import{_ as i,O as r,o,c as n,a as s,i as a,f as c}from"./chunks/framework.fmIt2z2h.js";const g=JSON.parse('{"title":"第六部分　运转与演化","description":"","frontmatter":{"title":"第六部分　运转与演化","xkChars":6175,"xkLessons":{"intro-06-part":{"title":"第六部分　运转与演化","lead":"“系统在运行”“系统收到反馈”“系统学会了”听起来相近，实际承诺的内容不同。第六部分把这些说法拆成可核的过程问题，防止一个响亮名称替代整条证据链。","explanation":["原文定位：第1294—1297行；原文锚点 part_6；短引文：‘机制名称本身不构成充分条件’。本题源切片逐字附后，讲解与原文分开。","本部分把对象合同展开为过程解释。对象合同说明边界、状态、关系、接口、时间、尺度及同一性判据；过程解释则要追问输入怎样经载体或通道改变后续状态，什么条件使该过程发生，哪些比较能排除其他解释。对象被清楚定义不等于过程机制已成立。","运转、反馈、学习、维护、负荷、相位和筛选不是可互换的叙事词。一次运转可以没有返回；返回造成改变不一定形成跨轮学习；维护身份或功能不一定是学习；负荷缺口不一定形成持久损伤；相位变化不自动是对象转换；差异结果也不自动构成反复筛选。","每个条件机制要分别给推理前提、使能条件、机制链、最低证据、反事实/竞争解释与停止位置。“定义要求什么”与“现实为什么发生”也分开：方法门规定分析怎样核查，并不是添加一个世界中的物理原因。","只有依赖、条件、最低证据和竞争解释的检验同时相称通过，才在指定SP、T和K范围内登记机制实例。SP是尺度剖面，T是窗口，K是同一性判据而非全部对象合同。字段齐全、名称正确或故事连贯，不代替实际证据。已有领域研究仍保留自身结论与范围，不因没有正式框架身份而作废。","本部分同时限制外推：有效不等于变好，持久不等于应该维持，筛选保留不等于优越，修复可行不等于有权实施。经验机制与规范评价、责任和行动许可分别判断；证据不足时保留候选和具体缺口，不把未知补成失败已证或成功已证。"],"distinctions":[{"leftTitle":"机制名称","leftText":"指向一组应满足的条件与材料。","rightTitle":"机制实例支持","rightText":"这些条件在具体对象与范围内有实际依据。"},{"leftTitle":"推理依赖/方法门","leftText":"说明如何组成和检验论证。","rightTitle":"经验原因","rightText":"世界中的作用通道，不能由方法名称产生。"},{"leftTitle":"过程起作用","leftText":"对后续状态有相应影响。","rightTitle":"净收益与正当性","rightText":"还需预定任务、代价和规范比较。"}],"boundaries":["本导语不是整部的替代摘要；后面每个机制仍须独立解释其特有条件。","不存在靠定义名称自动完成的现实机制认证。","同一事件可涉及多个机制，但同一材料被重复引用不变成多份独立证据。"],"questions":["一次返回造成状态改变，为什么不直接叫学习？","某机制得到有限支持，能否推出它值得永久维持？","为什么机制要绑定SP/T/K？"],"diagramPath":"/reading-assets/S-6-1/figures/intro-06-part.png","caseLinks":[],"caseNotes":[],"sourceRefs":[{"section":"intro-06-part","start_line":1294,"end_line":1297,"startLine":1294,"endLine":1297}],"outputId":"intro-06-part","sourceHash":"df579dbdbb68442b1781b066606c267761f0a1673fbd034ce93eeeb41641439f","argumentSteps":["把日常叙述拆成具体机制主张，不用一个名称包办全部过程。","声明对象合同及SP/T/K范围，再写过程变量和通道。","列该机制自己的依赖、使能条件、链条与最低材料。","用相称反事实、竞争解释和失败条件检查主张。","把已支持领域结论、正式机制资格、候选和未知分别报告。","超出窗口、尺度、身份或主张范围时停止外推；评价与行动另交规范/权限程序。"],"teachingExamples":[{"title":"教学构造：同样叫“改进”，其实有三个问题","text":"虚构装置收到输出误差信号并改变下一次控制量，只说明可能有一次反馈；若参数每回合清零，不能据此证明跨回合学习。另有人更换磨损零件并使预定功能继续保持，这是维护问题。三者可以同时出现，但必须分别核返回、保留调用和维护比较，不能统称“系统进化了”就结束。","assumptions":"装置、行为和条件均为构造，不是假设真实实验成功；每项机制是否正式成立还需自己的材料。","boundary":"不从行为改变推整体净益、价值进步或操作权限。"}],"counterexamples":[{"identity":"constructed_boundary","text":"系统运行多年，因此已经证明学习、维护、筛选和共演化全部成立。","effect":"长期存在不足以满足这些不同机制的特有条件。","sourceIds":["theory"]},{"identity":"constructed_boundary","text":"一个方法门通过，所以它被当作导致系统变化的新经验原因。","effect":"方法责任和对象层因果关系混淆，须分别登记。","sourceIds":["theory"]}],"questionAnswers":[{"question":"一次返回造成状态改变，为什么不直接叫学习？","answer":"学习还要求更新被保留/调用及任务比较等材料，一次反馈不自动具备。","basis":"本节原文及上述公开推导"},{"question":"某机制得到有限支持，能否推出它值得永久维持？","answer":"不能，经验效应与规范选择、成本、保护和权限分开。","basis":"本节原文及上述公开推导"},{"question":"为什么机制要绑定SP/T/K？","answer":"尺度、时间和身份条件限制结论范围，离开这些条件不能直接沿用原支持。","basis":"本节原文及上述公开推导"}],"figures":[{"path":"/reading-assets/S-6-1/figures/intro-06-part.png","alt":"反馈，返回造成后续改变，不自动形成学习；学习，更新保留并实际调用，任务与净益另分开；维护，指定通道影响K/F保持，不自动产生存续义务；负荷，同型需求与容量，即时缺口不必累积损伤；相位，同一K内区间与阈值，不自动对象转换；筛选，变异、差异保留、再生产，不自动更优或正当。六卡是六类条件机制，不是阶段阶梯；运转登记提供过程材料，正式支持须各自证据。","caption":"六卡是六类条件机制，不是阶段阶梯；运转登记提供过程材料，正式支持须各自证据。"}],"diagramBrief":"当前交付为静态图；交互尚未实现，以下涉及选择、切换或点击的内容仅为后续设计设想。六卡导航不画自动升级箭头。K为同一性判据，F为本次功能判据；图不认证任何现实机制。","applicability":{"realCase":"not_applicable","diagram":"applicable","reason":"分部导语说明条件机制的阅读方法，使用明确构造辨认问题，不强贴未经完整识别的历史机制。"},"openQuestions":[],"taskId":"S-6-1","sources":[{"id":"theory","title":"Xikari-条件结构与转化论，用户提供原文","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"现行全文第1294—1301行；每节精确范围见sourceRefs","claim_support":["intro-06-part：术语、合同、论证责任和原文边界；不据此认证经验事实","6.1：术语、合同、论证责任和原文边界；不据此认证经验事实"],"limits":["作者理论文本，是被解释对象，不替代外部经验资料；技能5.3.1不等于理论版本。"],"access_status":"read"},{"id":"nasa114-operation","title":"NASA STS-114：影像评估与填隙条移除","url":"https://www.nasa.gov/mission/sts-114/","source_type":"primary","version_or_date":"任务2005-07-26—08-09；网页2025-05-01更新","locator":"Mission Highlights，gap fillers叙述与EVA No.3段","claim_support":["6.1：影像发现突出填隙条，任务管理者评估行动，2005年8月3日Robinson实际拔除。"],"limits":["机构任务记录覆盖这次操作；不证明全部改进长期净益或正式G实例。"],"access_status":"partially_read"},{"id":"theory-d0","title":"Xikari3.1：对象接口与K","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"第425—448行","claim_support":["导语及6.1：完整对象声明含B/X/R/I/T/SP/K；K仅为同一性判据。"],"limits":["定义不预证对象有效。"],"access_status":"read"},{"id":"theory-history","title":"Xikari4.5：历史形成、载体与条件增量","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"第620—640行","claim_support":["6.1：三条历史问题分开，当前载体充分可无额外历史增量；不可遗漏已知当前状态。"],"limits":["形式模型不替现实路线取证。"],"access_status":"read"},{"id":"theory-scale","title":"Xikari3.4与4.8.5：跨尺度与证据责任","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"第473—494行；第698—700行","claim_support":["6.1：跨尺度需对象/变量/任务的D3/E5映射，不由名称或局部结果替代。"],"limits":["这里只说明责任，不认证真实尺度迁移。"],"access_status":"read"}],"lecturePath":"/reading-assets/S-6-1/lecture.md","sourcesPath":"/reading-assets/S-6-1/sources.json","sourceSlicePath":"/reading-assets/S-6-1/source-slice.md","supplementaryFiles":[],"diagramsPath":"/reading-assets/S-6-1/diagrams.md"},"6.1":{"title":"6.1　运转登记","lead":"要解释一次运转，不能只记开始和结束。要把东西从哪里来、走哪条路、何处改变、有没有另一条路以及哪些地方没看见，都放进记录。","explanation":["原文定位：第1298—1301行；原文锚点 section-6-1；短引文：‘让每一处时延、损耗、替代通道、证据断点和外推边界可被检验’。本题源切片逐字附后，讲解与原文分开。","最低登记项是输入、指定载体或通道、状态转移、输出、环境条件、时间窗和可能留痕。输入与输出按所选对象边界区分；输出并不必然是最终社会结果。载体是什么、通道怎样传导、状态哪些字段改变，要有具体指向，不能只写“系统处理了”。","“可能留痕”不表示每次运转都必须永久保存记忆。可以没有持久痕迹，也可以只留短暂状态；但若声称痕迹支持后续作用，就须定位载体、保留窗口和调用，而不是把一份日志存在当成整条机制。","若输出返回，要另登记返回通道、接收位置和被改变字段。返回信号究竟由先前输出形成，还是独立外来输入，必须说清；信号到达与后续字段变化也不能合并。基础运转登记不直接证明有效反馈，正式机制另按6.2的条件比较。","跨期作用先按4.5分三问：过去怎样形成当前状态；当前载体如何保留、更新并影响后续结果；给定当前注册状态后，历史是否仍提供额外条件增量。前两者不硬需G3，只有第三问需要比较历史感知模型与当前状态充分模型，并承担相应历史增量合同。","跨尺度时另完成D3/E5映射：源与目标对象、任务、变量、保持/改变/损失及误差要相容。仅仅记录了两层名称不能代替映射，局部作用也不能自动升成整个组织或总体的效果。","这些登记项不是把真实过程强制写成单向直线。可以有并行输入、分叉、环路、共享条件和替代路径；逐条指定时延、损耗、容量或边界，让每处能被观察、比较或保留未知。若某段证据断开，应指出它限制的结论，不以最终输出正常倒推所有中间通道无误。","过程登记应连同窗口和外推边界一起使用。一次执行可支持该轮发生了什么，不单独证明长期稳定、持续学习、全面修复或净收益。未观察时段与缺失字段保留类型，不让过程图的连线成为未经材料支持的证明。"],"distinctions":[{"leftTitle":"输出","leftText":"当前对象边界和窗口下的结果。","rightTitle":"长期最终效果","rightText":"需另有跨期材料与目标，不由一次输出保证。"},{"leftTitle":"留痕","leftText":"某载体保存了记录或状态。","rightTitle":"后续作用","rightText":"痕迹被调用并影响预定结果，还须证据。"},{"leftTitle":"返回信号","leftText":"来自先前输出/状态的反馈路径。","rightTitle":"独立输入","rightText":"可能同样改变系统，却不是该返回通道。"},{"leftTitle":"过程登记","leftText":"使路径和缺口可检查。","rightTitle":"线性链假设","rightText":"不是登记要求，可有网络、环路和并行通道。"}],"boundaries":["不把所有跨期作用都要求G3，也不以G3未过证明载体路线成立。","没有留痕不自动取消一轮运转或短暂反馈；持久主张才需要相称保存材料。","正常输出可由替代通道补偿，不能反推每条原路径均正常。","过程示例不是现实机制认证，行动仍需独立权限与保护。"],"questions":["库存例为什么是4而非3或5？","计划字段已改，下一轮实际输出就能写改善了吗？","所有跨期作用都需要历史感知模型比较吗？","过程登记一定要画成直线吗？"],"diagramPath":"/reading-assets/S-6-1/figures/section-6-1.png","caseLinks":[{"title":"STS-114：影像、分析和实际动作有不同位置","href":"https://www.nasa.gov/mission/sts-114/"}],"caseNotes":[{"title":"STS-114：影像、分析和实际动作有不同位置","text":"NASA的STS-114任务记录描述，2005年飞行中影像显示两处突出填隙条，任务管理者随后研究是否需要处理；8月3日Robinson在舱外活动中将它们拔除。记录把观测、分析/决定与执行分开，不能只以“获得影像”代替已经完成动作。","sourceLabel":"NASA STS-114任务页，2025-05-01更新","sourceUrl":"https://www.nasa.gov/mission/sts-114/","sourceLocator":"Mission Highlights：影像与gap fillers段、EVA No.3段；任务2005-07-26至08-09","boundary":"支持该次影像及移除动作的机构任务记录；不由一次操作证明全部安全改进有效、长期学习或完整正式反馈实例。","href":"https://www.nasa.gov/mission/sts-114/"}],"sourceRefs":[{"section":"6.1","start_line":1298,"end_line":1301,"startLine":1298,"endLine":1301}],"outputId":"section-6-1","sourceHash":"df579dbdbb68442b1781b066606c267761f0a1673fbd034ce93eeeb41641439f","argumentSteps":["结果前固定对象边界、任务、变量、时间窗及环境，明确输入与输出口径。","为每条载体/通道指定起点、终点、传导内容与状态更新规则。","登记并行和替代路径、时延、损耗与可能留痕，不强制单链。","有返回时追到原输出、接收位置与被改变字段，再按反馈责任比较。","有跨期主张时选历史形成、载体传递或额外历史增量路线，分别列材料。","有跨尺度主张时补D3/E5对象和变量桥，保留任务相关损失。","逐段说明可核事实、证据断点和外推上限，不用正常终点补造中间过程。"],"teachingExamples":[{"title":"数学构造：并行输入与损耗都影响状态登记","text":"虚构容器初始库存x=5，两条输入通道u₁=2、u₂=1，本轮交付输出q=3，环境泄漏ℓ=1。约定所有量同单位且同一窗口，输入先到位、交付和泄漏合计不超过可用量，更新为x′=x+u₁+u₂−q−ℓ=4。若只登记第一通道，会错误预测3；若漏记泄漏，会预测5。终点4不能单独告诉我们是哪组输入与损耗造成它，必须核过程材料。","assumptions":"精确非负库存模型，无额外未登记流量；所有数字为人为设定，不是真实设备观测。","boundary":"只证明记账映射，不据此识别现实因果或容量长期稳定。"},{"title":"教学构造：返回要追到输出来源","text":"沿用虚构容器，设预定交付目标r=4，比较器读取本轮实际q=3算出e=r−q=1，沿指定通道返回调度位置，并将下一轮第一通道计划u₁从2改为3。登记应分别保留q、e来源、接收位置和计划字段变化。若计划尚未执行，不能宣布下一轮实际交付已提高；若信号只是外部独立通知，也不能冒充由q返回。","assumptions":"目标、比较器和计划规则全为构造；只声明计划字段按规则更新，不假定执行和未来收益。","boundary":"实际反馈、后续交付和持久学习要按各自材料判断。"},{"title":"数学构造：当前载体充分时无需额外历史","text":"设状态s按s′=0.5s+u更新，两段历史(4,0)与(0,2)从0出发均到当前s=2。下一输入同为0时都到1；过去输入已影响当前s，但给定完整s后无须额外历史才能算下一步。若只存“是否s>0”，历史可能补回丢失差异，那是表示选择要公开的问题。","assumptions":"精确固定规则与完整当前s；没有真实历史效应检测。","boundary":"不从模型充分性推出现实当前状态已充分，现实载体与历史路线须分别取证。"}],"counterexamples":[{"identity":"constructed_boundary","text":"最终交付正常，所以所有原通道都没有故障。","effect":"替代通道可能补偿，终点不能唯一恢复路径。","sourceIds":["theory"]},{"identity":"constructed_boundary","text":"收到一条通知后改变计划，就说这一定是输出反馈。","effect":"须追通知是否确由先前输出形成，否则可能是独立输入。","sourceIds":["theory"]},{"identity":"constructed_boundary","text":"有一份运行日志，所以已证明长期学习和风险下降。","effect":"留痕、调用、任务结果与净益分别需要证据。","sourceIds":["theory"]}],"questionAnswers":[{"question":"库存例为什么是4而非3或5？","answer":"两路输入都到位且有泄漏：5+2+1−3−1=4；3漏了第二路，5漏了泄漏。","basis":"本节原文及上述公开推导"},{"question":"计划字段已改，下一轮实际输出就能写改善了吗？","answer":"不能，须核计划进入执行和实际结果，不能让字段更新代替未来观测。","basis":"本节原文及上述公开推导"},{"question":"所有跨期作用都需要历史感知模型比较吗？","answer":"不需要。只有当前注册状态之外的额外历史增量主张需要相应比较；形成和载体传递另有路线。","basis":"本节原文及上述公开推导"},{"question":"过程登记一定要画成直线吗？","answer":"不必，可以登记并行、返回、分叉和替代通道，关键是每段有可核身份与边界。","basis":"本节原文及上述公开推导"}],"figures":[{"path":"/reading-assets/S-6-1/figures/section-6-1.png","alt":"输入，u1=2，u2=1，两条并行通道；指定通道与时序，同单位／同窗口，输入先到位；状态更新，x=5，x′=5+2+1−3−1=4；输出，本轮交付q=3，不等于长期净效果；环境条件，本轮泄漏1，不能静默遗漏；可能返回与留痕，来源／接收／改变字段，是否执行仍另查。图中数字均为虚构库存模型；环境和返回卡是额外登记项，不用一条线替代真实网络。","caption":"图中数字均为虚构库存模型；环境和返回卡是额外登记项，不用一条线替代真实网络。"}],"diagramBrief":"当前交付为静态图；交互尚未实现，以下涉及选择、切换或点击的内容仅为后续设计设想。六卡保留输入、通道、状态、输出、环境和返回/留痕。箭头是记录顺序示意，正文公式与时序给定实际模型。","applicability":{"realCase":"applicable","diagram":"applicable","reason":"具体任务记录提供从观测到执行的不同环节，适合运转登记；图和库存算例另为明确构造，不假造NASA数值。"},"openQuestions":[],"taskId":"S-6-1","sources":[{"id":"theory","title":"Xikari-条件结构与转化论，用户提供原文","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"现行全文第1294—1301行；每节精确范围见sourceRefs","claim_support":["intro-06-part：术语、合同、论证责任和原文边界；不据此认证经验事实","6.1：术语、合同、论证责任和原文边界；不据此认证经验事实"],"limits":["作者理论文本，是被解释对象，不替代外部经验资料；技能5.3.1不等于理论版本。"],"access_status":"read"},{"id":"nasa114-operation","title":"NASA STS-114：影像评估与填隙条移除","url":"https://www.nasa.gov/mission/sts-114/","source_type":"primary","version_or_date":"任务2005-07-26—08-09；网页2025-05-01更新","locator":"Mission Highlights，gap fillers叙述与EVA No.3段","claim_support":["6.1：影像发现突出填隙条，任务管理者评估行动，2005年8月3日Robinson实际拔除。"],"limits":["机构任务记录覆盖这次操作；不证明全部改进长期净益或正式G实例。"],"access_status":"partially_read"},{"id":"theory-d0","title":"Xikari3.1：对象接口与K","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"第425—448行","claim_support":["导语及6.1：完整对象声明含B/X/R/I/T/SP/K；K仅为同一性判据。"],"limits":["定义不预证对象有效。"],"access_status":"read"},{"id":"theory-history","title":"Xikari4.5：历史形成、载体与条件增量","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"第620—640行","claim_support":["6.1：三条历史问题分开，当前载体充分可无额外历史增量；不可遗漏已知当前状态。"],"limits":["形式模型不替现实路线取证。"],"access_status":"read"},{"id":"theory-scale","title":"Xikari3.4与4.8.5：跨尺度与证据责任","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"第473—494行；第698—700行","claim_support":["6.1：跨尺度需对象/变量/任务的D3/E5映射，不由名称或局部结果替代。"],"limits":["这里只说明责任，不认证真实尺度迁移。"],"access_status":"read"}],"lecturePath":"/reading-assets/S-6-1/lecture.md","sourcesPath":"/reading-assets/S-6-1/sources.json","sourceSlicePath":"/reading-assets/S-6-1/source-slice.md","supplementaryFiles":[],"diagramsPath":"/reading-assets/S-6-1/diagrams.md"},"6.2":{"title":"6.2　CM-FEEDBACK 有效反馈","lead":"收到意见、收到警报、保存一份报告，都还不是本节所说的有效反馈。要看先前输出怎样绕回来，以及这条返回确实使下一步哪里不同。","explanation":["原文定位：第1302—1311行；原文锚点 section-6-2；短引文：‘有效反馈只说明返回造成了一次后续改变’。本题源切片逐字附后，讲解与原文分开。","本机制把D2的定义展开成经验责任。D2告诉我们什么叫有效反馈，G2负责识别指定返回通道的作用；E4、CAUSAL、EVIDENCE规定竞争解释、因果识别和材料审查的方法，不是造成世界变化的额外原因。基础反馈不要求G3，也不要求永久保存历史。","使能条件有三个不可省略的连接。第一，信号须来自先前状态或输出，且经具名通道进入后续过程。第二，与无返回或阻断条件相比，至少一个预先登记的后续状态、转移概率或约束发生超过阈值的差异。第三，时间顺序与改变字段须在结果前登记，不能看到哪里变了再把哪里改成目标。","机制链依次是先前状态/输出、返回信号、指定通道传导、接收位置摄取、后续字段改变、阻断反事实复核。前五项描述所主张的作用路径；最后一项是检验路径的比较责任，不是必须在每次实际运行末尾再发生一次物理阻断。只有连线图而无各段材料，仍是候选解释。","正式最低证据包括通过预注册门的G2-instance、返回通道及接收位置、时间顺序、被改变字段、后续差异和相称的无返回/阻断比较。受控干预、受控扰动或具识别条件的自然变异要依预选方案处理；不能为确认现实反馈而要求随意关闭安全通道。可以先分析合适的既有材料；实验本身另需权限与风险审查。","三类失败位置不同：信号确实到达但后续转移不变，说明不能把接收冒充作用；共同外来输入足以解释所见变化，说明这条返回尚未被区分；切断指定返回后差异保持，则不支持它承担所称差异。替代通道补偿、干预未真正生效和测量不敏感仍须核对，不由一次不显著直接证明“任何反馈都不存在”。","有效仅指返回有作用，不是褒义评价。它可能纠偏，也可能放大误差、延迟决策或造成损失；一次有效返回不自动构成跨轮学习、修复或净收益。6.2.1通过一个完全给定的数学模型，专门证明“第一步改变相同”与“长期稳定不同”可以同时成立。模型内比较不是现实G2实例资格。","领域报告中的过程事实和因果研究仍按其自身材料保留。未提供本框架的完整实例合同，不取消已经发生的规则更改或实际执行；同样，也不能由这些事实追授全部指定机制和长期效果。结论应明确写成已观察的改变、机制候选及仍未识别的部分。"],"distinctions":[{"leftTitle":"信号到达","leftText":"接收器有了该信号，可能只生成回执。","rightTitle":"有效反馈","rightText":"指定返回使预定后续字段出现可识别差异。"},{"leftTitle":"返回作用","leftText":"可以来自固定规则，且只发生一次。","rightTitle":"学习","rightText":"另需更新保留、实际调用和任务比较等条件。"},{"leftTitle":"无返回反事实","leftText":"帮助区分该通道作用的比较条件。","rightTitle":"必须现实强行断开","rightText":"不是逻辑要求，现实测试仍受安全、权限与可行性约束。"},{"leftTitle":"方法门","leftText":"约束如何检验与处理竞争解释。","rightTitle":"对象原因","rightText":"实际传导变化的通道或条件。"}],"boundaries":["形式模型中的参数阻断可精确计算，但不自动验证现实通道或实验可实施性。","只测得本轮某状态变化，不顺带获得通道容量、可靠性、成本和长期效果的结论。","负面或振荡的结果也可能包含有效反馈；有效不等于有益。","正向门未通过时，可有反证也可有测量不足；要分别记录，不把未决当零作用已证。"],"questions":["某回执按时生成，但后续排程与无返回时完全相同，可直接登记有效反馈吗？","每回合清零的控制器按实际输出误差调整一次，为什么仍可能有有效反馈？","阻断后差异不变，是不是已经证明零作用？","已知一次反馈令误差变大，能否仍称有效？"],"diagramPath":"/reading-assets/S-6-2/figures/section-6-2.png","caseLinks":[{"title":"马里兰续保：程序更改与完整通道识别要分开","href":"https://health.maryland.gov/mmcp/Documents/JCRs/2023/eligibilityredetprocessJCRfinal4-24.pdf"}],"caseNotes":[{"title":"马里兰续保：程序更改与完整通道识别要分开","text":"马里兰卫生部门2024年报告回顾，2023年8月CMS澄清应按个人而非家庭进行基于现有数据的续保；该州随后记录系统调整，并明确新流程自2023年11月开始实际使用。本节新增观察点是从问题返回到后续执行的材料位置：不能只凭报告收到就说有作用，也不应抹去已记录的实际流程变化。","sourceLabel":"Maryland FY24 Quarter 4报告，2024-05-14提交","sourceUrl":"https://health.maryland.gov/mmcp/Documents/JCRs/2023/eligibilityredetprocessJCRfinal4-24.pdf","sourceLocator":"印刷pp.8–9，Medicaid Mitigation of Ex Parte Renewals，末段updated process was utilized beginning November 2023","boundary":"行政自报支持这段问题说明与流程使用事实；本段未提供预注册G2、单独阻断比较或长期健康效果识别，不追授正式反馈实例，也不是当前资格建议。","href":"https://health.maryland.gov/mmcp/Documents/JCRs/2023/eligibilityredetprocessJCRfinal4-24.pdf"}],"sourceRefs":[{"section":"6.2","start_line":1302,"end_line":1311,"startLine":1302,"endLine":1311}],"outputId":"section-6-2","sourceHash":"df579dbdbb68442b1781b066606c267761f0a1673fbd034ce93eeeb41641439f","argumentSteps":["先登记对象、窗口、目标字段、返回起点与接收位置，确认信号不是独立外来输入。","列D2/G2推理责任，单列E4/CAUSAL/EVIDENCE方法责任；不增设基础反馈必须G3的门。","在结果前固定主比较、阈值、时间顺序及所测通道维度，并检查执行版本。","依材料追踪传导、摄取和后续变化，区分到达、留痕与作用。","使用相称的无返回、阻断或具识别条件的替代比较，处理共同输入、替代通道和测量变化。","证据不足只登记候选及缺口；零结论另需其规则、灵敏度和容差。","对已支持作用另问稳定、学习、目标改善、损失分布与权限，不用“有效”包办。"],"teachingExamples":[{"title":"数学构造：短暂反馈成立，永久记忆不存在","text":"设每回合装置输出a=0，目标r=1；比较器读取实际a并生成e=r−a=1，经返回通道到控制器，控制器按a←a+e更新为1。阻断返回时规则无输入，a仍为0；以本轮输出差异大于0.5为预定模型判据，差异1通过。每回合结束后全部状态清零，下一回合重复，且不保留参数、日志或经验。于是该构造有本轮返回作用，却没有由保留更新形成的跨回合学习。","assumptions":"精确确定性规则，返回是唯一更新来源，阻断不改变其他条件；全为数学设定而非真实装置试验。","boundary":"不能以算例声称现实G2已识别；没有跨回合记忆不取消本轮作用。"},{"title":"数学构造：共同输入会伪装成反馈","text":"设外部变量U取0或1；警报R=U，后续动作Y=U。观察可见R=Y，但若仅切断警报连线而保持U和动作规则不变，Y依然等于U。警报与动作同源，观察相关不足以证明R造成Y。若另把真实规则改为Y=R，则才得到另一种模型，不能在结果后偷换。","assumptions":"变量与干预含义完全人为给定，U同时影响两端；比较只删除R到接收端的信息。","boundary":"现实是否存在共同输入、替代通道或干预副作用，需材料，不由这个例子预判。"}],"counterexamples":[{"identity":"constructed_boundary","text":"意见被存入数据库，下一轮所有字段仍按旧规则执行，却称“反馈已闭环”。","effect":"存档可证明留痕，不证明后续作用。","sourceIds":["theory"]},{"identity":"constructed_boundary","text":"关闭一条返回通道后表现不变，于是宣布整个系统没有反馈。","effect":"其他路径补偿或干预失败可能仍在；只能在已核条件内评价指定主张。","sourceIds":["theory"]},{"identity":"constructed_boundary","text":"第一步误差下降，便宣布稳定、学习和修复全部完成。","effect":"这些是不同任务，子节将给稳定性相反的明确模型。","sourceIds":["theory"]}],"questionAnswers":[{"question":"某回执按时生成，但后续排程与无返回时完全相同，可直接登记有效反馈吗？","answer":"不能，仅有到达/记录；须核预定后续字段是否因指定返回而改变。","basis":"本节原文及上述公开推导"},{"question":"每回合清零的控制器按实际输出误差调整一次，为什么仍可能有有效反馈？","answer":"返回造成本轮差异即可；持久历史留痕不是基础反馈必要条件。","basis":"本节原文及上述公开推导"},{"question":"阻断后差异不变，是不是已经证明零作用？","answer":"不自动。需核阻断成功、替代通道、比较灵敏度及预定零结论规则；否则可能只是不支持该主张或未决。","basis":"本节原文及上述公开推导"},{"question":"已知一次反馈令误差变大，能否仍称有效？","answer":"可在作用被识别时称有效，但目标改善不成立；应分别报告作用与不利结果。","basis":"本节原文及上述公开推导"}],"figures":[{"path":"/reading-assets/S-6-2/figures/section-6-2.png","alt":"先前状态或输出，可追踪的来源，不是独立外来输入；返回信号与通道，传导至指定位置，记录时序与版本；接收与后续字段，到达不等于改变，核状态／概率／约束；比较责任，无返回或阻断，执行与副作用须核；竞争解释，共同输入／替代通道，测量与选择变化；支持上限，本轮返回有作用，学习／稳定／净益另查。上排是候选作用链；下排是检验责任与结论边界，不是额外物理原因。","caption":"上排是候选作用链；下排是检验责任与结论边界，不是额外物理原因。"}],"diagramBrief":"当前交付为静态图；交互尚未实现，以下涉及选择、切换或点击的内容仅为后续设计设想。六卡分开实际作用链与比较责任；缺少后续差异或相称识别时保留候选，不自动支持零作用。","applicability":{"realCase":"applicable","diagram":"applicable","reason":"真实行政报告用于区分问题返回、系统改变及实际使用，不伪装完整G2机制认证；短暂控制与共同原因另用明确构造。"},"openQuestions":[],"taskId":"S-6-2","sources":[{"id":"theory","title":"Xikari-条件结构与转化论，用户提供原文","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"现行全文第1302—1319行；每节精确范围见sourceRefs","claim_support":["6.2：术语、合同、论证责任和原文边界；不据此认证经验事实","6.2.1：术语、合同、论证责任和原文边界；不据此认证经验事实"],"limits":["作者理论文本，是被解释对象，不替代外部经验资料；技能5.3.1不等于理论版本。"],"access_status":"read"},{"id":"maryland-renewal","title":"Maryland FY24 Quarter 4 Medicaid Redetermination报告","url":"https://health.maryland.gov/mmcp/Documents/JCRs/2023/eligibilityredetprocessJCRfinal4-24.pdf","source_type":"primary","version_or_date":"报告April 2024；提交封信2024-05-14","locator":"印刷pp.8–9（PDF第12–13页），Medicaid Mitigation of Ex Parte Renewals","claim_support":["6.2：2023年8月个人续保要求的澄清、州系统调整、新流程2023年11月开始实际使用。"],"limits":["行政报告未提供此处所需完整G2合同或独立通道阻断识别；不延伸当前资格或长期健康结果。"],"access_status":"partially_read"},{"id":"theory-d2","title":"Xikari3.3：D2有效反馈","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"第462—471行","claim_support":["6.2：返回、接收、后续字段与无返回比较；一次作用、稳定和目标改善分开。"],"limits":["定义不是现实反馈的经验凭证。"],"access_status":"read"},{"id":"theory-g2","title":"Xikari4.4：G2指定通道","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"第610—619行；四态责任见第577—581行","claim_support":["6.2：G2预选主张、通道维度分别测量；正向未过不等于零作用支持。"],"limits":["保留既有领域证据身份，不追授正式资格。"],"access_status":"read"},{"id":"theory-c10","title":"Xikari附录C.10：固定时延反馈严格稳定条件","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"第4470—4493行","claim_support":["6.2.1：特征多项式、小正增益稳定、单位圆边界与向外交叉证明；四种延迟临界值。"],"limits":["只约束公开固定线性模型，不提供现实参数处方。"],"access_status":"read"}],"lecturePath":"/reading-assets/S-6-2/lecture.md","sourcesPath":"/reading-assets/S-6-2/sources.json","sourceSlicePath":"/reading-assets/S-6-2/source-slice.md","supplementaryFiles":[{"title":"delay-trajectories.csv","path":"/reading-assets/S-6-2/figures/delay-trajectories.csv"}],"diagramsPath":"/reading-assets/S-6-2/diagrams.md"},"6.2.1":{"title":"6.2.1　反馈时延与稳定区间","lead":"同样的纠偏力度，回应越晚，可能越容易来回过冲。这里不是凭经验喊“慢了就危险”，而是在一个假设完全公开的小模型里，算出精确的稳定范围。","explanation":["原文定位：第1312—1319行；原文锚点 section-6-2-1；短引文：‘等号不包含在稳定区内’。本题源切片逐字附后，讲解与原文分开。","模型是x_{t+1}=x_t−k x_{t−d}。x是相对目标的有符号、无量纲偏差，k是固定实数增益，d是固定非负整数延迟，采样步长固定；指定有限初始历史x_{−d},… ,x_0后，后续轨迹唯一。它没有外部冲击、测量噪声、执行饱和和状态边界。负x只表示越过目标，并不代表负任务数量。","所证结论是：对所有有限初始历史，零解渐近稳定，当且仅当0<k<k_c(d)，其中k_c(d)=2sin[π/(4d+2)]。渐近稳定要求小偏差不因演化失控且长期趋零；对该有限维固定线性系统，可用全部特征根模长严格小于1刻画。不是只选一条好看的初始轨迹，也不是仅观察有限几步下降。","把当前和延迟状态一起存为z_t=(x_t,x_{t−1},…,x_{t−d})，递推成为固定矩阵的z_{t+1}=Az_t。代入模态x_t=λ^t，得特征多项式p(λ,k)=λ^{d+1}−λ^d+k。若所有根在单位圆内，各模态衰减；即使有重根，多项式t因子乘上严格小于1的指数也趋零。若有根模长≥1，则存在相应实初始历史的不衰减或增长模态，不能满足“所有历史趋零”。","先排除k≤0。k=0时有根1，且任意非零常值历史会保持，故不渐近稳定。k<0时p(1,k)=k<0，而正λ充分大时p>0，由连续性至少有一个实根λ>1。d=0另可直接看x_{t+1}=(1−k)x_t：|1−k|<1恰为0<k<2。","对d≥1的充分小正k，k=0时根1是单根，由隐式求导向内移动为λ=1−k+O(k²)，其余d个根原在0附近，连续变化仍在圆内。因此至少有一个小正增益稳定区。要找它何时结束，不能只做若干浮点试算，须找特征根首次触及单位圆的参数。","令边界根λ=e^{iθ}，0<θ<2π。由p=0可写k=λ^d(1−λ)=2sin(θ/2)exp{i[(d+1/2)θ−π/2]}。由于sin(θ/2)>0，k为正实数要求相角为2π整数倍，所以θ=(π+4πm)/(2d+1)，m=0,…,d。所有可能正边界中最小的2sin(θ/2)来自最小角θ=π/(2d+1)及其共轭角，得到k_c=2sin[π/(4d+2)]。根随k连续且在有限参数区有界；离开单位圆前必须经过这些边界，故0<k<k_c内稳定。","必要性还要排除“出去后又回来”。边界处p_λ=λ^{d−1}[(d+1)λ−d]不为0，因为((d+1)λ=d)要求|λ|=d/(d+1)<1；故单位圆根都是单根。由p=0求导得λ′/λ=(λ−1)/{k[(d+1)λ−d]}。将分子分母乘以分母的共轭并取实部，分子实部为(2d+1)(1−cosθ)，于是d log|λ|/dk=(2d+1)(1−cosθ)/{k|(d+1)e^{iθ}−d|²}>0。每次正增益交叉都向圆外，没有向内回入，因此大于首个边界不可能重新全部稳定。d=0已由直接式处理。","在k=k_c处至少有单位模根，存在不衰减模态，所以等号排除；不能因为数值误差算出0.999999…就纳入。超过边界存在增长模态，不表示所有历史都增长：全零历史始终为零，其他恰好不含不稳定模态的特殊历史也可能不同。这里的“系统不稳定”是全体历史的性质，不等于每条曲线发散。","固定k=0.8，d=0、1、2、3的临界值分别为2、1、约0.618034和0.445042，前两者稳定，后两者不稳定。若各自所需初始历史全为1，第一步均为1−0.8=0.2；完全阻断时k=0，轨迹始终为1。返回第一步已造成差异0.8，但长期稳定性质不同，故“有作用”与“稳定”非等价。","更细看d=1的前三个更新值0.2、−0.6、−0.76：系统虽渐近稳定，绝对偏差仍可在相邻步增加，且发生过冲。稳定不保证逐步下降、有限时窗内达到任意容差、瞬态峰值安全或执行代价可承受。后面图只显示t=0…24的模型计算，长期结论来自证明，不来自看曲线。","现实使用必须另核误差定义、采样频率、延迟是否固定、执行器饱和、服务约束、外部输入和人员策略反应。现实队列有非负任务数、异质服务与需求，制度纠偏还有权限与代价；这些都没有被本式建模。因而本节不能直接给现实流程开一个k=0.8的处方。"],"distinctions":[{"leftTitle":"反馈有效","leftText":"相对阻断，返回已改变后续状态。","rightTitle":"渐近稳定","rightText":"全部有限初始历史随时间趋于零且满足该线性稳定性质。"},{"leftTitle":"系统不稳定","leftText":"存在不衰减或增长模态。","rightTitle":"每条轨迹发散","rightText":"强得多且不成立，零历史就是反例。"},{"leftTitle":"渐近趋零","leftText":"足够长时间的性质。","rightTitle":"每步改善与峰值可接受","rightText":"是另外的有限时任务和约束。"},{"leftTitle":"有符号偏差","leftText":"负数表示越过目标。","rightTitle":"实际任务数量","rightText":"通常另有非负约束，不能直接等同。"}],"boundaries":["稳定区严格开区间，端点k=0及k=k_c均不包含。","仅有有限步轨迹不能证明全体历史渐近稳定；根分析和交叉方向承担该证明。","该判据只适用于固定离散延迟和固定实增益；时变延迟、随机扰动、非线性及饱和需要重做分析。","模型内返回作用不等于经验G2认证，也不提供现实行动权限。","四幅轨迹图横轴统一，纵轴范围按面板分别标明，不能用线条视觉斜率跨图比较幅度。"],"questions":["d=1、k=1是否满足严格渐近稳定？","为什么求出第一个单位圆交点还不足以证明所有更大k都不稳定？","d=3、k=0.8，全零初始历史保持零，是否推翻不稳定结论？","d=1序列0.2到−0.6，和渐近稳定矛盾吗？","现实处理队列测到平均延迟2步，能否直接用k<0.618034设控制参数？"],"diagramPath":"/reading-assets/S-6-2/figures/section-6-2-1.png","caseLinks":[],"caseNotes":[],"sourceRefs":[{"section":"6.2.1","start_line":1312,"end_line":1319,"startLine":1312,"endLine":1319}],"outputId":"section-6-2-1","sourceHash":"df579dbdbb68442b1781b066606c267761f0a1673fbd034ce93eeeb41641439f","argumentSteps":["公开有符号偏差、固定增益/延迟、有限初始历史及无噪声/无约束等模型前提。","扩展为有限维线性状态，说明全部根严格在单位圆内与全体历史衰减的等价。","用根1及大于1的实根排除k≤0，并独立求解d=0。","证明充分小正k稳定，再令单位圆根e^{iθ}求首个正边界。","根据正实数相角条件求θ与k_c，利用根连续性确认首个边界前的稳定区。","对边界根隐式求导，证明所有正k交叉向外，排除重新稳定。","排除等号并区分存在不稳定模态与每条轨迹增长；代入四种d核数值。","对照阻断与反馈第一步，再把作用、渐近稳定、瞬态指标和现实采用分别判断。"],"teachingExamples":[{"title":"数学构造：四种延迟第一步相同，后面不同","text":"设k=0.8且每种延迟所需初始历史全为1。t=0…4时，d=0的值为1、0.2、0.04、0.008、0.0016；d=1为1、0.2、−0.6、−0.76、−0.28；d=2为1、0.2、−0.6、−1.4、−1.56；d=3为1、0.2、−0.6、−1.4、−2.2。每项由前式递推，例如d=2的x₃=x₂−0.8x₀=−0.6−0.8=−1.4。图展示同一设定到t=24的全部整数步，另附[逐步计算CSV](figures/delay-trajectories.csv)。","assumptions":"纯数学计算，无外来输入、噪声、饱和和状态边界；所有初始历史按各自d完整给定。","boundary":"有限轨迹展示不替代上文充要条件证明，也不是设备或组织测量。"},{"title":"数学构造：稳定却不是每一步更好","text":"d=1、k=0.8处于0<k<1内。x₁=0.2，x₂=−0.6，所以|x₂|=0.6>|x₁|=0.2，逐步下降失败；若预定任务要求t=2时绝对偏差≤0.1，也失败。不能因渐近趋零改写这个期限要求。","assumptions":"全1初始历史；绝对误差和t=2阈值为显式教学任务，非现实安全阈值。","boundary":"最终收敛、限时达标、瞬态峰值和代价分别评价。"},{"title":"数学构造：边界与零历史","text":"d=0、k=2时x_{t+1}=−x_t，从x₀=1得到1、−1、1、−1，始终不趋零，说明等号不可包含。d=2、k=0.8虽超临界，但若x_{−2}=x_{−1}=x₀=0，递推一直为0，说明不稳定不意味着每条轨迹增长。","assumptions":"完全给定的递推与初始值；没有真实实验。","boundary":"零历史不能证明系统稳定，单个非衰减历史却足以反驳“所有历史趋零”。"}],"counterexamples":[{"identity":"source_counterexample","text":"观察第一步从1降为0.2，就断言延迟2步的系统稳定。","effect":"同一模型后续可增长；固定0.8大于该延迟的临界0.618034。","sourceIds":["theory"]},{"identity":"constructed_boundary","text":"在边界得到浮点根模0.9999999999999999，因此把等号算作稳定。","effect":"解析边界存在单位模根，数值误差不能改变严格条件。","sourceIds":["theory"]},{"identity":"constructed_boundary","text":"把负偏差解释为负排队人数，并直接部署纠偏增益。","effect":"变量身份和模型约束不相容，现实使用须独立识别与授权。","sourceIds":["theory"]}],"questionAnswers":[{"question":"d=1、k=1是否满足严格渐近稳定？","answer":"不满足，临界为1且等号排除，存在不衰减模态。","basis":"本节原文及上述公开推导"},{"question":"为什么求出第一个单位圆交点还不足以证明所有更大k都不稳定？","answer":"还需排除根重新向内穿越；边界径向导数始终为正承担这一步。","basis":"本节原文及上述公开推导"},{"question":"d=3、k=0.8，全零初始历史保持零，是否推翻不稳定结论？","answer":"不推翻。不稳定说明存在某些不衰减/增长模态，不说每条历史增长。","basis":"本节原文及上述公开推导"},{"question":"d=1序列0.2到−0.6，和渐近稳定矛盾吗？","answer":"不矛盾，渐近稳定不要求绝对误差逐步下降。","basis":"本节原文及上述公开推导"},{"question":"现实处理队列测到平均延迟2步，能否直接用k<0.618034设控制参数？","answer":"不能。平均延迟不等于固定延迟，任务非负、服务约束、冲击与执行权限也未验证；需独立模型与风险分析。","basis":"本节原文及上述公开推导"}],"figures":[{"path":"/reading-assets/S-6-2/figures/section-6-2-1.png","alt":"d=0，临界2，k=0.8：稳定，x1=0.2；d=1，临界1，k=0.8：稳定，x1=0.2；d=2，临界0.618034，k=0.8：不稳定，x1=0.2；d=3，临界0.445042，k=0.8：不稳定，x1=0.2。数学构造：k=0.8，初始历史全1；每面板t=0…24，纵轴分别标注；虚线k=0恒为1。","caption":"数学构造：k=0.8，初始历史全1；每面板t=0…24，纵轴分别标注；虚线k=0恒为1。"}],"diagramBrief":"当前交付为静态图；交互尚未实现，以下涉及选择、切换或点击的内容仅为后续设计设想。四面板逐步绘制同一递推的计算轨迹，横轴相同而纵轴不同。全部25个整数时点均显示，阻断基线恒为1；图形不替代解析稳定证明。","applicability":{"realCase":"not_applicable","diagram":"applicable","reason":"本节是完整假设下的数学命题，证明和可复算轨迹最能展示非等价；不强贴真实组织为该方程的已验证实例。"},"openQuestions":[],"taskId":"S-6-2","sources":[{"id":"theory","title":"Xikari-条件结构与转化论，用户提供原文","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"现行全文第1302—1319行；每节精确范围见sourceRefs","claim_support":["6.2：术语、合同、论证责任和原文边界；不据此认证经验事实","6.2.1：术语、合同、论证责任和原文边界；不据此认证经验事实"],"limits":["作者理论文本，是被解释对象，不替代外部经验资料；技能5.3.1不等于理论版本。"],"access_status":"read"},{"id":"maryland-renewal","title":"Maryland FY24 Quarter 4 Medicaid Redetermination报告","url":"https://health.maryland.gov/mmcp/Documents/JCRs/2023/eligibilityredetprocessJCRfinal4-24.pdf","source_type":"primary","version_or_date":"报告April 2024；提交封信2024-05-14","locator":"印刷pp.8–9（PDF第12–13页），Medicaid Mitigation of Ex Parte Renewals","claim_support":["6.2：2023年8月个人续保要求的澄清、州系统调整、新流程2023年11月开始实际使用。"],"limits":["行政报告未提供此处所需完整G2合同或独立通道阻断识别；不延伸当前资格或长期健康结果。"],"access_status":"partially_read"},{"id":"theory-d2","title":"Xikari3.3：D2有效反馈","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"第462—471行","claim_support":["6.2：返回、接收、后续字段与无返回比较；一次作用、稳定和目标改善分开。"],"limits":["定义不是现实反馈的经验凭证。"],"access_status":"read"},{"id":"theory-g2","title":"Xikari4.4：G2指定通道","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"第610—619行；四态责任见第577—581行","claim_support":["6.2：G2预选主张、通道维度分别测量；正向未过不等于零作用支持。"],"limits":["保留既有领域证据身份，不追授正式资格。"],"access_status":"read"},{"id":"theory-c10","title":"Xikari附录C.10：固定时延反馈严格稳定条件","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"第4470—4493行","claim_support":["6.2.1：特征多项式、小正增益稳定、单位圆边界与向外交叉证明；四种延迟临界值。"],"limits":["只约束公开固定线性模型，不提供现实参数处方。"],"access_status":"read"}],"lecturePath":"/reading-assets/S-6-2/lecture.md","sourcesPath":"/reading-assets/S-6-2/sources.json","sourceSlicePath":"/reading-assets/S-6-2/source-slice.md","supplementaryFiles":[{"title":"delay-trajectories.csv","path":"/reading-assets/S-6-2/figures/delay-trajectories.csv"}],"diagramsPath":"/reading-assets/S-6-2/diagrams.md"},"6.3":{"title":"6.3　CM-LEARNING 反馈介导学习","lead":"昨天听了意见，今天改了一下，不足以说明以后会用。反馈介导学习要追的是：什么被改了，靠什么留下来，后来究竟有没有调用，以及预定任务因此哪里不同。","explanation":["原文定位：第1320—1337行；原文锚点 section-6-3；短引文：‘当前载体传递与当前表示之外的历史增量是两个分别取证的分支’。本题源切片逐字附后，讲解与原文分开。","基础依赖是CM-FEEDBACK：先前状态或输出的返回确实造成变化；E4、CAUSAL、EVIDENCE提供审查方法。此后才问更新是否可定位、能保留且被后续使用。只把系统运行前后作对照，无法自动区分反馈学习、持续外部训练、成员更换或测量方式改变。","载体分支CM-LEARNING-carried有五段：有效反馈→内部更新→载体保留或持续更新→后续轮次实际调用→预定任务结果改变。更新可以在参数、规则、记忆、结构或其他内部状态中，不限于可读文字档案；保留也可依靠持续维护而非一次写入永不变化。关键是给出位置、版本、时序和调用路径。","最低材料应把更新前后状态、载体维持、重复调用及任务比较连起来。因果解释还需相称中断、替换、恢复或有识别条件的比较，处理共同输入、持续训练、选择、失访和测量变化。所有比较都依目标与允许操作设计，不得为了验证理论撤去必要支持或强行干预人员。若要声称跨情境迁移或样本外预测增益，应另给相称的独立任务或样本外材料。","一次参数改动、一次成功、一次写回、材料归档分别只覆盖链中的局部。若更新没保存、后来不用、结果可由共同输入解释，或只让代理分数好看而预定任务没改变，相应学习机制未获支持。报告应标出断在哪一段；不能把尚不确定的净效应误写成已确定没有学习，也不能把已变的做法写成全部机制已证。","历史增量分支CM-LEARNING-history是在上述载体链之外，再问：给定明确登记的当前表示后，过去历史是否仍增加对预定后续结果的解释或预测，且有合格G3-instance支持。载体学习可以充分保存在当前参数里，从而不再需要额外历史；这并不取消已经学到的内容。反过来，历史变量有用也不单独证明返回、更新、保留和调用全链成立。","因此两条路线要事先分别声明比较、反例和失败条件。不能删掉已知当前参数以制造历史增量，不能在载体路线缺少调用证据时改说“历史重要”来救援，更不能在历史增量未过时事后切换主判据。载体路线可独立成立，但要靠自己的材料，而非另一分支失败的余地。","一般学习并不必须等待本框架正式认证。领域中可重复的新任务表现、保留技能或可追查教学/组织过程，可支持各自范围内的学习判断。可以同时报告“做法已改变”“反馈介导机制未充分识别”“后续净收益未确定”，这三句不是矛盾。框架资格不足不抹去独立事实，领域结论也不自动升成框架的全部机制。","学习成立不等于变得更好，更不产生统一目标或行动授权。若目标改变，应公开新目标形成理由和决定程序，保存旧目标下的失败、结果及成本，为新任务重新建立比较；不能事后把原来的错误任务改名为“探索”便宣告成功。","还要把支持下完成、撤除支持后的独立迁移、后续生活结果分开。必要支持可以是协作/表达任务的组成部分，此时失去支持后失败不取消已有支持下成功；若预定目标确是独立迁移，辅助成绩又不能冒充独立能力。支持保留是否必要、目标选择是否合理、更新是否保留、表现是否变好、净收益如何，各有证据责任。"],"distinctions":[{"leftTitle":"更新保留","leftText":"载体在后续窗口仍保存或持续维持更新。","rightTitle":"实际调用","rightText":"后续任务确实读取并使用它，保存不等于使用。"},{"leftTitle":"载体学习","leftText":"当前载体承接更新并影响后续任务。","rightTitle":"额外历史增量","rightText":"给定当前表示后，历史仍提供条件增量，另需G3。"},{"leftTitle":"支持下表现","leftText":"按原任务合同带有工具或协作支持的完成。","rightTitle":"独立迁移","rightText":"在明确规定的撤援/新情境条件下完成，不能互相冒充。"},{"leftTitle":"任务差异","leftText":"预定任务结果发生可复核改变。","rightTitle":"净收益","rightText":"综合目标、成本、风险和分布的另项判断。"}],"boundaries":["反馈成立而更新每轮清零，可有一次作用但没有该载体的跨轮学习。","当前载体充分时额外历史增量可以为零，学习并不因此消失。","模型内删除一个已知参数会制造表示不足，不能隐瞒这种删除来声称历史本体不可消除。","支持是原任务组成部分时，无支持失败不能取消带支持成功；独立迁移仍需自己的比较。","单纯证据不足保留未决；得到相称反证才拒绝具体主张，不把长期净益未知说成一切学习为零。"],"questions":["模型载体θ=2保留，但后续程序从未读取，学习机制证据缺哪一段？","当前参数已经包含所学内容，G3增量为零，会否否定载体学习？","数学预测器测试u=3时旧参数平方误差为什么是36？","培训后组织做法改变，但没有足够材料判断净效果，应如何报告？","带辅助工具完成任务，能否直接写独立能力已形成？"],"diagramPath":"/reading-assets/S-6-3/figures/section-6-3.png","caseLinks":[{"title":"马里兰新续保流程：开始使用与长期学习仍有距离","href":"https://health.maryland.gov/mmcp/Documents/JCRs/2023/eligibilityredetprocessJCRfinal4-24.pdf"}],"caseNotes":[{"title":"马里兰新续保流程：开始使用与长期学习仍有距离","text":"2024年马里兰报告明确记载，新版基于现有数据的续保流程自2023年11月开始使用，并表示以后续保会沿用这些修改。本节新增观察点是“已经调用”与“将持续调用”的证据时态：前者是报告中的实施事实，后者是前瞻安排，不能只靠一句将来计划证明多轮保留、稳定调用或长期净效果。","sourceLabel":"Maryland FY24 Quarter 4报告，2024-05-14提交","sourceUrl":"https://health.maryland.gov/mmcp/Documents/JCRs/2023/eligibilityredetprocessJCRfinal4-24.pdf","sourceLocator":"印刷p.9末段，updated ex parte systems process was utilized beginning November 2023及紧接的Moving forward句","boundary":"支持报告时已开始使用的流程改变；未提供本节完整反馈载体链的因果对照、跨轮任务效果或长期健康收益，仍保留行政实施事实。","href":"https://health.maryland.gov/mmcp/Documents/JCRs/2023/eligibilityredetprocessJCRfinal4-24.pdf"}],"sourceRefs":[{"section":"6.3","start_line":1320,"end_line":1337,"startLine":1320,"endLine":1337}],"outputId":"section-6-3","sourceHash":"df579dbdbb68442b1781b066606c267761f0a1673fbd034ce93eeeb41641439f","argumentSteps":["声明具体任务、基线、窗口和支持条件，再定位有效返回及其改变的内部字段。","追踪更新载体的版本、保留/持续更新和后续重复调用，不以归档替代使用。","比较预定任务结果，并核共同输入、持续训练、选择、失访和测量改变。","若主张迁移或预测增益，另给独立任务/样本外评价；比较不得造成未经授权的支持中断。","载体路线与历史增量路线事前分开；后者另需相对完整明示当前表示的G3。","独立保留一般学习证据和组织做法变化，具体机制与净收益分别结案。","目标变化保留旧任务账目并启动新比较；功能获得、独立迁移、后续生活和权限不合并。"],"teachingExamples":[{"title":"数学构造：反馈写入参数，后续调用有可算差异","text":"虚构预测器输出y=θu，初始θ=0，目标规则y*=2u。训练轮u=1时实际输出0，比较器据目标2计算返回误差e=2−0=2，规则θ←θ+e将参数写为2。此后停止训练，保留θ，在两个新轮次u=2、u=3实际调用，输出分别4、6，平方误差均为0。保持旧θ=0的基线输出0、0，平方误差16、36。若只在调用前替换载体为θ=0，则又得到16、36；恢复θ=2则回到0、0。完整模型因此连通了返回、更新、保留、调用与任务差异。","assumptions":"目标规则、训练与更新规则、测试输入以及载体替换皆人为设定；没有其他外部输入或参数变化，训练只一轮但后续调用为两轮。","boundary":"这是真实可算的数学构造，不是实际机器实验；不因测试输入不同就证明任意现实跨情境泛化或正式G实例。"},{"title":"数学构造：学习保存在当前状态，历史增量为零","text":"沿用预测器，当前完整登记包括θ=2和输入u。输出必为2u，无论训练前有多少轮或历史怎样排列，只要这些历史最终给同一θ，未来输出就相同；额外历史不能再降低已为0的预测误差。因此载体学习成立与额外历史增量消失相容。若故意把当前表示改为“参数是否非零”，θ=1和θ=2被折叠，历史可能帮助区分；必须公开这一粗化，不能把已知θ删除后装作没有当前载体。","assumptions":"固定确定性输出规则；θ就是本例所学的全部可调用内容，比较模型允许读取它。","boundary":"现实载体是否充分要取证，构造中的充分性不能直接外推。"},{"title":"教学构造：辅助任务与独立任务不是同一考试","text":"虚构译码任务规定使用一张代码表，参与者正确完成三次译码。若原目标就是“借助表完成”，不能临时收走表后用失败取消原成功；若原目标是“离开代码表独立译码”，前三次又不足以证明目标。这个例子只说明评价合同，三次表现本身还不证明有反馈介导学习或保留更新。","assumptions":"纯教学情境，无真实参与者、测量或撤援试验；代码表是否可用在评价前声明。","boundary":"不主张现实中应撤除必要支持；独立比较须兼顾伦理、风险和权限。"},{"title":"数学构造：目标重写不能擦掉旧任务失败","text":"若原目标要求输出2，实际输出3，平方损失为(3−2)²=1。事后把新目标设为3，新任务损失变为0，但原任务损失仍是1；新目标还要有合理形成过程和后续比较。数字改变的是评价问题，不是过去输出。","assumptions":"两目标与同一输出均为构造；不预设新目标天然错误或正确。","boundary":"不能由新目标下成功免除旧目标的失败记录、成本或责任。"}],"counterexamples":[{"identity":"constructed_boundary","text":"参数文件已更新，但执行程序仍读取旧版本，却称后续任务已经学会。","effect":"保存与实际调用断开，不支持该载体链。","sourceIds":["theory"]},{"identity":"constructed_boundary","text":"有支持时能完成、撤援后不能，因此所有获得的功能都不存在。","effect":"评价条件被替换；应分别报告辅助完成和独立迁移。","sourceIds":["theory"]},{"identity":"constructed_boundary","text":"当前参数已充分预测结果，历史不再提高预测，所以学习没有发生。","effect":"把额外历史增量误作载体学习的必要条件。","sourceIds":["theory"]},{"identity":"constructed_boundary","text":"代理评分上升而预定真实任务未变，事后把目标改成评分并宣布学习成功。","effect":"改变目标须公开且另比较，不能救援原任务。","sourceIds":["theory"]}],"questionAnswers":[{"question":"模型载体θ=2保留，但后续程序从未读取，学习机制证据缺哪一段？","answer":"缺实际调用及由调用引起的预定任务差异；保存本身不足。","basis":"本节原文及上述公开推导"},{"question":"当前参数已经包含所学内容，G3增量为零，会否否定载体学习？","answer":"不会。载体学习与当前表示之外的历史增量分别取证，前者不硬需后者。","basis":"本节原文及上述公开推导"},{"question":"数学预测器测试u=3时旧参数平方误差为什么是36？","answer":"旧θ=0输出0，目标2×3=6，平方误差(0−6)²=36。","basis":"本节原文及上述公开推导"},{"question":"培训后组织做法改变，但没有足够材料判断净效果，应如何报告？","answer":"保留做法改变的事实；分别列反馈学习机制的证据/缺口与净效果未决，不压成单一成功或失败。","basis":"本节原文及上述公开推导"},{"question":"带辅助工具完成任务，能否直接写独立能力已形成？","answer":"不能，除非原目标及相称评价覆盖独立迁移；同样不能因独立迁移未证而取消原条件下的完成。","basis":"本节原文及上述公开推导"}],"figures":[{"path":"/reading-assets/S-6-3/figures/section-6-3.png","alt":"有效反馈，返回实际造成改变，基础依赖；可定位更新，状态／参数／规则，记录版本与时序；明确载体，保留或持续更新，归档不等于调用；后续重复调用，进入预定任务，核中断／替换／恢复；任务比较，与预定基线有差异，净收益与授权另查；额外历史分支，相对当前表示加G3，不是载体学习必需。箭头表示应核连接；最左下为可另声明的历史分支，不是载体学习的追加必经门。","caption":"箭头表示应核连接；最左下为可另声明的历史分支，不是载体学习的追加必经门。"}],"diagramBrief":"当前交付为静态图；交互尚未实现，以下涉及选择、切换或点击的内容仅为后续设计设想。六卡呈现返回、载体、调用与结果；历史分支只有另主张当前表示之外增量时增加G3。支持、独立迁移、净益分别评价。","applicability":{"realCase":"applicable","diagram":"applicable","reason":"真实实施记录帮助辨认更新、已使用与将来持续的不同材料；数学例完整公开机制设定，不把行政报告追授为正式学习实例。"},"openQuestions":[],"taskId":"S-6-3","sources":[{"id":"theory","title":"Xikari-条件结构与转化论，用户提供原文","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"现行全文第1320—1337行；每节精确范围见sourceRefs","claim_support":["6.3：术语、合同、论证责任和原文边界；不据此认证经验事实"],"limits":["作者理论文本，是被解释对象，不替代外部经验资料；技能5.3.1不等于理论版本。"],"access_status":"read"},{"id":"maryland-use","title":"Maryland FY24 Quarter 4报告：已使用与持续计划","url":"https://health.maryland.gov/mmcp/Documents/JCRs/2023/eligibilityredetprocessJCRfinal4-24.pdf","source_type":"primary","version_or_date":"报告April 2024；提交封信2024-05-14","locator":"印刷p.9，Medicaid Mitigation of Ex Parte Renewals末段","claim_support":["6.3：新流程自2023年11月实际使用，随后句子是未来继续使用安排。"],"limits":["开始使用和计划不单独证明长期保留调用、因果学习或健康净益。"],"access_status":"partially_read"},{"id":"theory-history","title":"Xikari4.5：当前载体与历史增量","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"第620—640行","claim_support":["6.3：形成、当前传递、额外历史增量分开；不能删除已知当前状态制造残差。"],"limits":["数学充分性不能替现实载体测量。"],"access_status":"read"},{"id":"theory-feedback","title":"Xikari6.2：有效反馈","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"第1302—1311行","claim_support":["6.3：基本依赖是有作用的返回，不要求持久历史或G3。"],"limits":["基础反馈不自动构成学习。"],"access_status":"read"}],"lecturePath":"/reading-assets/S-6-3/lecture.md","sourcesPath":"/reading-assets/S-6-3/sources.json","sourceSlicePath":"/reading-assets/S-6-3/source-slice.md","supplementaryFiles":[],"diagramsPath":"/reading-assets/S-6-3/diagrams.md"},"6.4":{"title":"6.4　反馈、制度写回与学习的虚拟申诉例","lead":"同一封申诉，可以停在“收到了”，也可以改动案件字段、落实执行，甚至影响后续多轮处理。每多说一层，就多承担一层证据，不能用一张回执跨完所有台阶。","explanation":["原文定位：第1338—1351行；原文锚点 section-6-4；短引文：‘本例只展示分类方法’。本题源切片逐字附后，讲解与原文分开。","原文明确设定一个虚拟制度，因此下面是分类教学，不是现实申诉报道，也不提供外部经验证明。我们固定同一对象、申诉和观察窗口，分别改变后续条件，看允许说到哪里。它不是现实制度必然经历的成熟阶梯。","第一种情形是收件并生成回执，而本次登记的记录、规则、资源、角色、责任、记忆和停止条件均未改变。这里回执证明信号到达，不自动证明任何相关后续字段变化。应事先界定回执元数据与所问制度字段；若现实回执本身触发排程或停止条件，那已不是本例的“均未改变”情形，需重新核实际通道与作用。","第二种情形中，申诉经指定通道使案件状态字段改变，但尚未进入执行。在已具备相称因果比较的前提下，这可以符合D2的返回作用：状态字段也是后续状态，不必等最终结果变化才承认反馈。但H3要求字段变化和实际执行，故此时不能称完整制度写回。仅看字段时间上后变，尚不能替代“申诉导致”的证据。","第三种情形把字段变化带入实际执行，并分别记录受理、字段前后版本、执行和持续时间，满足该例的写回分类。持续多久是合同的一部分，不因执行过一次就默认永久有效。H3是分类规则，不是抽象经验真值，更不是修改制度的许可；C11还要求指定反馈通道的G2与D2比较。分类成立与完整经验机制支持不要混为一谈。","第四种情形再加可保留规则或状态更新，后续多轮相似案件实际调用，并有预定任务比较和相应因果依据，才能提出载体型反馈介导学习候选。写回一次不自动提供跨轮保存与调用；后续多次同样结果也可能来自持续外部指令或共同环境，须排除相称竞争解释。若另主张当前状态之外的额外历史增量，再单独由G3检验。","本例证据门随主张加深而增加，但不意味着任何领域的学习都必须先经过制度写回。这里固定的是“申诉如何改制度并影响后续案件”这一条路径；一般学习可以发生在其他载体中，按6.3另核。图上的箭头也不保证收件以后迟早走到学习，每个连接都有可能停住。","写回事实不保证制度正当，也不等于长期修复。执行一条不当规则仍可能有真实字段改变与实施，应分别记录事实和规范问题；不能因规则不正当抹掉已发生的影响，也不能因为执行成功便替其正当性背书。修复目标、责任、授权和实施程序仍分别判断。","对真实材料应逐项列“已经发生”“证据不足”“只有计划”。入口开放、公开回应、字段改动、实际执行、保留调用和任务效果各有位置；缺执行证据不能编造实施，缺长期材料也不能否认已有的短期变化。教学表格只帮助组织材料，不把填入“是”当作材料本身。"],"distinctions":[{"leftTitle":"受理/回执","leftText":"确认到达或开始受理。","rightTitle":"字段改变","rightText":"需定位相关字段前后差异并核其来源。"},{"leftTitle":"有效反馈","leftText":"指定返回造成后续状态等的差异。","rightTitle":"完整制度写回","rightText":"该例还要求制度字段变化进入实际执行，并记录持续时间。"},{"leftTitle":"一次写回","leftText":"本轮修改已经执行。","rightTitle":"载体学习","rightText":"可保留更新在后续重复调用并改变预定任务。"},{"leftTitle":"H3分类","leftText":"按给定规则区分受理、修改和执行。","rightTitle":"经验支持或授权","rightText":"需要相应证据或规范/程序，分类不能替代。"}],"boundaries":["本节无真实申诉对象，不得把构造里的状态、次数或损失当成行政统计。","这里的层层加条件仅对应申诉路径，不宣称所有学习都依赖H3制度写回。","字段改变与无执行可以并存，不能以最终实施未完成取消已经有证据的状态反馈。","执行过一次不保证持续、学习、修复或正当；持续时间不能留空后默认为永久。","已知无相应改变与尚无材料观察改变不同；材料不足时保留未决，而非把缺记录当无事件。"],"questions":["案件字段由0改1但尚未执行，为何不能简单说“什么也没发生”？","公告说新规则已批准，执行者仍沿用旧规则，应停在哪一层？","版本D三次调用，是否自动证明独立于当前状态的历史增量？","原目标正确复核，旧输出0、新输出1，三个案件平均平方损失各是多少？","是不是所有反馈学习都必须先制度写回？"],"diagramPath":"/reading-assets/S-6-4/figures/section-6-4.png","caseLinks":[],"caseNotes":[],"sourceRefs":[{"section":"6.4","start_line":1338,"end_line":1351,"startLine":1338,"endLine":1351}],"outputId":"section-6-4","sourceHash":"df579dbdbb68442b1781b066606c267761f0a1673fbd034ce93eeeb41641439f","argumentSteps":["声明这是作者虚拟分类例，固定对象、字段、时间窗和申诉路径，不假造真实案例。","先核到达/回执，再核指定返回造成的字段改变，两者不合并。","字段改变有相称返回比较时可构成反馈；未进入执行则停止在此，不升级完整写回。","实际执行后分别记录受理、版本、执行与持续时间，按H3分类，机制因果资格另核。","再检查保留、多轮调用、预定任务比较与因果材料，才提出载体学习候选。","若另主张额外历史增量，独立核G3；不能把它加成所有写回或学习的必需门。","最后分开写回事实、学习、长期修复、正当性和权限；缺口落在具体层级。"],"teachingExamples":[{"title":"教学构造：四个版本逐项判别","text":"虚构系统将案件状态s=0定义为待原流程，s=1定义为进入复核；另登记实际执行e、规则保留p及后续调用次数n。版本A只收件，s=0、e=0、p=0、n=0：只有到达。版本B按已给定返回规则将s改为1，但e=0：有模型内状态反馈，无完整写回。版本C在B基础上执行复核e=1，受理、字段变化、执行时间及两日有效期均记录：可作一次写回分类。版本D另保留更新p=1，后续三个相似案件调用n=3，并补任务和因果比较：才达到提出载体学习候选的材料层次。","assumptions":"全为人为构造；B的规则明确为有该返回则s=1，无返回则s=0，其他条件固定。标志只是给定模型状态，不是现实填表即认证。","boundary":"D仍不能仅凭p=1、n=3声称真实机制成立；需对应实际材料，额外历史与净益也未由此证明。"},{"title":"数学构造：任务比较必须有明确规则","text":"沿用版本D，设三个新案件的预定任务均是正确进入复核，理想输出y*=1。旧规则在这三种指定输入下都输出0，新保留规则都输出1；平均平方损失旧为[(0−1)²×3]/3=1，新为0。模型中仅在调用前替换为旧规则，损失回到1，恢复新规则又为0。这给出可算的调用与结果连接，不能把没有这些比较的“三次用了”直接当成功。","assumptions":"输入、目标、两版规则和替换含义均人为固定，无共同外部指令改变输出。","boundary":"模型不包含真实案件权益、资源成本和法律效力；不能据此对现实机构作裁决。"},{"title":"教学构造：回执也可能触发作用，但须改写问题","text":"虚构系统规定，收件回执一生成，案件截止时钟就暂停24小时。若这一规则确实执行，停止条件已经改变，便不能再把它归入“所有相关字段均未改变”的A版本。应登记被改变字段与通道，区分时钟暂停和后续实质复核；暂停本身不证明最终申诉成功或长期学习。","assumptions":"明确条件反事实，不描述任何现行申诉制度；24小时为教学设定。","boundary":"不能把所有真实回执都默认具有停止效力，也不据此给法律期限建议。"}],"counterexamples":[{"identity":"source_counterexample","text":"原文虚拟例A只有回执，相关制度字段均未改变。","effect":"不能凭入口或回应登记有效反馈和写回。","sourceIds":["theory"]},{"identity":"source_counterexample","text":"原文虚拟例B字段改变却没有执行。","effect":"可有D2意义状态反馈，但不能说H3完整写回。","sourceIds":["theory"]},{"identity":"constructed_boundary","text":"一项有害规则被申诉推动修改并确实执行，所以该制度正当且修复完成。","effect":"事实分类与规范评价、长期修复互不替代。","sourceIds":["theory"]},{"identity":"constructed_boundary","text":"没有发现后续执行记录，就断定现实从未执行。","effect":"缺证据不自动是事件不存在；须区分已核无执行与未观察。","sourceIds":["theory"]}],"questionAnswers":[{"question":"案件字段由0改1但尚未执行，为何不能简单说“什么也没发生”？","answer":"若指定返回的作用有相称依据，状态已经改变；但它仍未满足完整制度写回的执行条件。","basis":"本节原文及上述公开推导"},{"question":"公告说新规则已批准，执行者仍沿用旧规则，应停在哪一层？","answer":"保留公告/批准事实，核具体字段变化；不能据公告冒充实际执行和完整写回。","basis":"本节原文及上述公开推导"},{"question":"版本D三次调用，是否自动证明独立于当前状态的历史增量？","answer":"不证明。载体更新可充分包含所学内容；额外增量须另按G3相对明确当前表示检验。","basis":"本节原文及上述公开推导"},{"question":"原目标正确复核，旧输出0、新输出1，三个案件平均平方损失各是多少？","answer":"旧为1，新为0；只在给定模型、目标及三种输入范围内成立。","basis":"本节原文及上述公开推导"},{"question":"是不是所有反馈学习都必须先制度写回？","answer":"不是，本节固定制度申诉路径；其他载体的学习按6.3独立检验。","basis":"本节原文及上述公开推导"}],"figures":[{"path":"/reading-assets/S-6-4/figures/section-6-4.png","alt":"A 只有收件回执，相关字段未变，只登记到达；B 返回改变字段，但尚未进入执行，反馈可有／写回未全；C 字段变化已执行，受理／版本／执行，持续时间分别记录；D 更新保留与调用，后续重复案件，任务与因果比较；载体学习候选，不等于长期修复，不产生正当性或授权；另加历史主张时，相对当前表示核G3，不是前面各层必需。全部为虚拟条件版本，箭头不是实际升级记录；本路径不代表所有学习都必须制度写回。","caption":"全部为虚拟条件版本，箭头不是实际升级记录；本路径不代表所有学习都必须制度写回。"}],"diagramBrief":"当前交付为静态图；交互尚未实现，以下涉及选择、切换或点击的内容仅为后续设计设想。六卡按原例展开收件、反馈、写回、重复调用、学习候选及可另提历史分支。每箭头都须核条件，图不认证任何现实制度。","applicability":{"realCase":"not_applicable","diagram":"applicable","reason":"原节明确是虚拟制度的分类教学，保留其身份并用条件变体展开，不强加真实史实或编造申诉个案。"},"openQuestions":[],"taskId":"S-6-4","sources":[{"id":"theory","title":"Xikari-条件结构与转化论，用户提供原文","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"现行全文第1338—1351行；每节精确范围见sourceRefs","claim_support":["6.4：术语、合同、论证责任和原文边界；不据此认证经验事实"],"limits":["作者理论文本，是被解释对象，不替代外部经验资料；技能5.3.1不等于理论版本。"],"access_status":"read"},{"id":"theory-h3","title":"Xikari7.1：H3制度写回分类与权限边界","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"第1467—1482行，尤其第1477、1482行","claim_support":["6.4：H3是分类规则，字段改变需有实际执行；分类不授权修改记录或规则。"],"limits":["不是经验实例也不是法律效力判决。"],"access_status":"read"},{"id":"theory-c11","title":"Xikari4.13.4：C11制度写回","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"第885—897行","claim_support":["6.4：D2/G2与H3责任不同，受理、字段变化、执行、持续时间分开。"],"limits":["具备字段不自动证明因果机制。"],"access_status":"read"},{"id":"theory-learning","title":"Xikari6.3：反馈介导学习两分支","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"第1320—1337行","claim_support":["6.4：可保留更新、多轮调用、任务比较与因果依据；额外历史才加G3。"],"limits":["本节虚拟例不认证任何现实学习。"],"access_status":"read"}],"lecturePath":"/reading-assets/S-6-4/lecture.md","sourcesPath":"/reading-assets/S-6-4/sources.json","sourceSlicePath":"/reading-assets/S-6-4/source-slice.md","supplementaryFiles":[],"diagramsPath":"/reading-assets/S-6-4/diagrams.md"},"6.5":{"title":"6.5　CM-MAINTENANCE 维护与存护—消解","lead":"一台设备继续转、一项服务继续开，背后可能有人不断补给、更换、校正或清障。维护分析要找出这些具体输入怎样保持身份或功能，同时问：保持的是什么、靠谁承担、故障时备份真的切得过去吗？","explanation":["原文定位：第1352—1367行；原文锚点 section-6-5；短引文：‘冗余按失效条件检验，不能只数备用数量’。本题源切片逐字附后，讲解与原文分开。","基础依赖D0和G2：先明确完整对象合同，其中K只是同一性判据；再识别指定维护通道。D1限定存续、解体和修复等状态词，E4、CAUSAL、EVIDENCE审查解释与材料。预先声明当前K或功能判据F及窗口，才能判断维护使什么保持；“看着还在”不自动说明所有功能正常。","机制链是磨损、漂移、损耗或组件退出→指定维护通道→补给/替换/校正/清除→K或F保持时间、失效概率改变。结果可为延长可用时间或改变失效风险，不必每次使状态回到初始值。最低比较不只“有无工单”，还需维护、减维护、错配和停止条件之间的相称材料，并有G2识别通道。现实停维护比较须受风险和权限限制，不能为验证而任意关闭必要服务。","current分支问当前输入对当前窗口K/F保持的作用。carried-cumulative分支另追此前输入如何形成当前磨损或能力载体、如何跨窗保留/补给，以及维护改变后续保持的纵向和因果依据。cumulative是额外历史增量分支，只有声称给定当前表示后历史仍有额外作用时才加G3。当前磨损已经充分承接过去时，可以没有额外历史增量。","若对象在目标窗口不需持续维护也保持K/F，就不能把维护的必要性外推进这个窗口；若维护输入变化不改变相关结果，或所谓磨损其实来自独立冲击，应收窄或撤回相应主张。比较不敏感时保留未决，不能把未测差异直接当零作用。原K已经改变还沿用旧判据，会把维护和对象转换混同，须重新核对象合同。","维护需要不是永久存续的规范理由。补给通道存在，不会自动指定某人承担、不产生牺牲义务。错配维护可能让旧对象K延续却破坏目标F；有序停止、转换或解体也可能属于允许结果。该不该维持、以何目标、由谁决定与执行，仍交规范、授权和程序，不能从技术可行推义务。","正常运行、迁移、故障和恢复是不同任务。接口标准说明可能互通的条件；实现版本、业务语义、环境负荷、测试及现场适配决定这次是否实际兼容。仓库有零件还须核规格、质量、运输、现场技能和停机权限，不能把“存在”合成“可及时用”。平时能替换与紧急窗口内能完成替换也不同。","维护可能移出原对象边界，由用户、家庭、外包人员或其他机构补上。中心工单下降、输出维持，不必意味着总维护劳动减少；应登记外部承担的位置、工作量、时间、支持与停止权。只有同型量才可在明示口径下加总，不把异质劳动、风险、时间和权利压成无单位的统一成本。","冗余要针对失效条件，而非只数备用数量。两条路径可共用电源、软件状态、运输、供应商、操作者或审批节点；正常时彼此替代，故障时却一起失效。应分别核备用容量、共因暴露、切换时间、现场技能与实际切换权，不能默认两台就是独立可靠。","恢复过程还依赖通信、道路、燃料、备件和人员，必须放在同一故障窗口核可达性。如果通信断了就无法取得切换许可，或道路中断使备件到不了，纸面的备份可能不能转成实际恢复。增加备份、降低耦合或保留局部独立运行都是候选设计，其净效应仍取决于故障类型、维护成本与具体任务。"],"distinctions":[{"leftTitle":"保持K","leftText":"对象继续满足所声明同一性判据。","rightTitle":"保持F","rightText":"继续达到特定功能要求，两者可分离。"},{"leftTitle":"备用存在","leftText":"有另一组件或路径。","rightTitle":"故障时可用","rightText":"容量、共同暴露、切换、到场和权限都适配本次窗口。"},{"leftTitle":"标准接口","leftText":"规定可能互通的类型与规则。","rightTitle":"实际兼容","rightText":"具体实现、语义、环境和负荷下的可用连接。"},{"leftTitle":"维护必需","leftText":"特定范围内功能依赖某些输入。","rightTitle":"某人必须继续承担","rightText":"还需规范、责任与权限，不能直接推出。"}],"boundaries":["短窗口内无需持续维护，不意味着任何更长窗口都不需要；长窗口证据也不能替换原短任务结论。","当前磨损可充分承接过去，不必要求G3才承认累积载体作用。","原K失效后仍称“维护同一对象”，需检查是否已转换或解体，不能静默延用旧合同。","正常供能和运输条件下的冗余测试不能自动覆盖共因故障与恢复阶段。","中心指标改善可能伴随外部劳动增加；维护能力不直接创造任何具名者的义务。"],"questions":["磨损模型m=1为何第四步才失效？","模型B为什么不能把双失效算成0.1×0.1？","功能保持必须维护，是否足以指定某位员工继续承担？","有备份且容量足，为什么仍可能不能满足恢复目标？","当前磨损已完整反映过去，额外历史没有增量，是否排除累积维护作用？"],"diagramPath":"/reading-assets/S-6-5/figures/section-6-5.png","caseLinks":[{"title":"STS-114：备件必须进入实际替换","href":"https://www.nasa.gov/mission/sts-114/"}],"caseNotes":[{"title":"STS-114：备件必须进入实际替换","text":"NASA任务记录写明，2005年8月1日第二次舱外活动中，Noguchi和Robinson移除失效的CMG-1，将新控制力矩陀螺从载荷舱移出并安装；记录随后报告空间站有四台可工作的CMG。本节新增观察点是备件存在、运输到位置、人员操作、安装与工作状态的区别，而非重复影像反馈案例。","sourceLabel":"NASA STS-114任务页，2025-05-01更新","sourceUrl":"https://www.nasa.gov/mission/sts-114/","sourceLocator":"Mission Highlights，EVA No.2（Aug.1）条目；CMG功能见前一条EVA No.1后续句","boundary":"支持这次更换及当时工作数量的任务记录，不量化长期可靠性、独立冗余或维护必要性的全部反事实，也不据此取得正式G2资格。","href":"https://www.nasa.gov/mission/sts-114/"}],"sourceRefs":[{"section":"6.5","start_line":1352,"end_line":1367,"startLine":1352,"endLine":1367}],"outputId":"section-6-5","sourceHash":"df579dbdbb68442b1781b066606c267761f0a1673fbd034ce93eeeb41641439f","argumentSteps":["固定完整对象合同、K/F、窗口及正常/迁移/故障/恢复的任务，避免把身份和功能合并。","定位损耗载体、维护输入和作用路径，预先指定保持时间或失效概率等结果。","用相称维护、减维护、错配、停止比较识别通道，处理独立冲击、选择和测量限制。","当前、载体累积、额外历史增量分别登记；只有最后一条另需G3。","核接口实际兼容、零件质量与到场、人员技能和停机/切换权限，而非只查库存。","把外部承接劳动与恢复依赖计入边界；同型量明确口径，异质成本分列。","按共同失效条件和切换时限评估冗余；最后另议应否维持、替代/停止和责任授权。"],"teachingExamples":[{"title":"数学构造：维护改变保持时间，窗口不能偷换","text":"虚构设备磨损w₀=0，每步增加2，维护输入m抵消磨损，规则w_{t+1}=max(0,w_t+2−m)。预定功能F为每个检查时点w≤3。无维护m=0得到0、2、4，第二步首次失效；减维护m=1得到0、1、2、3、4，第四步首次失效；维护m=2始终为0，在所取四步窗口内保持F。若任务窗口只有第一步，三者都满足F，不能从更长窗口的差别宣称第一步功能必须持续维护。","assumptions":"同一单位的磨损与补偿量，固定规则、无额外冲击；只比较F，不声称该单变量已验证对象的完整合同或其同一性判据K。","boundary":"全为数学模型；现实磨损、维护时序和失效阈值须独立测量，不据此指定维护量。"},{"title":"数学构造：同样两条备路，独立与共因失效不同","text":"假定两路中至少一路可用即达成功能。模型A两路各以0.1失效且独立，双失效概率0.01。模型B以0.05概率发生共同事件使两路同时失效；无共同事件时，两路各以1/19条件独立失效。因此每路边际失效仍是0.05+0.95/19=0.1，但双失效为0.05+0.95×(1/19)²=1/19≈0.052632。路数及单路边际相同，系统失效概率却不同，共同条件不能靠数备用代替。","assumptions":"两种概率模型完全人为给定，且切换无延迟、容量足够；模型B仅在无共因事件条件下独立。","boundary":"不是实际设备可靠性统计；现实还要加入切换时间、权限、技能和容量。"},{"title":"教学构造：备用容量足，仍会错过功能窗口","text":"虚构服务允许的最大中断为2分钟，备用系统有足够容量，但必须由现场人员切换，最短需5分钟。备用存在并不满足“中断不超过2分钟”的F；5分钟后恢复服务仍是真实的另一个结果，不能因此说备份完全无用，也不能把迟恢复写成原窗口达标。","assumptions":"时限、容量与切换规则均为教学设定，无真实停机或人员试验。","boundary":"不是现实安全阈值或切换建议；任务要求须事前确定。"},{"title":"数学构造：中心工作量下降，外部补位可能上升","text":"假设同一周、同一登记活动的维护劳动，原来中心8人时、外部0人时；改变后中心3人时、外部7人时。中心减少5人时，但该口径总劳动从8变成10人时。输出保持可由外部补位解释，不能只凭中心工单宣布总维护减少。","assumptions":"人为设定的同型劳动时间，覆盖两边且无重复计数；人时仅用于时间账，不假设不同人的疲劳、机会损失和权利相同。","boundary":"不把时间和健康、风险、责任合成统一成本，不描述真实家庭或机构。"}],"counterexamples":[{"identity":"constructed_boundary","text":"两台备用共享同一电源和唯一审批者，因此宣布具备两个完全独立恢复路径。","effect":"共同暴露与切换权可能同时阻断，须按故障条件检验。","sourceIds":["theory"]},{"identity":"constructed_boundary","text":"旧流程身份延续，但任务功能持续受损，所以只要继续维护旧流程就算修复。","effect":"K保持与F达标不同，错配维护可能需要停止或转换。","sourceIds":["theory"]},{"identity":"constructed_boundary","text":"有人一直补位使服务正常，于是推定此人有永久继续承担的义务。","effect":"经验承接与规范义务分开，需检查自愿性、责任和停止权。","sourceIds":["theory"]},{"identity":"constructed_boundary","text":"已买到符合某接口标准的零件，便断言现场故障可立即解决。","effect":"实现版本、语义、环境、质量、到场、技能和停机权限仍可能不满足。","sourceIds":["theory"]}],"questionAnswers":[{"question":"磨损模型m=1为何第四步才失效？","answer":"磨损依次1、2、3、4，F允许≤3，第一次超阈是第四步。","basis":"本节原文及上述公开推导"},{"question":"模型B为什么不能把双失效算成0.1×0.1？","answer":"两路仅在无共同事件时条件独立，总体受共因耦合；应先对共同事件分层求概率。","basis":"本节原文及上述公开推导"},{"question":"功能保持必须维护，是否足以指定某位员工继续承担？","answer":"不足，维护机制与责任、义务、自愿性和权限是不同判断。","basis":"本节原文及上述公开推导"},{"question":"有备份且容量足，为什么仍可能不能满足恢复目标？","answer":"可能有共同失效、切换延迟、到场技能或权限缺口，恢复依赖也可能在同一窗口不可用。","basis":"本节原文及上述公开推导"},{"question":"当前磨损已完整反映过去，额外历史没有增量，是否排除累积维护作用？","answer":"不排除，载体累积路线另依纵向/因果证据成立；额外历史分支才需要G3。","basis":"本节原文及上述公开推导"}],"figures":[{"path":"/reading-assets/S-6-5/figures/section-6-5.png","alt":"先定目标与窗口，K同一性／F功能，正常、故障、恢复分开；磨损或能力载体，此前输入怎样形成，当前充分可无G3增量；维护指定通道，补给／替换／校正／清除，比较保持时间与失效；实际可用性，版本、语义、质量，人员到场与停机权；冗余与恢复依赖，共因、容量、切换时间，通信／道路／燃料等；负担与停止选择，中心之外也可能补位，需要不自动成为义务。六卡为维护检验清单，不是每项均已证；K只是完整对象合同中的同一性判据。","caption":"六卡为维护检验清单，不是每项均已证；K只是完整对象合同中的同一性判据。"}],"diagramBrief":"当前交付为静态图；交互尚未实现，以下涉及选择、切换或点击的内容仅为后续设计设想。上排定位目标、载体、通道，下排列真实兼容与恢复可达性、共因故障和承接边界。备用数量不能代替故障时条件。","applicability":{"realCase":"applicable","diagram":"applicable","reason":"真实任务提供具体替换动作和工作状态；可靠性、磨损、切换及外部时间账为显式数学/教学构造，不伪装NASA数据。"},"openQuestions":[],"taskId":"S-6-5","sources":[{"id":"theory","title":"Xikari-条件结构与转化论，用户提供原文","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"现行全文第1352—1367行；每节精确范围见sourceRefs","claim_support":["6.5：术语、合同、论证责任和原文边界；不据此认证经验事实"],"limits":["作者理论文本，是被解释对象，不替代外部经验资料；技能5.3.1不等于理论版本。"],"access_status":"read"},{"id":"nasa-cmg","title":"NASA STS-114：CMG替换与工作状态","url":"https://www.nasa.gov/mission/sts-114/","source_type":"primary","version_or_date":"任务2005-07-26—08-09；网页2025-05-01更新","locator":"Mission Highlights，EVA No.2（2005-08-01）及EVA No.1后CMG说明","claim_support":["6.5：失效CMG-1被移除，新CMG由载荷舱移出安装；当时记录四台可工作。"],"limits":["一次任务记录不证明长期可靠性、独立冗余或完整G2反事实。"],"access_status":"partially_read"},{"id":"theory-d0d1","title":"Xikari3.1—3.2：对象合同与状态","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"第425—461行","claim_support":["6.5：K为同一性判据，功能F与对象持续身份分开，解体/修复不自动有规范方向。"],"limits":["定义与事实支持及规范判断各自承担责任。"],"access_status":"read"},{"id":"theory-carried","title":"Xikari4.5：当前载体与历史增量","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"第620—640行","claim_support":["6.5：当前磨损/能力可承接历史，只有额外条件增量主张另需G3。"],"limits":["不由历史叙述代替载体因果识别。"],"access_status":"read"}],"lecturePath":"/reading-assets/S-6-5/lecture.md","sourcesPath":"/reading-assets/S-6-5/sources.json","sourceSlicePath":"/reading-assets/S-6-5/source-slice.md","supplementaryFiles":[],"diagramsPath":"/reading-assets/S-6-5/diagrams.md"},"6.6":{"title":"6.6　CM-LOAD 负荷、容量与恢复","lead":"“忙不过来”和“已经恢复”都需要补上口径。哪里、哪段时间、什么需求、多少可用能力？恢复的是当日输出，还是身份和功能，还是已经耗掉的储备？这些问题不能用一个总百分比回答。","explanation":["原文定位：第1368—1383行；原文锚点 section-6-6；短引文：‘恢复判断应同时说明恢复了什么、对谁、在什么支持条件下以及截至何时’。本题源切片逐字附后，讲解与原文分开。","CM-LOAD先依D0明确对象与位置，再由G2识别已测通道和相关维度；E4、CAUSAL、EVIDENCE是方法门。需求与容量须同型，或有明确单位及转换映射，在同一窗口和位置测量。每小时任务数不能直接减总库存，人数不能直接减预算；先给处理时间、任务类型、核算边界与映射，才可能比较。","机制链是同型需求进入指定通道、占用可用容量、形成即时缺口或跨界溢出，再由减载、补给、扩容改变缺口。instant分支只登记同窗需求—容量及即时缺口，不由一次缺口自动推出累积损伤。carried-cumulative另追历史暴露怎样形成当前损伤/容量载体、跨窗保留或恢复，以及后续结果与相称因果比较；cumulative额外历史分支才另加G3。","负荷不必单调积累。容量可能随需求扩大而吸收增量，短暂缺口也可能结束后没有持续差异。要说迟恢复或后来崩溃，必须说明损伤、储备、积压或其他载体怎样把前一窗口连到后一窗口；不能只把“曾经过载”当作后来一切问题的充分原因。","位置与分布不可被平均值替代。总需求小于总容量，不保证各局部都不超载；备用能力若无法在本窗口转移到缺口位置，就不能直接抵扣。容量还要分峰值与持续值、替代通道能力和补给速率，短时峰值不能默默承诺长期供给。跨界溢出要记录落到哪里，而非从中心指标中删去。","恢复至少有三个不同目标：输出是否回来，原K或预定F是否恢复，内部余量是否补回。输出数量正常时，质量、持续性或可达性仍可能不同；某项F已恢复时，人员休整、备件、维护积压、资金接续也可能未恢复。反过来，对一个准确限定的功能确认，不需要所有其他生活结果同时好转。","恢复声明要同时交代恢复什么、对谁、在何支持下、截至何时。实物或服务输出的数量、质量、持续性与可达性分别取证；内部休整/备件/积压/资金，以及边界外照护、通勤、借款、替代服务负担，再加后续中断和近失误，不能只用中心产出推断。不同型负担分列，恢复需要本身不产生牺牲义务或操作授权。","分母是主张的一部分。灾前人口、当前人口、符合资格者、实际使用者回答不同问题；分子也须属于对应集合。某项“符合安全条件者的服务连接率100%”可以真实成立，同时不能改写成“所有灾前居民各项生活恢复100%”。改变分母要说明原因、时间和被排除位置，不以新口径覆盖旧口径。","临时场所、持续外援或辅助设备也能形成真实功能修复。依赖支持不是失败；应该核支持能持续多久、何时到期、替代承接是否已实际运行，以及尚未经历的高峰、季节性暴露或维护周期。不能把“支援存在”当成恢复永远不算，也不能把支持下的成功推广成撤援后的独立成功。","所谓假恢复只宜指出声明超出证据支持的对象、人群、功能或持续条件，不因此推定欺骗。后来再次失稳，要比较旧损伤延续、储备未补回、支持中断、新冲击和口径改变。新失败可能暴露边界，但不能抹去此前准确限定的成果；也不能为验证恢复而撤去必要支持。"],"distinctions":[{"leftTitle":"即时缺口","leftText":"同一窗口、位置的需求超过可用容量。","rightTitle":"累积损伤","rightText":"需要载体把过去暴露带入后续，不能直接由缺口推出。"},{"leftTitle":"输出恢复","leftText":"数量等某项输出回到预定水平。","rightTitle":"余量恢复","rightText":"储备、休整、积压和接续能力恢复，是另一任务。"},{"leftTitle":"支持下功能恢复","leftText":"临时支援可以构成真实功能的一部分。","rightTitle":"撤援后独立维持","rightText":"需相称后续材料，不能由前者代替。"},{"leftTitle":"限定百分比","leftText":"明确人群、分子分母、功能和时间。","rightTitle":"全面恢复","rightText":"覆盖更多对象和结果，不能靠一个百分比自动获得。"}],"boundaries":["不同类型、不同时间或不同位置的量，不能直接相减；可调度性也是桥接条件。","短暂过载可没有长期损伤；长期容量不足也可能来自不同的独立原因。","某有限功能成立不等于所有结果恢复，也不必等待所有结果恢复才承认该功能。","支持到期尚无已运行承接时，持续结论保留未决，不虚构未来供给。","再次失稳不自动推翻此前有限成功，更不自动证明先前人员欺骗或要求撤援。"],"questions":["两点容量总和10、需求总和8，为什么仍可剩3件？","损伤例第1轮输出3已满足需求，为什么不能说余量恢复？","支持设备下功能达标，必须先撤设备才算真实恢复吗？","资格人群连接率100%能否推出灾前账户连接率100%？","再次失稳应比较哪些解释？"],"diagramPath":"/reading-assets/S-6-6/figures/section-6-6.png","caseLinks":[{"title":"波多黎各复电：分母与临时支持同时限定恢复","href":"https://www.gao.gov/assets/gao-19-296.pdf"}],"caseNotes":[{"title":"波多黎各复电：分母与临时支持同时限定恢复","text":"GAO在2019年报告中转述PREPA估计：2018年8月时，能安全接电的客户已全部恢复供电；报告明确这不等于全部灾前客户，因为部分建筑不具安全接入条件。GAO同时记载，截至2018年12月11日，USACE仍支持7台发电机，为Vieques和Culebra两岛的微电网供能。本节新增观察点是恢复分母与持续支持条件：供电功能可以真实恢复，同时不能据此证明所有旧客户、原有电网配置和长期连续性全部恢复。","sourceLabel":"GAO-19-296，2019-04-18","sourceUrl":"https://www.gao.gov/assets/gao-19-296.pdf","sourceLocator":"印刷pp.6–7：Status of electricity restoration及Figure 1后的临时发电机段；PDF第10–11页","boundary":"报告本身公开限定口径，并非欺骗证据；不从接电数量推个人生活、健康或全部储备恢复，也不据此对当前电网作判断。","href":"https://www.gao.gov/assets/gao-19-296.pdf"}],"sourceRefs":[{"section":"6.6","start_line":1368,"end_line":1383,"startLine":1368,"endLine":1383}],"outputId":"section-6-6","sourceHash":"df579dbdbb68442b1781b066606c267761f0a1673fbd034ce93eeeb41641439f","argumentSteps":["先声明对象、地点、人群、时间窗和需求/容量的类型与单位，给必要转换映射。","逐位置测实际可用容量、需求、补给和溢出，区分峰值与持续能力。","即时、载体累积、额外历史增量分别列主张，后两者补跨窗材料，最后一条另需G3。","对减载/补给/扩容作用给相称识别依据，处理共同冲击与替代通道。","恢复声明分别记录输出、K/F、内部储备，列数量/质量/持续/可达性及内外负担。","固定分子与分母，公开支持条件、到期、承接是否运行和未经历的压力窗口。","对再次失稳区分旧损伤、储备、支持、新冲击与测量变化；保留已有有限成功并另审行动权限。"],"teachingExamples":[{"title":"数学构造：总体富余掩盖局部缺口","text":"虚构两处服务点，同一小时需求分别8、0件，可用容量分别5、5件，任务同型。总需求8小于总容量10，但若该小时不能跨点转运，局部缺口为max(0,8−5)=3与0，总未完成3件。若另有即时、无损且有权调度的通道，可把原本未完成的3件转到第二点，从而清除该窗口缺口；这属于额外条件，不能从合计数自动得到。","assumptions":"容量单位均为件/该小时，需求已固定任务类型；是否允许跨点转移明确分两种构造。","boundary":"不是实际组织数据；不由数学可调度性推现实权限或无损通道。"},{"title":"数学构造：输出回来，储备尚未回来","text":"虚构系统额定容量5，当前损伤z使可用容量c=5−z；本例窗口内z始终在0至5之间。初始z₀=0，第0轮需求7，缺口g₀=max(0,7−5)=2，规定本轮无恢复且缺口写入损伤，故z₁=2。之后每轮需求3，缺口为max(0,3−c)，并按z_{t+1}=max(0,z_t+g_t−1)恢复1单位：第1轮c₁=3，输出3，z₂=1；第2轮c₂=4，输出3，z₃=0；第3轮c₃=5。第1轮输出已满足需求，但可用容量与余量尚未回到5与2。","assumptions":"人为设定的损伤形成及恢复规则；输出=min(需求,容量)，无其他冲击、输入或容量调整。","boundary":"真实过载未必形成这种损伤；模型只证明“输出达标”与“储备恢复”可不同步。"},{"title":"数学构造：即时缺口不必留下损伤","text":"另设同样额定容量5的虚构系统，每轮容量都为5且不保留损伤。需求第一轮7、第二轮3，输出5、3，第一轮未满足2件；若未完成任务按公开规则结束而不积压，则第二轮没有由此前缺口留下的状态差异。不能只因为发生过2件缺口，便强加上一例的损伤方程。","assumptions":"明确无积压、无持续损伤；未满足任务本身仍有本轮损失，并非被称为没有影响。","boundary":"不适用于已知有积压、持续伤害或其他载体的现实对象。"},{"title":"数学构造：三个真实比例可以回答不同问题","text":"虚构社区灾前有100个账户，当前有90个，80个符合本次安全接入条件且全部恢复连接，实际使用者70个；假设各集合与时点已经核对且无重复计数。则符合条件者连接率80/80=100%，灾前账户中恢复连接的比例80/100=80%，当前账户中实际使用比例70/90≈77.8%。三个分子分母各有含义，不能把100%改写为所有灾前账户都恢复使用。","assumptions":"纯教学数字，连接账户、实际使用和安全资格是不同字段；假设恢复连接的80个均属于灾前及当前集合。","boundary":"不对应波多黎各实际人数，不评估用电质量、连续性或健康结果。"}],"counterexamples":[{"identity":"constructed_boundary","text":"平均需求低于平均容量，所以每个位置都没有负荷问题。","effect":"不能消除局部超载和不可调度性。","sourceIds":["theory"]},{"identity":"constructed_boundary","text":"临时发电或持续外援仍在，因此当地功能从未真正恢复。","effect":"支持可以构成真实功能恢复，应明确条件、持续性和范围。","sourceIds":["theory"]},{"identity":"constructed_boundary","text":"某次新冲击导致再次中断，所以此前限定时间内供给恢复的记录都是假的。","effect":"不同窗口和冲击须分别核，不能反向抹去准确事实或直接推定欺骗。","sourceIds":["theory"]},{"identity":"constructed_boundary","text":"中心产量恢复，所以人员休整、备件、维护积压、外部照护负担都恢复了。","effect":"输出与内外储备及分布分别取证。","sourceIds":["theory"]}],"questionAnswers":[{"question":"两点容量总和10、需求总和8，为什么仍可剩3件？","answer":"需求集中于容量5的第一点且本窗口不能调度，局部缺口不能被第二点闲置容量自动抵消。","basis":"本节原文及上述公开推导"},{"question":"损伤例第1轮输出3已满足需求，为什么不能说余量恢复？","answer":"当时容量只有3，需求3，余量0；额定容量5下同需求的余量2尚未回来。","basis":"本节原文及上述公开推导"},{"question":"支持设备下功能达标，必须先撤设备才算真实恢复吗？","answer":"不必。按原支持条件已可成立；撤援后的独立维持是另一个主张，不能为验证而撤去必要支持。","basis":"本节原文及上述公开推导"},{"question":"资格人群连接率100%能否推出灾前账户连接率100%？","answer":"不能，分母不同；构造中前者80/80，后者80/100。","basis":"本节原文及上述公开推导"},{"question":"再次失稳应比较哪些解释？","answer":"旧损伤延续、储备未补回、支持中断、新冲击和测量口径改变，并核各自时序与载体。","basis":"本节原文及上述公开推导"}],"figures":[{"path":"/reading-assets/S-6-6/figures/section-6-6.png","alt":"负荷口径，同类型／单位／位置／窗口，峰值与持续容量分开；即时缺口，需求进入指定通道，不自动留下累积损伤；跨窗载体，损伤／储备／积压，额外历史主张才加G3；恢复什么、对谁，输出／K或F／内部余量，分子分母不可偷换；支持与持续，临时支持也可真实有效，核到期与已运行承接；分布与再次失稳，内部休整、外部负担，旧损伤／新冲击另比。六卡区分同窗缺口、载体跨窗及恢复条件；不以支持依赖取消有限功能，也不把有限功能升成全面恢复。","caption":"六卡区分同窗缺口、载体跨窗及恢复条件；不以支持依赖取消有限功能，也不把有限功能升成全面恢复。"}],"diagramBrief":"当前交付为静态图；交互尚未实现，以下涉及选择、切换或点击的内容仅为后续设计设想。静态六卡把即时与累积分开，恢复分别核功能/人群/支持/时间。缺口到跨窗载体的箭头标明必须另有证据，非必然损伤。","applicability":{"realCase":"applicable","diagram":"applicable","reason":"官方调查把恢复分母、支持条件和持续性直接区分；局部负荷、损伤轨迹及账户比例均另标数学构造，不冒充灾区数据。"},"openQuestions":[],"taskId":"S-6-6","sources":[{"id":"theory","title":"Xikari-条件结构与转化论，用户提供原文","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"现行全文第1368—1383行；每节精确范围见sourceRefs","claim_support":["6.6：术语、合同、论证责任和原文边界；不据此认证经验事实"],"limits":["作者理论文本，是被解释对象，不替代外部经验资料；技能5.3.1不等于理论版本。"],"access_status":"read"},{"id":"gao-restoration","title":"GAO-19-296：波多黎各恢复口径与临时供电","url":"https://www.gao.gov/assets/gao-19-296.pdf","source_type":"primary","version_or_date":"2019-04-18","locator":"印刷pp.6–7，Status of electricity restoration及Figure 1后段","claim_support":["6.6：2018年8月安全可接电客户的恢复口径不等全部灾前客户；2018-12-11 USACE支持7台发电机服务Vieques/Culebra微电网。"],"limits":["PREPA估计由GAO转述且明示局限；本例不使用源图曲线、不推居民全方面恢复或欺骗意图。"],"access_status":"partially_read"},{"id":"theory-history","title":"Xikari4.5：载体跨窗与历史增量","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"第620—640行","claim_support":["6.6：当前损伤/容量载体与表示之外历史增量分开，后者另需G3。"],"limits":["构造方程不证明现实损伤机制。"],"access_status":"read"},{"id":"theory-types","title":"Xikari4.4与4.11.2：通道逐维和同型量","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"第610—619行；第730—743行","claim_support":["6.6：G2只及指定通道、所测维度；跨类型比较须单位、核算与转换映射。"],"limits":["不能由形式加减推统一成本或授权。"],"access_status":"read"}],"lecturePath":"/reading-assets/S-6-6/lecture.md","sourcesPath":"/reading-assets/S-6-6/sources.json","sourceSlicePath":"/reading-assets/S-6-6/source-slice.md","supplementaryFiles":[],"diagramsPath":"/reading-assets/S-6-6/diagrams.md"},"6.7":{"title":"6.7　CM-PHASE 相位与阈值转换","lead":"一个系统可以在不同区间用不同方式运转，但图上看起来有一条折线，还不能说明它被某个原因触发，更不能说明它经历了必然升级。先确认仍是所说的同一对象，再辨认模式、触发、持续和历史各需什么证据。","explanation":["原文定位：第1384—1397行；原文锚点 section-6-7；短引文：‘相同曲线形状不能替任一路线取证’。本题源切片逐字附后，讲解与原文分开。","基础依赖是D0和D1。固定同一候选对象合同及K，事前登记状态变量、候选参数或触发条件、阈值，并检查噪声和分箱稳健性，才能检验至少两个可重复区分的运转区间。“同一K”不仅是文字没改，还要求对象在所比较区间继续满足该同一性判据；若旧K已失效，不能用相位名义掩盖对象变化。","pattern分支只登记区间—阈值模式。其共同方法门为E4和EVIDENCE，须处理连续趋势、噪声、测量分类等竞争解释，但不以因果识别为所有模式分类的前置门。可重复观测到不同区间，并不等于已经知道是什么造成转移。","causal-trigger分支才要求指定触发通道、通道干预或有识别条件的自然变异，并另有G2-instance定位触发作用，同时增加CAUSAL责任。时间顺序、阈值附近变化或预测准确都不足以单独消除共同输入、反向作用或选择；因果主张比模式登记多承担材料。","carried-persistence分支解释当前载体如何在同一K下维持相位、跨窗持续或迟恢复，须有载体、时序、纵向比较和相称因果证据。hysteretic在本书中特指历史增量型迟滞：相对于明示当前表示，历史还提供条件增量，另需G3。一般领域里看到迟滞环可有自己的物理或经验解释，但不能仅凭环形曲线追授本分支资格。","若当前载体已记录决定后续的状态，路径影响可完全由当前状态承接，额外历史增量便可能消失。基础可逆相位更不必须有历史路径。若只做预测性历史比较，它不会因为被叫“迟滞”而自动升级为历史因果；因果触发、载体持续机制及历史因果解释分别加相称CAUSAL责任。","三类反向情形应改记不同结果：同一状态分布中的连续趋势已足够解释，则不保留没有必要的相位划分；阈值随任意分箱变动，则优先考虑测量分类效果；转移前K已失效，则检对象转换、解体或重新分类。若进一步主张正式对象转换，仍依相应映射和G4合同，不能只靠K字样变化自动认证。","稳健性不是要求所有阈值都一样，而是事先说清对哪些噪声范围、分箱选择和观察窗口仍可复核。边界附近未能可靠分类时应保留过渡/未决区，不事后删掉难看点。区间重复出现也不自动说明它是不可逆成熟阶段。","本节的相位不是S0—S6必经序列。新相位未必更高效、更正当或拥有更大授权；逆转也不自动退步。比较优劣、承受代价和实施干预仍需预定任务、规范与权限，不能由图形方向决定。"],"distinctions":[{"leftTitle":"相位模式","leftText":"同一对象下重复可分的区间—阈值关系。","rightTitle":"触发因果","rightText":"指定通道改变造成区间转移，需额外识别。"},{"leftTitle":"载体持续","leftText":"当前内部状态承接过去并维持相位。","rightTitle":"额外历史迟滞","rightText":"在明示当前表示之外还存在增量，另需G3。"},{"leftTitle":"物理曲线有环","leftText":"可提示路径或状态记忆，但须核模型与测量。","rightTitle":"历史增量资格","rightText":"不能仅由形状决定，也不自动是因果。"},{"leftTitle":"同对象不同区间","leftText":"对象继续满足原K。","rightTitle":"对象转换/解体","rightText":"原K失效或合同改变，另行判断。"}],"boundaries":["基础模式不硬需G3或全部因果门；没有触发识别也可保留恰当的描述模式。","重复区间不能靠任意分箱人为制造；已知连续关系要作为竞争解释。","当前状态已充分时，额外历史为零不取消载体持续，也不取消可逆相位。","K不能为得到相位结论而事后重写；同一性必须按原任务和材料核对。","自然界物理相与社会系统运转区间没有自动等价或阶段映射。"],"questions":["模式反复出现，但触发通道尚未识别，是否必须删掉全部模式描述？","第一构造为何h=0.5能区分有噪声状态？","迟滞模型给定p=1.5但不知道s，能否唯一算下一步？给定(p,s)呢？","所有相位研究都需要CAUSAL作为基础门吗？","新相位出现为何不能直接说更好？"],"diagramPath":"/reading-assets/S-6-7/figures/section-6-7.png","caseLinks":[{"title":"NIST三相点池：物理相与对象边界先分清","href":"https://www.nist.gov/video/triple-point-cell"}],"caseNotes":[{"title":"NIST三相点池：物理相与对象边界先分清","text":"NIST在2016年12月21日发布的三相点池说明中，描述了含特定同位素组成水的密闭玻璃容器，以及池内形成固、液、气三相平衡的状态。用于本节时，可以明确以“该密闭容器及内容物”为候选对象，再研究内部相态；这一步对象划分是分析者声明，不能把内部出现不同物态自动写成容器对象更换。","sourceLabel":"NIST Triple-Point Cell，2016-12-21","sourceUrl":"https://www.nist.gov/video/triple-point-cell","sourceLocator":"网页正文单段（Triple-Point Cell说明）及Uploaded On日期；本讲依据文字说明，不宣称审阅视频测量","boundary":"来源支持实际计量装置的相态说明；不提供本框架完整预注册阈值/噪声检验，也不证明任何组织拥有同样相位或成熟序列。","href":"https://www.nist.gov/video/triple-point-cell"}],"sourceRefs":[{"section":"6.7","start_line":1384,"end_line":1397,"startLine":1384,"endLine":1397}],"outputId":"section-6-7","sourceHash":"df579dbdbb68442b1781b066606c267761f0a1673fbd034ce93eeeb41641439f","argumentSteps":["固定完整对象合同及K，核比较各区间仍满足同一性，不事后换K保住结论。","事前登记状态、参数、阈值、噪声容差和分箱检验，先判断可重复模式。","模式只报告区间关系；若要说触发原因，另给G2指定通道及相称因果识别。","若要说持续或迟恢复，定位当前载体与跨窗作用；若另说额外历史增量，再核G3。","把预测性历史收益与历史因果区别开，曲线形状不代替分支材料。","对连续趋势、分箱效应、K失效分别改记合适结果；正式转换主张另核其合同。","保持模式、机制、任务优劣和行动授权各自范围，不画自动成熟阶梯。"],"teachingExamples":[{"title":"数学构造：可逆两区间没有历史记忆","text":"虚构同一控制单元持续满足预定K，输入p∈[0,4]，状态规则x=0当p<2，x=1当p≥2；测量y=x+ε，|ε|≤0.1。两输出区间分别[-0.1,0.1]与[0.9,1.1]，任取分类界限h∈(0.1,0.9)都能区分。输入1.5→2.5→1.5给状态0→1→0，只依当前p，不需保存历史。规则在模型中给定，说明模式和可逆性可以不含额外历史。","assumptions":"确定性状态规则加有界测量误差；p准确测量，阈值2及噪声界在计算前指定，K不依x为0或1而改变。","boundary":"两区间是数学设定而非真实重复测量；现实的pattern或因果触发资格仍需各自材料。"},{"title":"数学构造：分箱能制造假的跳变印象","text":"另设真实模型y=p，p在[0,4]连续变化，没有状态跳变。报告者只公布标签L=0当y<2、L=1当y≥2，图上标签突然跳变；把分箱界改成3，标签跳变点也移到3，但原始y=p没有改变。分类阈值随报告规则移动，不足以证明对象发生相位转换。","assumptions":"连续函数完整已知，标签规则是分析者的人为分箱；没有真实观察数据。","boundary":"不否认所有离散分类都有用途，只说明分类用途与对象相位识别不同。"},{"title":"数学构造：迟滞环可以由当前载体充分承接","text":"设状态s∈{0,1}，规则为p≥2时s′=1，p≤1时s′=0，1<p<2时s′=s，输出为s′。路径A从p=0.5进入1.5，当前s=0；路径B从p=2.5进入1.5，当前s=1。同样p=1.5可见不同输出，但完整当前表示(p,s)已决定下一步；只登记p会漏掉已知载体s。这个带记忆的模型解释为何有迟滞形状并不自动要求完整当前表示之外的额外历史。","assumptions":"规则与初始端点人为给定，没有其他噪声或隐藏状态；必须公开s，不删除它来制造历史收益。","boundary":"不以数学载体充分性否认现实历史增量，现实比较仍按所选表示和G3条件取证。"},{"title":"教学构造：同一性判据决定问题边界","text":"对虚构灯具，若预定K是同一编号机壳与接线组件仍组成该装置，亮/灭可以是同一对象内状态。若另一个任务的候选对象是“正在燃烧的这一次火焰”，火焰熄灭后其K可能已不成立；不能把新点燃的火焰一概说成原对象换了相位。具体K必须先与任务说明，而非看到结果再任选。","assumptions":"对象与判据均是教学构造，不宣称任何一个K是唯一自然边界。","boundary":"字段定义只声明候选，不由此证明现实对象有效或正式转换。"}],"counterexamples":[{"identity":"constructed_boundary","text":"先按任意阈值把连续得分分成两组，再以两组证明自然相位。","effect":"分类规则本身不能成为对象区间模式的独立证据。","sourceIds":["theory"]},{"identity":"constructed_boundary","text":"观察到迟滞环，未测当前载体就宣布历史增量因果已证。","effect":"曲线形状不能替代载体控制、G3和相称因果依据。","sourceIds":["theory"]},{"identity":"constructed_boundary","text":"原对象同一性已失效，但仍称同一对象进入更成熟相位。","effect":"对象边界和价值升级同时越界，应检转换/解体并另评目标。","sourceIds":["theory"]}],"questionAnswers":[{"question":"模式反复出现，但触发通道尚未识别，是否必须删掉全部模式描述？","answer":"不必，按pattern有限记录区间关系；触发因果单列未决。","basis":"本节原文及上述公开推导"},{"question":"第一构造为何h=0.5能区分有噪声状态？","answer":"低区间最高0.1，高区间最低0.9，0.5位于间隙内；h在(0.1,0.9)均可。","basis":"本节原文及上述公开推导"},{"question":"迟滞模型给定p=1.5但不知道s，能否唯一算下一步？给定(p,s)呢？","answer":"只知p不能，s可为0或1；知道完整(p,s)则s′=s，未来由当前载体决定。","basis":"本节原文及上述公开推导"},{"question":"所有相位研究都需要CAUSAL作为基础门吗？","answer":"不需要，模式分支的共同门是E4/EVIDENCE；提出因果触发、载体持续机制或历史因果解释时追加相称因果责任。","basis":"本节原文及上述公开推导"},{"question":"新相位出现为何不能直接说更好？","answer":"相位只分类运行区间，任务收益、代价、规范和权限另有判断。","basis":"本节原文及上述公开推导"}],"figures":[{"path":"/reading-assets/S-6-7/figures/section-6-7.png","alt":"共同起点，同一候选合同且K成立，变量、阈值、噪声分箱；pattern 模式，可重复区间—阈值，不先宣称触发因果；causal-trigger，指定通道与识别比较，另加G2和因果责任；carried-persistence，当前载体跨窗维持，时序与因果材料；hysteretic 增量，相对当前表示另核G3，预测不自动升为因果；反向检查，连续趋势／分箱效果，K失效则另检对象。四类分支不互相冒充；相同曲线形状不证明全部机制，新相位不自动更好或更有权。","caption":"四类分支不互相冒充；相同曲线形状不证明全部机制，新相位不自动更好或更有权。"}],"diagramBrief":"当前交付为静态图；交互尚未实现，以下涉及选择、切换或点击的内容仅为后续设计设想。六卡包含共同起点、四分支和反向检查。没有从模式自动升级到历史或价值的箭头；触发箭头明确须额外主张与材料。","applicability":{"realCase":"applicable","diagram":"applicable","reason":"官方计量装置说明提供具体物理相态与边界辨认；可逆、分箱和迟滞证明另用完整假设的数学模型，不把物理类比替代社会证据。"},"openQuestions":[],"taskId":"S-6-7","sources":[{"id":"theory","title":"Xikari-条件结构与转化论，用户提供原文","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"现行全文第1384—1397行；每节精确范围见sourceRefs","claim_support":["6.7：术语、合同、论证责任和原文边界；不据此认证经验事实"],"limits":["作者理论文本，是被解释对象，不替代外部经验资料；技能5.3.1不等于理论版本。"],"access_status":"read"},{"id":"nist-phase-cell","title":"NIST：Triple-Point Cell装置说明","url":"https://www.nist.gov/video/triple-point-cell","source_type":"primary","version_or_date":"2016-12-21","locator":"正文单段及Uploaded On日期","claim_support":["6.7：NIST说明密闭玻璃池中的水及其固、液、气三相平衡；2016-12-21发布。"],"limits":["仅核网页文字说明，不引用视频帧或测量数值；候选对象合同为本讲条件分析，并非NIST采用Xikari框架。"],"access_status":"read"},{"id":"theory-d0d1","title":"Xikari3.1—3.2：对象与状态词","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"第425—461行","claim_support":["6.7：K为同一性判据，同对象状态变化与K失效分开；演化不内含成熟或价值。"],"limits":["声明候选不证明对象经验有效。"],"access_status":"read"},{"id":"theory-history","title":"Xikari4.5：当前载体与额外历史","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"第620—640行","claim_support":["6.7：载体持续与表示之外增量分开，不可删已知当前状态制造增量。"],"limits":["预测增量不自动是历史因果。"],"access_status":"read"},{"id":"theory-g4","title":"Xikari4.6：尺度闭合与转换","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"第642—648行","claim_support":["6.7：进一步作正式对象转换主张时，须有相应映射与预选G4实例条件。"],"limits":["相位名或K文字变化不自动认证转换。"],"access_status":"read"}],"lecturePath":"/reading-assets/S-6-7/lecture.md","sourcesPath":"/reading-assets/S-6-7/sources.json","sourceSlicePath":"/reading-assets/S-6-7/source-slice.md","supplementaryFiles":[],"diagramsPath":"/reading-assets/S-6-7/diagrams.md"},"6.8":{"title":"6.8　CM-SELECTION 变异—差异保留—再生产","lead":"看到某种做法或类型留下来，很容易倒过来讲“它必然更优”。本节先不评价优劣，而要检查：有哪些变异，结果怎样不同，差异是否真的进入下一轮，并且不是抽样运气就足以解释。","explanation":["原文定位：第1398—1411行；原文锚点 section-6-8；短引文：‘一次存续不等于差异保留’。本题源切片逐字附后，讲解与原文分开。","D1只给变化、演化等状态词的使用规则，不能由“发生演化”直接推出筛选。CM-SELECTION是另作操作化的条件机制：E4、CAUSAL、EVIDENCE承担竞争解释、因果和材料审查，概念故事不产生实证支持。基础模式不硬依赖G2或G3，但仍须完整检查V、D、R、下一轮、重复轮次与漂变竞争。","V是结果前定义的可区分变异及其来源；不能先看赢家再把赢家共有特征当成事前变量。D是在可比环境中超过预定阈值的差异结果，分母、暴露和机会条件需相称；群体数量增加不直接等于每单位保留或再生产能力提高。R指使这种差异进入下一轮的保留，并有重复轮次可复核，不仅是本轮统计上的差别。","pattern分支登记具备这些连接的筛选模式，必须比较漂变、共同外因和抽样偏差。随机抽样也能造成某类型长期占优，样本中没有看见另一类型也可能只是漏采。若漂变模型已在相称充分性条件下解释观察，就不登记超出它的筛选模式；单纯未显著又不等于已证明漂变充分，须保留判断精度与失败记录。","carrier分支在模式之外，进一步指出是哪条保留或再生产通道承载差异，并由通道扰动或具识别条件的自然变异以及G2-instance定位。扰动候选通道后保留不变，不能继续把它当成所称具体机制；同时要核扰动确实生效、替代路径和测量条件。指定通道未支持不自动取消其他材料已支持的模式。","history分支在模式之外另检跨轮历史项相对当前状态控制后的条件增量，由G3支持。重复轮次是基础模式要求，额外历史增量是另一要求；反复发生不意味着给定完整当前状态后历史仍额外有用。反之，一个历史变量有预测力也不单独证明V/D/R和筛选通道已成立。","缺项时应停在恰当层级：只有变化而没有D，记变动；只有一次差异，没有R、下一轮和复现，记一次结果；漂变充分，不增设筛选解释；指定再生产机制未被区分，保留模式或候选而不捏造通道。结果不符合预期，也不能事后改V、阈值、环境或历史控制来救援原主张。","被保留并不表示更高级、更正当，甚至不意味着在所有环境和所有任务上更好。某类型能在特定条件下复制较多，只是一个有限过程结果；环境改变、权衡、频率依赖和共同存在都可能限制“永远胜出”的叙事。","系统筛选、行动主体选择、集体治理选择是三件事。系统筛选可能没有统一决策者；主体选择需要具体主体、选项和决策证据；集体治理另需规范前提、J轴授权及O程序。不能说“机制留下了这种制度”就替公众作同意判断，或据此授权淘汰人和分配资源。"],"distinctions":[{"leftTitle":"变化/演化","leftText":"登记状态或对象合同字段改变。","rightTitle":"筛选模式","rightText":"要有V/D/R、下一轮、重复及漂变竞争。"},{"leftTitle":"一次结果差异","leftText":"这一轮不同类型结果不同。","rightTitle":"差异保留","rightText":"差异实际进入后续轮次且可复核。"},{"leftTitle":"筛选模式","leftText":"有限条件下的差异保留结构。","rightTitle":"具体机制","rightText":"另识别指定载体/再生产通道。"},{"leftTitle":"系统保留","leftText":"过程使一些类型延续或增加。","rightTitle":"治理决定","rightText":"需要主体、选项、规范、授权及程序。"}],"boundaries":["随机漂变可能产生持久占优，长时间存在不是排除漂变的捷径。","当前状态足以决定后续时，可以有重复筛选而无额外历史增量。","差异再生产可伴随共存，并非必然使其他类型消失。","某通道扰动没有预期效应时，应限于该通道与比较条件，不泛化为所有筛选不可能。","过程优势不等于道德优越、行动许可或某人的牺牲义务。"],"questions":["第一构造第三轮A比例是多少？","每轮末重置4比4，为什么不能把中间8比4当跨轮保留？","纯漂变例下一代全A概率1/4，能说明什么、不能说明什么？","已见模式但通道扰动未显示预期变化，是否可以保留模式？","反复差异保留是否自动满足G3历史增量？"],"diagramPath":"/reading-assets/S-6-8/figures/section-6-8.png","caseLinks":[{"title":"长期演化实验中的共存：筛选不必只留一个赢家","href":"https://pmc.ncbi.nlm.nih.gov/articles/PMC2430337/"}],"caseNotes":[{"title":"长期演化实验中的共存：筛选不必只留一个赢家","text":"Blount、Borland和Lenski的2008年原始研究，在关于频率依赖筛选的结果节报告：将Cit−与Cit+类型以不同初始比例组合后，两者在后续多轮中共存；Cit−趋向一个少数比例，而非被Cit+完全消灭。作者将这一结果解释为负频率依赖筛选维持多样性。本节关注有类型、跨轮轨迹与竞争条件的证据，而不是只看谁在最后留下。","sourceLabel":"Blount等，PNAS 105(23):7899–7906，2008-06-10刊期","sourceUrl":"https://pmc.ncbi.nlm.nih.gov/articles/PMC2430337/","sourceLocator":"Results：Frequency-Dependent Selection Maintains Ecological Diversity，前两段；Methods：Test for Frequency-Dependent Interaction","boundary":"保留原研究限定条件下的生态结论；不将论文追授为本框架正式G2/G3，不外推所有环境、不把保留者称为更高等或更正当。","href":"https://pmc.ncbi.nlm.nih.gov/articles/PMC2430337/"}],"sourceRefs":[{"section":"6.8","start_line":1398,"end_line":1411,"startLine":1398,"endLine":1411}],"outputId":"section-6-8","sourceHash":"df579dbdbb68442b1781b066606c267761f0a1673fbd034ce93eeeb41641439f","argumentSteps":["结果前定义变异及来源、可比环境、差异结果、阈值和下一轮单位。","分别核D的分母与机会条件、R的保留连接，以及多个后续轮次。","与漂变、共同外因和抽样偏差作相称比较，不能只凭一次优势或长期存在。","先报告模式层；指定保留/再生产机制另加通道识别和G2，不把名称当因果。","额外跨轮历史另控当前状态并核G3，不把重复本身当历史条件增量。","缺项时收窄为变动、一次结果、模式或未决；每条失败条件明确保留。","从过程支持到价值、主体意图和治理权限均需另给桥接材料，不自动升级。"],"teachingExamples":[{"title":"数学构造：差异复制怎样进入下一轮","text":"虚构两类标记A/B，初始各4个。每轮A标记产生2个同类后继，B产生1个，同一规则、无容量约束、无突变和随机抽样。第一轮为A=8、B=4，A比例2/3；第二轮A=16、B=4，比例4/5。一般若当前比例p∈(0,1)，下一轮p′=2p/(1+p)，差值p′−p=p(1−p)/(1+p)>0。V是事前两类型，D是单位复制数2与1，R是同类后继保留，重复轮次来自同一规则递推。","assumptions":"完全指定的非生物标记复制模型，没有真实实验；确定规则排除了随机漂变，而非用数据检验排除它。","boundary":"只证明给定模型中的差异保留，不证明现实机制、无限可用资源或A在任何价值上更优。"},{"title":"数学构造：有一轮差异却没有跨轮保留","text":"沿用模型，但每轮结束后，外部规则丢弃全部后继并重新放入4个A、4个B。每轮中间仍可看到8比4，却没有把这一差异带入下一轮的初始状态；各轮起点一直1/2。若预定所问是跨轮频率演变，不能把中间结果当成已完成的R链。","assumptions":"重置规则公开，分析单位是完整一轮及其下一轮起点；数字为构造。","boundary":"若改问轮内复制差异，可以保留相应结论，不能因跨轮失败否定所有局部事实。"},{"title":"数学构造：纯漂变也能很快固定","text":"虚构仅有A、B各一个的群体。每代独立、有放回地从两个父标记中等概率抽两次，分别复制其类型，形成大小仍为2的下一代；两类型没有能力差异。下一代全为A的概率是(1/2)²=1/4；一旦全A，之后无突变时都保持A。故持久全A可以来自纯抽样，而非A有较高的单位再生产率。","assumptions":"抽样规则和无突变是数学设定，父标记等概率；未真实抽样。","boundary":"不由“漂变也可能”直接否定所有现实筛选；现实需比较概率、重复材料及预定判据。"},{"title":"数学构造：重复选择不需要额外历史","text":"在第一构造中，给定当前p和固定复制规则，p′已经由2p/(1+p)唯一决定。任何两段历史只要到同一p，下一步比例就相同；历史可解释如何来到当前p，但不再提高这一预定下一步预测。若现实还有未记录的可遗传差异、环境或载体，则不能直接沿用这个充分性结论。","assumptions":"当前表示含本例所需全部状态和规则，不隐藏其他差异。","boundary":"不把模型的零额外增量当成现实G3的零结论证据。"}],"counterexamples":[{"identity":"constructed_boundary","text":"只看到一类长期留下，就断言它必有更高差异保留能力。","effect":"等概率漂变可产生持久固定，仍要比较其他解释。","sourceIds":["theory"]},{"identity":"real_counterevidence","text":"Blount等2008年研究的相关生态比较中，Cit+并未固定，Cit−仍为少数并与其共存。","effect":"限制“新有利类型必然消灭其他类型”的普遍说法；优势与保留依具体环境和频率。","sourceIds":["blount2008"]},{"identity":"constructed_boundary","text":"某制度经长期竞争留下，所以所有人都选择、同意且应服从它。","effect":"系统保留不能证明主体决策、公众同意或治理授权。","sourceIds":["theory"]},{"identity":"constructed_boundary","text":"只有一次差异，没有后续追踪，就宣布已识别跨轮路径机制。","effect":"缺R、下一轮、重复及当前控制等不同材料，应停在一次结果。","sourceIds":["theory"]}],"questionAnswers":[{"question":"第一构造第三轮A比例是多少？","answer":"A=32、B=4，比例32/36=8/9；也可把p=4/5代入2p/(1+p)。","basis":"本节原文及上述公开推导"},{"question":"每轮末重置4比4，为什么不能把中间8比4当跨轮保留？","answer":"中间差异被重置，未进入下一轮的起始状态；应明确任务所指的轮次边界。","basis":"本节原文及上述公开推导"},{"question":"纯漂变例下一代全A概率1/4，能说明什么、不能说明什么？","answer":"能说明持久优势不逻辑蕴含能力差异；不能据此判所有现实优势都由漂变造成。","basis":"本节原文及上述公开推导"},{"question":"已见模式但通道扰动未显示预期变化，是否可以保留模式？","answer":"可按其独立材料保留模式，具体通道机制则未支持或未决，并核扰动实施及替代路径。","basis":"本节原文及上述公开推导"},{"question":"反复差异保留是否自动满足G3历史增量？","answer":"不自动，G3问的是控制明确当前状态后历史是否仍有额外条件增量。","basis":"本节原文及上述公开推导"}],"figures":[{"path":"/reading-assets/S-6-8/figures/section-6-8.png","alt":"V 可区分变异，结果前定义及来源，不是事后挑赢家特征；D 差异结果，可比环境、分母、阈值，机会与抽样须核；R 进入下一轮，保留与重复轮次，不只一次结果；模式竞争解释，漂变／共同外因／漏采，持久存在不排除漂变；具体载体分支，指定通道与识别比较，模式之外加G2；跨轮历史分支，控制明确当前状态，额外增量另加G3。六卡分开模式、具体载体与历史分支；被保留不自动更优，系统筛选不等于治理选择。","caption":"六卡分开模式、具体载体与历史分支；被保留不自动更优，系统筛选不等于治理选择。"}],"diagramBrief":"当前交付为静态图；交互尚未实现，以下涉及选择、切换或点击的内容仅为后续设计设想。上排给V/D/R连接，下排给模式竞争和两个附加分支。不画从筛选到道德优越或治理权限的箭头。","applicability":{"realCase":"applicable","diagram":"applicable","reason":"原始研究具体报告跨轮共存及作者的频率依赖解释，适合限制一轮赢家叙事；数学标记例与原研究数据分开，不提供实验操作方案。"},"openQuestions":[],"taskId":"S-6-8","sources":[{"id":"theory","title":"Xikari-条件结构与转化论，用户提供原文","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"现行全文第1398—1411行；每节精确范围见sourceRefs","claim_support":["6.8：术语、合同、论证责任和原文边界；不据此认证经验事实"],"limits":["作者理论文本，是被解释对象，不替代外部经验资料；技能5.3.1不等于理论版本。"],"access_status":"read"},{"id":"blount2008","title":"Blount等：长期实验群体中的历史偶然性与创新","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC2430337/","source_type":"primary","version_or_date":"2008-06-04在线；2008-06-10刊期；DOI 10.1073/pnas.0803151105","locator":"Results：Frequency-Dependent Selection Maintains Ecological Diversity前两段；Methods：Test for Frequency-Dependent Interaction","claim_support":["6.8：Cit−/Cit+不同起始比例后的多轮共存，作者解释为负频率依赖筛选维持多样性。"],"limits":["仅引用该研究的生态结果段，不声称本文已复现原实验或读过补充实验数据；不追授正式框架实例。"],"access_status":"partially_read"},{"id":"theory-d1","title":"Xikari3.2：D1状态词","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"第450—461行","claim_support":["6.8：演化定义不蕴含筛选、方向或价值。"],"limits":["独立机制须自身操作化与证据。"],"access_status":"read"},{"id":"theory-c8","title":"Xikari4.13.1：C8筛选","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"第837—853行","claim_support":["6.8：差异、保留、下一轮、重复、竞争解释与条件分支分开。"],"limits":["有限模式不生成主体选择和规范授权。"],"access_status":"read"}],"lecturePath":"/reading-assets/S-6-8/lecture.md","sourcesPath":"/reading-assets/S-6-8/sources.json","sourceSlicePath":"/reading-assets/S-6-8/source-slice.md","supplementaryFiles":[],"diagramsPath":"/reading-assets/S-6-8/diagrams.md"},"6.9":{"title":"6.9　共演化的条件","lead":"两个人、两套制度或两个物种一起变化，并不一定在相互塑造。共演化要查两个方向分别怎样起作用；即使最后都回到同一点，途中速度、风险和可干预的位置也可能完全不同。","explanation":["原文定位：第1412—1419行；原文锚点 section-6-9；短引文：‘同终态不是同机制’。本题源切片逐字附后，讲解与原文分开。","提出共演化候选的条件是：两个候选对象相互改变对方的环境、可行路径、指定通道或保留条件，且双向作用在各自窗口内可追踪。“共”指相互作用结构，不是两个曲线同时向上，也不保证彼此帮助。","应分别登记两份完整D0对象合同、各自的同一性判据K和SP/T。不能把一个总系统名称代替两边对象，也不能把K叫作全部合同。两边可有不同时间粒度、更新周期和可见范围；需要把事件时序对齐，说明A改变B后何时可能返回影响A，避免用日数据与年数据的表面相关制造同步机制。","双向G2通道分别承担识别责任。A→B得到支持，并不自动证明B→A；只做一次同时改变两者的干预，也未必能区分两个方向。记录传导内容、作用位置、前后顺序、比较条件和速度差异，并对第三方环境共同改变双方、单向依赖和测量协议同步作相称检验。","跨轮作用要按4.5分别查两边的当前载体、保留/更新、实际调用和纵向比较。只有另声称当前表示之外的额外历史条件增量时，才分别追加相应G3。一个方向有额外增量，不能把另一方向的增量也视为自动成立；两边都有持久载体也不必然都有额外历史收益。","共演化不要求双方对称。传导强度、速度、成本、依赖程度和可退出性可很不一样；它还可以是对抗关系，而非互利。即使双向影响已证，也不能直接推出价值一致、公众同意、继续关系的义务或任何一方取得处置权。","同终态不是同机制。固定点是更新后保持不动的状态，存在固定点本身不保证轨迹收敛。只有另证收敛后，才能讨论该轨迹的长期终值；更新规则还决定回归速度、瞬态峰值与干预响应。若任务仅是某条件下长期终值，较简表示可能充分；一旦改问两步内达标、峰值、定向改变谁或支持撤除后的表现，就必须保留相关差异并重新检验。","恢复、共演化和跨圈层接续都可能出现终值相同但过程不同。不能把两条曲线最终靠拢当成双向通道识别，也不能因原来的长期摘要准确，就让它包办新的行动任务。保持“哪种表示对哪个目标、期限和操作足够”的范围，才不会把模型简化当成世界唯一机制。"],"distinctions":[{"leftTitle":"共同变化","leftText":"两边在同一时期有变化。","rightTitle":"双向作用","rightText":"两条作用路径分别有材料，不能靠相关代替。"},{"leftTitle":"相互作用","leftText":"两边都能影响另一边。","rightTitle":"对称或互利","rightText":"大小、速度、收益和负担还须分别测量。"},{"leftTitle":"同一固定点","leftText":"两规则共享更新后不动的状态；只有另证收敛时才能谈同一长期极限。","rightTitle":"同一动力与干预机制","rightText":"更新、瞬态和操作响应相同，是更强且不同的主张。"},{"leftTitle":"载体跨轮","leftText":"当前状态保存过去并影响后来。","rightTitle":"额外历史增量","rightText":"给定当前表示后历史仍增益，两个方向各自另核。"}],"boundaries":["只有一个方向可识别时，保留单向作用，不补写另一方向。","共同环境或统一测量时点可制造同步，不能把报表节奏当对象耦合。","在一个任务下充分的终值摘要，不能自动用于期限、峰值或定向干预。","关系能持续不产生继续维持的义务；双向影响也可能放大损害。","真实案例本讲只援引原作者公开摘要所报告的结论；实验方法和逐项数据未在此独立复核，不作正式G实例认证。"],"questions":["两个模型都收敛到0，为什么第二步达标结论不同？","只增加当前y一单位，两模型下一步x差多少？","A影响B，B又有变化，是否已经足够双向共演化？","双向都存在持久载体，是否两边必须有G3？","共演化关系可否不对称且对抗？"],"diagramPath":"/reading-assets/S-6-9/figures/section-6-9.png","caseLinks":[{"title":"细菌与噬菌体：共演化可以是对抗性的","href":"https://pmc.ncbi.nlm.nih.gov/articles/PMC1690980/"}],"caseNotes":[{"title":"细菌与噬菌体：共演化可以是对抗性的","text":"Buckling与Rainey在2002年原始论文的公开摘要中报告，细菌宿主抗性与噬菌体感染能力呈长期相互适应：宿主对更广范围寄生者类型产生抗性，寄生者对更广范围宿主类型具有感染能力；重复群落的变化路径还发生分化。这个案例直接限制“共演化等于互利同步”的理解。","sourceLabel":"Buckling & Rainey 2002，DOI 10.1098/rspb.2001.1945","sourceUrl":"https://pmc.ncbi.nlm.nih.gov/articles/PMC1690980/","sourceLocator":"原论文公开Abstract，第二、三段；Proc. R. Soc. B 269:931–936，2002-05-07","boundary":"仅据原作者公开摘要保留该研究所报告的有限结论；本讲未独立复核全文方法和数据，不据摘要重新认证双向G2/G3，也不推广为人的关系义务。","href":"https://pmc.ncbi.nlm.nih.gov/articles/PMC1690980/"}],"sourceRefs":[{"section":"6.9","start_line":1412,"end_line":1419,"startLine":1412,"endLine":1419}],"outputId":"section-6-9","sourceHash":"df579dbdbb68442b1781b066606c267761f0a1673fbd034ce93eeeb41641439f","argumentSteps":["分别声明A、B完整对象合同及K、尺度剖面和时间窗，明确仍可分别追踪。","各自提出A→B、B→A通道与改变字段，列时序、速度与比较。","分别核双向G2，区分共同环境、单向依赖及测量协议同步。","跨轮先查两边载体路线；额外历史增量分别声明和检验，不捆绑通过。","把长期终值、到达期限、瞬态和定向干预当成不同任务，按任务检查表示保留。","允许报告不对称或对抗性共演化；价值、持续义务和权限另议。"],"teachingExamples":[{"title":"数学构造：相同终点，不同速度与干预响应","text":"设两个状态偏差z=(x,y)，模型A更新x′=0.25x+0.25y，y′=0.25x+0.25y；模型B更新x′=0.75x+0.125y，y′=0.125x+0.75y。两模型的最大行和分别0.5和0.875，所以对任意有限初态都有||z_t||∞≤r^t||z₀||∞→0，且唯一固定点都是(0,0)。但从(1,0)出发，A第一步(0.25,0.25)、第二步(0.125,0.125)；B第一步(0.75,0.125)、第二步(0.578125,0.1875)。若任务是第二步最大绝对偏差≤0.2，A通过、B不通过。若当前只把y增加δ而x不变，下步x的变化分别0.25δ和0.125δ，定向干预响应也不同。","assumptions":"完全给定的固定线性双状态模型，无外来冲击和执行限制；r是对应模型行和上界，变量是偏差而非人数。","boundary":"该构造证明终值不足以恢复机制，不独立证明现实对象共演化，也不提供实际干预方案。"},{"title":"数学构造：共同输入能让两条曲线完全同步","text":"设外部条件U_t任意变化，x_t=U_t、y_t=2U_t，两者没有相互连线。它们会完全同步，相关也可极高；但在固定U及另一规则的条件下单独替换y，并不改变x的后续值。真正要检双向关系，应分别问两个方向的变化是否由对方输入造成，而不是把同一U漏掉。","assumptions":"明确共同输入结构且无隐藏交叉项，所有序列为构造。","boundary":"现实中共同环境与双向关系也可同时存在，不能因为列出共同输入就自动否定共演化。"},{"title":"教学构造：两个时钟不能用一张同期表替代","text":"虚构A每周调整供给接口，B每季度才修订使用规则。A本周变化不必在B同周报表中出现；B下一季度变化也可能来自其他条件。应分别登记供给何时真正改变B的可行路径、B的规则何时返回影响A，再按各自窗口比较。把季度总量复制到每周，不能凭新增的表格行数制造更多独立证据。","assumptions":"纯教学时序，未观察任何机构；更新周期事前声明。","boundary":"既不能以短期无同步否认迟效应，也不能把所有迟变化归因给最早的A。"}],"counterexamples":[{"identity":"constructed_boundary","text":"两边长期相关，故必然互相塑造且共同受益。","effect":"共同输入可解释相关，互利又是额外价值/结果判断。","sourceIds":["theory"]},{"identity":"constructed_boundary","text":"模型A和B极限都是0，所以两步恢复与定向干预也等价。","effect":"第二步和响应系数不同，终值摘要超出了用途。","sourceIds":["theory"]},{"identity":"constructed_boundary","text":"只有A到B的因果证据，却画两条箭头并称双向G2都过。","effect":"缺失方向必须保留未决，图不能增加证据。","sourceIds":["theory"]}],"questionAnswers":[{"question":"两个模型都收敛到0，为什么第二步达标结论不同？","answer":"最大行和分别给出收敛速率的上界；具体两步差异由矩阵递推算出。从给定初态，A第二步最大0.125，B最大0.578125，相对0.2阈值不同。","basis":"本节原文及上述公开推导"},{"question":"只增加当前y一单位，两模型下一步x差多少？","answer":"A增加0.25，B增加0.125；同固定点不保证相同干预响应。","basis":"本节原文及上述公开推导"},{"question":"A影响B，B又有变化，是否已经足够双向共演化？","answer":"不足，须独立追B→A的实际作用、时序和比较，不能用B变化替代回向机制。","basis":"本节原文及上述公开推导"},{"question":"双向都存在持久载体，是否两边必须有G3？","answer":"不必须。载体路线分别取证，只有各自额外历史增量主张才另需G3。","basis":"本节原文及上述公开推导"},{"question":"共演化关系可否不对称且对抗？","answer":"可以，双向影响不等对称或互利，也不产生继续维持义务。","basis":"本节原文及上述公开推导"}],"figures":[{"path":"/reading-assets/S-6-9/figures/section-6-9.png","alt":"对象A，完整合同与判据K_A，自己的SP_A／T_A；对象B，完整合同与判据K_B，自己的SP_B／T_B；第三方共同环境，共同冲击／单向依赖，测量协议同步须比较；A到B与B到A，时序、速度、载体分别核，不默认对称或互利；同终态仍可不同，更新、期限、瞬态、干预，按所问任务保留差异。两支箭头都是待分别取证的候选方向，不由同时变化自动成立；五卡不构成现实共演化认证。","caption":"两支箭头都是待分别取证的候选方向，不由同时变化自动成立；五卡不构成现实共演化认证。"}],"diagramBrief":"当前交付为静态图；交互尚未实现，以下涉及选择、切换或点击的内容仅为后续设计设想。五卡分别登记两个对象、共同环境、双向取证责任及任务相关动态差别。两支分开标注的箭头是各自需取证的候选通道，不能把一向证据复制作另一向支持。","applicability":{"realCase":"applicable","diagram":"applicable","reason":"原研究摘要提供明确的对抗性双向适应案例；读取范围和支持上限公开，数学模型只解释同终态非等价，不冒充生物数据。"},"openQuestions":["若要独立评价该生物实验的通道识别、时间分辨率及竞争解释，尚需取得并逐项核对全文方法与数据；本讲不据摘要填补这些内容。"],"taskId":"S-6-9","sources":[{"id":"theory","title":"Xikari-条件结构与转化论，用户提供原文","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"现行全文第1412—1419行；每节精确范围见sourceRefs","claim_support":["6.9：术语、合同、论证责任和原文边界；不据此认证经验事实"],"limits":["作者理论文本，是被解释对象，不替代外部经验资料；技能5.3.1不等于理论版本。"],"access_status":"read"},{"id":"buckling2002","title":"Buckling与Rainey：细菌和噬菌体的对抗共演化","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC1690980/","source_type":"primary","version_or_date":"2002-05-07；DOI 10.1098/rspb.2001.1945","locator":"Abstract第二、三段（公开全文页中摘要部分）","claim_support":["6.9：原作者报告宿主抗性与寄生者感染能力相互适应，重复群落出现路径分化。"],"limits":["只核公开摘要；全文PDF未取得，具体实验方法、数据和通道识别未在此复核。"],"access_status":"partially_read"},{"id":"theory-d0","title":"Xikari3.1：完整对象合同","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"第425—448行","claim_support":["6.9：双方分别登记D0，K仅是同一性判据，SP/T不是可随意合并的时空标签。"],"limits":["两个候选合同不证明双方或双向通道已有效。"],"access_status":"read"},{"id":"theory-history","title":"Xikari4.5：跨轮载体与额外历史","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"第620—640行","claim_support":["6.9：双方载体分别取证，额外历史增量才追加各自G3。"],"limits":["不能由一个方向支持替代另一个方向。"],"access_status":"read"}],"lecturePath":"/reading-assets/S-6-9/lecture.md","sourcesPath":"/reading-assets/S-6-9/sources.json","sourceSlicePath":"/reading-assets/S-6-9/source-slice.md","supplementaryFiles":[],"diagramsPath":"/reading-assets/S-6-9/diagrams.md"},"6.10":{"title":"6.10　解体、对象转换与修复边界","lead":"修复不一定是恢复每个旧零件，解体也不一定是失败。先说清要保住或重新得到什么，再比较哪些新状态能达到目标，以及谁有权作这个选择。","explanation":["原文定位：第1420—1425行；原文锚点 section-6-10；短引文：‘它不是把时间倒回旧状态’。本题源切片逐字附后，讲解与原文分开。","解体以原合同的K不再成立为判据。K是同一性判据，不是整个对象合同；判据文字未改也不保证对象继续满足它。若原K失效而另一对象合同可成立，要进一步区分对象终止、转换或重新分类；不能只看旧名称还在，便把原对象存续当作事实。","相位变化与解体的分界在原K是否仍成立。同一对象可改变运转区间，但原同一性已经失效，就不能静默把变化叫成“新相位”。另有新候选合同也不能仅凭定义就认证现实对象转换；正式转换主张还需相应尺度映射、保持/损失和G4路线等材料。","解体不自动等于失败，存续也不自动等于成功。判断成功需要事前目标、代价和评价标准；有序结束某对象可能是允许目标，维持旧身份也可能持续损害功能或他人。描述什么仍在、什么已终止，与是否值得维持，必须分别回答。","修复以结果前公开的目标K*或F*判断。可以利用旧痕迹，也可换组件、边界、关系、接口、载体或尺度位置。达到目标的新状态不必和过去完全相同；反之，外观恢复、旧名称沿用或某项输出恢复，也不单独保证预定K*/F*均满足。若只选F*，就只报告该功能达标，不顺带证明原对象身份。","“存在修复窗口”是更具体的经验主张。除目标外，还需比较不同介入时点如何影响目标可达性和成本，说明允许措施、资源、时延及替代路径。一段时间后原方案不可行，不等于所有可能方案永久无望；新增资源或技术会改变可行集，必须公开，而非改写原窗口结论。","过去形成的损伤、连接或能力可作为当前限制，按载体路线追其形成和现在作用。给定完整当前限制后历史是否仍额外有用，是另一问题，只有后者追加G3。不能因为当前损伤有历史来源，就要求所有修复比较必须证明额外历史增量。","经验可达不授予实施权。目标正当性、谁选择、谁负责、谁能执行须由N、J及O1—O4审查：先冻结描述和证据，再公开规范前提与冲突、比较含不行动在内的方案并核授权，最后限定执行、监测、停止、申诉、回滚与补救。供审议的技术比较可以先做，但不冒充已经获准的现实处置。"],"distinctions":[{"leftTitle":"原K失效","leftText":"按原同一性判据不能继续称原对象保持。","rightTitle":"所有功能都消失","rightText":"更强且未必成立，其他对象或功能可能保留。"},{"leftTitle":"修复K*或F*","leftText":"达到预先声明的身份或功能目标。","rightTitle":"返回历史原样","rightText":"不必要，路径、组件或支持可以改变。"},{"leftTitle":"修复可达","leftText":"给定措施、资源与时点下可达到目标。","rightTitle":"获准实施","rightText":"还需规范前提、权限与受限程序。"},{"leftTitle":"某方案窗口关闭","leftText":"在已登记可行集内该目标不可达。","rightTitle":"任何未来方案均不可能","rightText":"不能由前者外推出。"}],"boundaries":["解体、转换与失败不是同义词；同样，存续不保证功能或价值。","不能在结果后把K*/F*改成已经做到的内容来救援原修复任务。","改变载体可真实修复功能；是否保留原K另核，不要求一律两者同时成立。","修复窗口绑定对象、目标、措施与资源条件，不是脱离条件的永久命运判断。","技术可行不产生具名责任或权限，分析比较不等于实际部署。"],"questions":["新增a—c边为何既能连通三点又能送4？","若K原本要求旧边b—c本身必须存在，新方案是否保持该K？","窗口模型在t=3最少剩多少损伤？","修复借助临时不同载体，能否被确认？","已有经验支持为何还不能直接决定由谁实施？"],"diagramPath":"/reading-assets/S-6-10/figures/section-6-10.png","caseLinks":[{"title":"岛屿临时微电网：功能修复不要求旧连接原样返回","href":"https://www.gao.gov/assets/gao-19-296.pdf"}],"caseNotes":[{"title":"岛屿临时微电网：功能修复不要求旧连接原样返回","text":"GAO的2019年报告记载，Vieques和Culebra此前由连接波多黎各主网的海底输电线供电；截至2018年12月11日，USACE支持的7台发电机用于两岛微电网。本节新增观察点是实现供电的载体/连接可以与原来不同，不能把“原连接未按原样恢复”和“没有任何功能修复”视为同一句话。","sourceLabel":"GAO-19-296，2019-04-18","sourceUrl":"https://www.gao.gov/assets/gao-19-296.pdf","sourceLocator":"印刷p.7，Figure 1之后的临时发电机与海底输电线段","boundary":"仅说明报告中的替代供电配置；不独立证明所有用户连续供电、原电网K保持或长期净收益，更不替任何实际改造授权。","href":"https://www.gao.gov/assets/gao-19-296.pdf"}],"sourceRefs":[{"section":"6.10","start_line":1420,"end_line":1425,"startLine":1420,"endLine":1425}],"outputId":"section-6-10","sourceHash":"df579dbdbb68442b1781b066606c267761f0a1673fbd034ce93eeeb41641439f","argumentSteps":["核原对象合同与原K，明确哪些状态仍满足、何时不再满足。","K持续时再看相位；K失效时分别检终止、转换或重新分类，正式转换另核合同与证据。","结果前公开K*/F*，列可改变组件/边界/关系及不得丢失的任务条件。","对候选修复状态逐项验目标，而非要求回到全部旧状态或仅看外观。","要说修复窗口，就比较介入时点、允许措施、可达性和成本，明确可行集。","当前历史载体与额外历史增量分开；行动选择另过N、J和O1—O4。"],"teachingExamples":[{"title":"数学构造：换一条边也能修复功能","text":"虚构无向服务网有节点a、b、c，原边a—b与b—c容量各为4，任务F*为每时段从a向c输送4单位同型量；K*为这三个指定节点组成连通网。只有a供给、c接收，b守恒，无额外流量。原唯一a—b—c路径可输送4。若b—c断开，c孤立，K*不满足、可送量0。修复方案新增容量4的a—c边，保留a—b，则三点重新连通且可直接送4；新边集不同于原边集，但同时满足这里预定的K*/F*。","assumptions":"图结构、容量和目标均人为给定；输入/输出同单位同窗口，边容量可实现且无额外损耗。K*只是该构造声明的判据，完整现实对象仍需其他材料。","boundary":"数学可达性不认证现实网络、部署权限或成本；若原K要求每根旧边都保留，结论会不同，必须事前说明。"},{"title":"数学构造：时点改变可达性而非历史必然","text":"设虚构损伤z_t=t，t为从0起的整数时点。唯一允许措施可一次消除m单位损伤，0≤m≤2，处理后z*=max(0,z_t−m)，成本为m单位预算，预算上限2；目标F*为z*=0。在t=1，取m=1可达且成本1；t=2取m=2可达且成本2；t=3则任何允许m都剩至少1，目标不可达。因此该措施/预算下窗口是t≤2，而非一切未来修复都不可能。","assumptions":"损伤形成、措施范围和成本规则全部明示；不含等待期间额外恢复或新措施，t≥0。","boundary":"只是目标可达性计算，不是人的不可逆诊断；新增资源/措施须另声明新问题。"},{"title":"教学构造：改名不能让受影响位置消失","text":"沿用断网状态，若只把a、b登记为一个新的两点服务对象，可以研究这个新候选，但不能因此说原先对c的服务目标已恢复。新合同怎样处理c、原义务和退出损失必须公开；一个小对象成立不自动替代原对象的任务。","assumptions":"纯教学重新分组，未对现实组织或人群作边界调整。","boundary":"新对象的经验有效性、转换资格与规范采用分别取证，不由改名获得。"}],"counterexamples":[{"identity":"constructed_boundary","text":"三节点网络用新直连边达标，所以必须说它没有修复，因为并非旧路径。","effect":"修复目标若允许关系改变，新状态可达K*/F*；历史原样不是必要条件。","sourceIds":["theory"]},{"identity":"constructed_boundary","text":"原对象K失效，就推出全部社会目标失败且必须恢复旧对象。","effect":"解体事实不自行给目标或义务，需独立评价。","sourceIds":["theory"]},{"identity":"constructed_boundary","text":"同一维修方案晚了已无效，所以任何技术、资源和未来条件下都不可修复。","effect":"外推超出已登记可行集，窗口结论须保留条件。","sourceIds":["theory"]},{"identity":"constructed_boundary","text":"方案在技术模型里可行，因此团队有权立即改真实记录或基础设施。","effect":"可行性不能替代N/J/O程序。","sourceIds":["theory"]}],"questionAnswers":[{"question":"新增a—c边为何既能连通三点又能送4？","answer":"保留a—b并新增a—c，b与c通过a相连；a—c容量4且只有该同型流需求，所以可达F*。","basis":"本节原文及上述公开推导"},{"question":"若K原本要求旧边b—c本身必须存在，新方案是否保持该K？","answer":"不保持；可满足某个功能F*却不满足这个原K，必须依事前判据分别报告。","basis":"本节原文及上述公开推导"},{"question":"窗口模型在t=3最少剩多少损伤？","answer":"最大可消除2，原损伤3，最少剩1，所以原目标不可达。","basis":"本节原文及上述公开推导"},{"question":"修复借助临时不同载体，能否被确认？","answer":"若在公开支持和窗口条件下满足预定K*或F*，可以有限确认；持续性、原身份和独立维持另核。","basis":"本节原文及上述公开推导"},{"question":"已有经验支持为何还不能直接决定由谁实施？","answer":"目标、责任、授权及程序不是经验作用的自动产物，需N/J/O1—O4另审。","basis":"本节原文及上述公开推导"}],"figures":[{"path":"/reading-assets/S-6-10/figures/section-6-10.png","alt":"原网：a—b—c，两边容量4，连通且a到c可送4；断网：b—c失效，c孤立，K*不满足，输送0；新网：加a—c，保留a—b，直连容量4，K*与F*均满足。数学构造；K*是三点连通，F*是每时段a到c输送4；新网不是原边集，真实采用权限另审。","caption":"数学构造；K*是三点连通，F*是每时段a到c输送4；新网不是原边集，真实采用权限另审。"}],"diagramBrief":"当前交付为静态图；交互尚未实现，以下涉及选择、切换或点击的内容仅为后续设计设想。三个并排网络画出原状、断边及新增直连修复。红叉示断边，蓝线示可用容量4的边；全部为教学设定，无真实网络数据。","applicability":{"realCase":"applicable","diagram":"applicable","reason":"真实替代供电配置用于辨认新载体与旧配置的差别；修复目标、网络流和窗口均另作明确构造，不假定灾区原对象合同。"},"openQuestions":[],"taskId":"S-6-10","sources":[{"id":"theory","title":"Xikari-条件结构与转化论，用户提供原文","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"现行全文第1420—1425行；每节精确范围见sourceRefs","claim_support":["6.10：术语、合同、论证责任和原文边界；不据此认证经验事实"],"limits":["作者理论文本，是被解释对象，不替代外部经验资料；技能5.3.1不等于理论版本。"],"access_status":"read"},{"id":"gao-alternative","title":"GAO-19-296：两岛替代供电配置","url":"https://www.gao.gov/assets/gao-19-296.pdf","source_type":"primary","version_or_date":"2019-04-18","locator":"印刷p.7，Figure 1后临时发电机段","claim_support":["6.10：2018-12-11七台发电机支持Vieques/Culebra微电网，两岛此前通过海底输电线接主网。"],"limits":["替代配置事实不自动给原K保持、全面连续供电或治理授权。"],"access_status":"partially_read"},{"id":"theory-d1","title":"Xikari3.2：解体、修复定义","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"第450—461行","claim_support":["6.10：原K失效与目标K*/F*，状态词不自带价值或授权。"],"limits":["数学目标达到不替现实对象取证。"],"access_status":"read"},{"id":"theory-history","title":"Xikari4.5：当前历史载体","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"第620—640行","claim_support":["6.10：历史形成的当前限制与额外历史残差分开。"],"limits":["只有额外增量才另需G3。"],"access_status":"read"},{"id":"theory-conversion","title":"Xikari4.6与5.7：正式转换责任","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"第642—650行；第1190—1220行","claim_support":["6.10：进一步正式声称对象转换时，须相应映射、保持/损失与G4条件。"],"limits":["K失效不自动证明另一对象及正式转换。"],"access_status":"read"},{"id":"theory-action","title":"XikariC12与14.6：规范、授权和程序","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"第908—924行；第2940—2953行","claim_support":["6.10：可达性、供审议比较与现实采用分开；N、J、O1—O4承担不同责任。"],"limits":["讲解不实施任何现实改造。"],"access_status":"read"}],"lecturePath":"/reading-assets/S-6-10/lecture.md","sourcesPath":"/reading-assets/S-6-10/sources.json","sourceSlicePath":"/reading-assets/S-6-10/source-slice.md","supplementaryFiles":[],"diagramsPath":"/reading-assets/S-6-10/diagrams.md"},"6.11":{"title":"6.11　机制输出总闸","lead":"机制说明写完后，要再问一遍：我们究竟交出了什么证据，允许结论到哪一步？这个总闸防止一句“系统有反馈”悄悄变成“系统已经学会、恢复并且值得维持”。","explanation":["原文定位：第1426—1429行；原文锚点 section-6-11；短引文：‘缺项时只保留候选机制或检查问题’。本题源切片逐字附后，讲解与原文分开。","这里的六个条件机制是反馈、反馈介导学习、维护、负荷、相位和筛选。它们共用八项检查：对象与尺度声明、推理依赖、使能条件、机制链、最低证据、竞争解释、反例、失效边界。共同框架不意味着每个机制都用同一份证据，也不意味着所有分支都需G3。","对象与尺度声明确定说的是谁、在哪个SP/T/K范围；推理依赖说明结论逻辑上靠什么；使能条件说明过程发生所需条件；机制链连接各个实际作用位置。最低证据规定要拿什么材料来支撑，竞争解释检查还有哪些说明能改变判断，反例说明什么情形会限制或反驳主张，失效边界则明确何时停止外推或换合同。","八项不能相互顶替。画出一条机制链不等于已经有证据；罗列竞争解释不等于逐项排除了它们；写了时间窗不等于观察覆盖它；填满字段也不保证变量、通道和授权引用语义正确。总闸要求实质相称，而不是看到表格没有空白就认证。","每个机制保留自己的结论上限。反馈只保证有作用的返回，不带跨轮学习；即时负荷只说同窗缺口，不带累积损伤；基础相位模式不带历史增量型迟滞；筛选模式不带指定承载机制，更不带价值优越；维护与修复不带永久存续义务。进一步主张可以提出，但要另补它实际需要的材料。","缺项时保留候选机制或具体检查问题，不把空白用宏大叙事补上。这里暂停的是所声称层级的完整机制登记；已经独立成立的观察、领域结论或较低层级结果不应被一概撤销。例如参数确已更新但调用材料不足，可以保留更新事实，把载体学习标为未充分识别。","也要区分“明确反证”与“尚无材料”。已证某个必要条件不满足，会阻断该具体机制路线；必要条件尚未确定，则保留未决，不直接宣告机制在世界中不存在。零结论须自己的比较、灵敏度及容差，不能由正向未过替代。","概念说明与教学构造展示合同如何使用。构造中能精确复算，并不意味着外部对象已按该规则运行；附上一条真实事实，也不让整段模型自动获得实证验证。这个总闸可帮助读者发现缺口，不宣称已经通过真实读者测试或可自动替代领域判断。"],"distinctions":[{"leftTitle":"完整说明","leftText":"八类责任都有可读文字。","rightTitle":"实质支持","rightText":"各项有相称材料与实际检验，不能由文字存在推出。"},{"leftTitle":"机制候选","leftText":"值得按具体缺口继续检查的解释。","rightTitle":"已经支持的机制","rightText":"满足相应范围和分支条件，可作有限结论。"},{"leftTitle":"高层主张未证","leftText":"例如学习机制链还缺调用证据。","rightTitle":"低层事实被否定","rightText":"例如参数改变本身可能已确证，不随之消失。"},{"leftTitle":"缺证据","leftText":"尚不能确认必要条件。","rightTitle":"有反证","rightText":"条件或主张被相称材料反驳，结案不同。"}],"boundaries":["总闸是实质责任集合，不是字段计数器，也不是物理过程中的第九个原因。","八项按逻辑顺序展开，发现新反例可回查前提；不承诺一次直线填写即永远有效。","某一分支未过不会自动改判另一分支成立；需要各自事前主张与材料。","教学例不产生外部经验支持，机器校验通过也不认证事实或规范。","缺项不抹除已经独立建立的事实，但阻止把这些事实合成为尚未支持的完整主张。"],"questions":["报告有参数文件、无调用记录，适当结论是什么？","为什么八个c_i都是1不能推出八个e_i都是1？","看到一次过载后，进一步声称迟恢复，需补什么？","基础相位模式已支持，是否必须宣布迟滞也支持？","明确证明某必要条件不成立与没有读到材料有何不同？"],"diagramPath":"/reading-assets/S-6-11/figures/section-6-11.png","caseLinks":[],"caseNotes":[],"sourceRefs":[{"section":"6.11","start_line":1426,"end_line":1429,"startLine":1426,"endLine":1429}],"outputId":"section-6-11","sourceHash":"df579dbdbb68442b1781b066606c267761f0a1673fbd034ce93eeeb41641439f","argumentSteps":["先确定在六个机制中的哪一个、哪个分支、哪个结论层级，避免名称混用。","逐项核八个共同责任，并把每项连接到本对象和本窗口的材料。","对需要更强主张的地方显式追加条件，不把G3或治理权限等通用硬塞给所有路线。","区分填了说明、具备相称材料、已经检验及得到何种结果。","缺项时给具体候选/问题与停止位置，保留独立已知事实。","分别记录反证和未知；概念、形式构造与真实经验支持保持不同身份。"],"teachingExamples":[{"title":"教学构造：一份“学习报告”的缺口定位","text":"虚构报告准确记录了反馈到达、参数改变、参数文件保存，却没有后续任务读取该版本的材料。总闸不应把它打成“什么都没发生”，也不能宣布学习完成：更新事实可保留，实际调用和任务差异缺口具体列出。如果另有材料显示程序始终读旧版本，则不只是缺证，而是这一调用主张受到反证。","assumptions":"虚构材料配置，不对应真实组织；到达/改变/保存均按设定已核，调用状态分未知与已知不成立两种。","boundary":"不把本构造当作现实学习诊断，也不替真实领域取证。"},{"title":"数学构造：八个非空字段不等于八项已解决","text":"设c_i=1表示第i项字段有文字，e_i=1表示该项实质条件已获相称支持。一个模型记录可有(c₁,…,c₈)=(1,1,1,1,1,1,1,1)，而(e₁,…,e₈)=(1,1,1,1,0,0,1,1)：最低证据和竞争解释尚未解决。于是∏c_i=1而∏e_i=0，形式完整性不能代替实质完整性。这里e_i只是教学逻辑标记；现实支持不能由作者自己填一个1来创造。","assumptions":"用二值标记演示逻辑非蕴含；现实还需未决等多状态，不能把0一概理解为经验反证。","boundary":"该乘积不是推荐的自动事实认证算法，只是一个反例。"},{"title":"教学构造：逐条阻断偷带结论","text":"虚构六条陈述：返回改变一次状态→永久学会；一小时需求超容量→必有累积损伤；两个阈值区间→必有额外历史；差异保留模式→特定遗传通道已证；某设备需维护→某人有永久义务；功能修复可行→机构可立即实施。每个箭头都缺不同桥接材料，不能用“系统机制完整”统一补齐。","assumptions":"完全由自拟论证跳跃组成，不描述现实人物或事件。","boundary":"只展示识别缺口，不预判补齐材料后各结论必然错误。"}],"counterexamples":[{"identity":"constructed_boundary","text":"八个标题齐全且JSON通过，所以六类机制在现实中都成立。","effect":"语法完整不产生对象事实、因果支持或规范授权。","sourceIds":["theory"]},{"identity":"constructed_boundary","text":"学习路线缺调用材料，所以此前参数改变的记录必定也是假的。","effect":"不能用高层缺证抹除低层已知事实。","sourceIds":["theory"]},{"identity":"constructed_boundary","text":"主张尚未检验，于是记成零机制已经得到支持。","effect":"未运行、未决和零结论须分别保留。","sourceIds":["theory"]}],"questionAnswers":[{"question":"报告有参数文件、无调用记录，适当结论是什么？","answer":"保留已核参数更新/保存事实；学习机制仍缺调用与任务材料，列为候选或未决。","basis":"本节原文及上述公开推导"},{"question":"为什么八个c_i都是1不能推出八个e_i都是1？","answer":"c记录文字存在，e记录实质条件支持，两者不同；给出的向量就是反例。","basis":"本节原文及上述公开推导"},{"question":"看到一次过载后，进一步声称迟恢复，需补什么？","answer":"补损伤/容量/恢复载体的形成、跨窗作用与相称比较，额外历史主张才另加G3。","basis":"本节原文及上述公开推导"},{"question":"基础相位模式已支持，是否必须宣布迟滞也支持？","answer":"不必，载体持续或额外历史迟滞各自需要材料，不能由基础模式偷带。","basis":"本节原文及上述公开推导"},{"question":"明确证明某必要条件不成立与没有读到材料有何不同？","answer":"前者阻断该具体路线，后者通常保留未决；两者都不能随意推成一切外部现象不存在。","basis":"本节原文及上述公开推导"}],"figures":[{"path":"/reading-assets/S-6-11/figures/section-6-11.png","alt":"1 对象与尺度，谁／SP／T／K，范围必须相称；2 推理依赖，结论靠哪些前提，方法门不装原因；3 使能条件，何时能发生，不把名称当条件；4 机制链，逐段指定通道，图线不代替材料；5 最低证据，材料、比较和结果，字段有字不等于支持；6 竞争解释，哪些解释会改判断，比较及残差要保留；7 反例，什么会限制或反驳，反证与未知分开；8 失效边界，何时停止外推，候选不冒充已证。六机制各按自己的分支落实八项；缺项列具体问题，独立事实仍保留，概念与构造不产生外部支持。","caption":"六机制各按自己的分支落实八项；缺项列具体问题，独立事实仍保留，概念与构造不产生外部支持。"}],"diagramBrief":"当前交付为静态图；交互尚未实现，以下涉及选择、切换或点击的内容仅为后续设计设想。八卡按原文共同责任展开，不画自动证实箭头；不同机制所需材料不同，六种禁止偷带关系在正文逐项说明。","applicability":{"realCase":"not_applicable","diagram":"applicable","reason":"本节是六机制共同输出责任的收束，适合用逻辑反例与明确教学情境；不再强贴一件史实冒充所有机制的共同认证。"},"openQuestions":[],"taskId":"S-6-11","sources":[{"id":"theory","title":"Xikari-条件结构与转化论，用户提供原文","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"现行全文第1426—1429行；每节精确范围见sourceRefs","claim_support":["6.11：术语、合同、论证责任和原文边界；不据此认证经验事实"],"limits":["作者理论文本，是被解释对象，不替代外部经验资料；技能5.3.1不等于理论版本。"],"access_status":"read"},{"id":"theory-mechanisms","title":"Xikari6.2—6.8：六机制及分支","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"第1302—1411行，分别见6.2、6.3、6.5、6.6、6.7、6.8","claim_support":["6.11：六机制的不同依赖、材料和结论上限；G3只进入相应额外历史分支。"],"limits":["概念解释不是外部机制支持。"],"access_status":"read"},{"id":"theory-four-states","title":"Xikari4.1：四态与零结论责任","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"第577—581行","claim_support":["6.11：正向未过不自动支持零，未运行、未决、反证与零结论区分。"],"limits":["形式记录不能自行创造证据。"],"access_status":"read"}],"lecturePath":"/reading-assets/S-6-11/lecture.md","sourcesPath":"/reading-assets/S-6-11/sources.json","sourceSlicePath":"/reading-assets/S-6-11/source-slice.md","supplementaryFiles":[],"diagramsPath":"/reading-assets/S-6-11/diagrams.md"},"6.12":{"title":"6.12　异步多时钟的运转","lead":"一句话能在几秒内被听见，关系预期可能要几轮互动才改变，组织资源与制度执行又有自己的周期。若把所有变化盖成同一天，既会错怪迟到的效应，也会把短暂反应吹成长久成果。","explanation":["原文定位：第1430—1446行；原文锚点 section-6-12；短引文：‘跨时钟桥必须给出载体、执行、确认和失效条件’。本题源切片逐字附后，讲解与原文分开。","多圈层联合状态至少区分即时、互动、组织、制度和长期五种时钟。这里的时钟是各类变量何时更新、在什么窗口观察，不是给每类事件固定一个全球统一时长。同一事件可以先改变快变量，再经重复互动影响关系预期，随后经组织决策改变资源，最后可能进入制度写回；“可以”不等于必然走完。","即时→互动的最低桥是多个回合中状态差持续，并改变对方响应。单次情绪消退，不能当成稳定互动规则；同时，下一回合尚未到来时也不能急于说无效。须记录状态由什么载体留下、后续接触是否发生及对方实际响应。","互动→组织要看到关系或策略变化进入角色、流程、资源或记录。口头共识和会议气氛不能替代落实；角色调整、排程、预算或工作记录的版本和执行有各自位置。对组织变化的判断仍不能直接跳到所有制度约束都已改变。","组织→制度的桥要求可核规则或程序变化、责任安排与实际执行。授权、法律有效性、规范正当性另列，不能用发布文件代替执行，也不能因为行为越权或有争议就漏记已经发生的制度性影响。记录事实不等于认可或允许再次实施。","制度→长期要追持续执行、维护、学习和替代路径，并检查短期合规后是否回弹。长期不是一个预先盖上的标签：覆盖期限、季节、需求波动、成员变动及支持接续都须与所声称结果相称。观察窗口只到某日，不能填造其后已经持续。","每条跨时钟桥都说明载体、执行、确认及失效条件。载体可能是参数、记录、排程、规则或其他状态，但必须定位；执行说明更新实际进入过程，确认说明从何处独立核到变化，失败条件说明什么时候桥未接上。一个发布渠道中的同源转发不能自动增加独立执行确认。","产业扩张、签署协议、停止公开暴力、设施完工和群众合作等快一些的结果，都可能有真实价值；却不能由此包办长期生活状态。继续核执行、分配、权利、关系及持续性，资料不足时保留局部已知结果并停止远程外推，不把局部成果取消，也不虚构最终成功。","事实时钟与规范状态不能合并。若规则变更或执行确实发生，即使违规、越权或受争议，也须进入过程记录并标明相应状态；反之，已获授权、公告已发或机构宣布完成，不等于每个局部位置已实际执行。两种混淆都会使因果时间线失真。","因此短期没变化与迟效应尚未到观测窗要分开，短期波动与长期演化也要分开。更新时点与观测时点可不同，缺记录不是自动无事件；但承诺未来会有作用也不能代替现在缺失的证据。按照各自主张的期限报告，桥未核实处停住。"],"distinctions":[{"leftTitle":"事件发生时点","leftText":"动作或状态实际改变的时候。","rightTitle":"公告/记录时点","rightText":"可能早或晚于执行，不能直接互换。"},{"leftTitle":"规则发布","leftText":"某文本或决定出现。","rightTitle":"制度实际执行","rightText":"规则进入具体位置的过程，需要独立材料。"},{"leftTitle":"授权/正当状态","leftText":"规范与权限方面的判断。","rightTitle":"是否实际发生","rightText":"经验记录问题，两者不得互相代替。"},{"leftTitle":"短期有限成果","leftText":"某窗口、对象或功能已有依据。","rightTitle":"长期综合结果","rightText":"需继续核持续、分配、权利与关系。"}],"boundaries":["五类时钟不是强制统一顺序或固定天数；实际可以交错、回返、停滞。","每一跨时钟桥都可能失败，前层成功不保证后层，更不能靠汇总标签跳过。","非法、越权或争议不使真实影响变成未发生；解释其形成不授予实施许可。","批准和计划不能代替执行，暂时观察不到后效也不能不加窗口地宣称永久无效。","长期材料未到时保留未知，不为验证而强行撤去必要支持或制造危险中断。"],"questions":["教学时间线第9日能否宣布新程序已执行？","观察截至第30日，能否宣布第90日持续达标？","越权动作已执行，过程记录应怎样写？","互动形成口头共识，到组织层至少还缺什么？","看到制度短期合规，为何长期还要看维护与替代路径？"],"diagramPath":"/reading-assets/S-6-12/figures/section-6-12.png","caseLinks":[{"title":"马里兰续保：提交、实际使用与批准是不同日期","href":"https://health.maryland.gov/mmcp/Documents/JCRs/2023/eligibilityredetprocessJCRfinal4-24.pdf"}],"caseNotes":[{"title":"马里兰续保：提交、实际使用与批准是不同日期","text":"马里兰2024年报告分别记载，缓解方案于2023年9月13日提交CMS，新版续保流程从2023年11月开始使用，而该方案于2024年2月获批。本节新增观察点是三类事件没有共用一个时间戳；实施、方案审批与长期结果应分别取证。仅凭先后顺序不能裁定当时所有动作的法律地位，报告也未以这一时间线证明长期健康效果。","sourceLabel":"Maryland FY24 Quarter 4报告，2024-05-14提交","sourceUrl":"https://health.maryland.gov/mmcp/Documents/JCRs/2023/eligibilityredetprocessJCRfinal4-24.pdf","sourceLocator":"印刷p.9，第3项mitigation plan及末段updated process utilized beginning November 2023","boundary":"支持这些报告日期与事件身份；不把方案批准等同全部动作授权，不推未审批前每项执行均违法，也不外推长期收益。","href":"https://health.maryland.gov/mmcp/Documents/JCRs/2023/eligibilityredetprocessJCRfinal4-24.pdf"}],"sourceRefs":[{"section":"6.12","start_line":1430,"end_line":1446,"startLine":1430,"endLine":1446}],"outputId":"section-6-12","sourceHash":"df579dbdbb68442b1781b066606c267761f0a1673fbd034ce93eeeb41641439f","argumentSteps":["为即时、互动、组织、制度和长期变量分别声明更新时钟与观察覆盖。","即时到互动核重复回合、状态保留及对方响应，不能用单次情绪替代。","互动到组织核角色/流程/资源/记录的实际进入；组织到制度核规则、责任与执行。","制度到长期核持续执行、维护、学习和替代路径，保留回弹与未覆盖期。","每桥定位载体、执行、确认、失效条件，并区分事件时间、记录时间与发布时点。","事实记录与授权、法律效力、正当性并列登记；既不以非法抹去事件，也不以批准制造执行。","局部已知成果保留，期限外、人群外与最终生活效果停止外推。"],"teachingExamples":[{"title":"教学构造：把几个日期压成一个日期会出错","text":"虚构系统第0日收到反馈；第1、3日的两次互动显示更新持续并改变对方回应；第5日组织作决定，第6日资源真正调配；第8日发布新程序，第10日开始实际执行。若任务要求第9日已落实制度执行，本构造未达标，不能用第8日公告代替。若只问第11日是否已经执行，则可以答已开始。长期目标到第90日，但材料仅覆盖第30日，后60日仍未观察，不把第10日开始执行当作90日持续成功。","assumptions":"日期、事件和观察覆盖全为教学设定；每一桥在本例按文字给定，不声称任何真实制度如此运行。","boundary":"期限达标、执行开始和持续达标不同；迟于第9日不等于永久无效。"},{"title":"数学构造：事实位与授权位互不蕴含","text":"设E=1表示动作确实执行，J=1表示满足本构造预定权限合同。情况甲(E,J)=(1,0)：动作已执行但权限条件不满足，必须同时记录事实与越权状态；不能把E改0。情况乙(E,J)=(0,1)：已获相应授权但尚未执行，不能把E改1。法律有效性和规范正当性若要讨论，还须另设字段，不由J一位包办。","assumptions":"明确给定的二值教学记录，不裁定任何现实行为的法律地位。","boundary":"不允许因“发生了”推“可以继续发生”，也不以授权存在证明实际成果。"},{"title":"教学构造：季节尚未经历，不取消眼前达标","text":"虚构设施在一个月的普通负荷下达到预定服务质量，且记录完整；下一季高峰尚未来临。可以确认这个月、这个负荷范围的功能，但不能据此宣布全年高峰都稳定。反过来，尚未验证高峰也不把已核普通期服务写成零成果。","assumptions":"无真实设施或性能数据，负荷与窗口为教学条件。","boundary":"高峰评价须安全、可行并获授权，不以构造要求强行压测或撤援。"}],"counterexamples":[{"identity":"constructed_boundary","text":"收到反馈当天就登记长期制度修复完成。","effect":"把不同更新时钟压成同一时点，跨桥材料缺失。","sourceIds":["theory"]},{"identity":"constructed_boundary","text":"组织批准了规则，所以每个局部位置已经执行。","effect":"批准与执行不同，位置与时点需实际确认。","sourceIds":["theory"]},{"identity":"constructed_boundary","text":"规则变更未经授权，所以它对真实流程没有发生影响。","effect":"规范状态不取消事件事实，必须分别记录。","sourceIds":["theory"]},{"identity":"constructed_boundary","text":"一个月内没看到长期效果，所以反馈一定没有作用。","effect":"可能期限错配，也可能确实无效，需按主张窗口与桥接材料比较。","sourceIds":["theory"]}],"questionAnswers":[{"question":"教学时间线第9日能否宣布新程序已执行？","answer":"不能，执行在第10日才开始；第8日公告不足以满足第9日任务。","basis":"本节原文及上述公开推导"},{"question":"观察截至第30日，能否宣布第90日持续达标？","answer":"不能，未覆盖时段保留未决；已有30日内的证据仍保留。","basis":"本节原文及上述公开推导"},{"question":"越权动作已执行，过程记录应怎样写？","answer":"同时记录实际执行及权限不满足，不掩盖事实也不赋予继续实施许可；法律与正当性另核。","basis":"本节原文及上述公开推导"},{"question":"互动形成口头共识，到组织层至少还缺什么？","answer":"需核关系/策略变化进入角色、流程、资源或记录，并有实际执行或使用依据。","basis":"本节原文及上述公开推导"},{"question":"看到制度短期合规，为何长期还要看维护与替代路径？","answer":"持续运行可能依赖支持和承接，短期合规可能回弹，长期任务有自己的时间覆盖。","basis":"本节原文及上述公开推导"}],"figures":[{"path":"/reading-assets/S-6-12/figures/section-6-12.png","alt":"即时，信号到达、快变量变化，不能代替重复互动；互动，多个回合保留并改响应，口头共识未必进组织；组织，角色、流程、资源、记录，决定不等于执行；制度，规则、责任与实际执行，合法与发生分别登记；长期，持续执行与维护承接，未覆盖未来保留未知。五时钟不按同一天更新；四条跨时钟桥均需载体、执行、确认与失败条件，不是自动成熟阶梯。","caption":"五时钟不按同一天更新；四条跨时钟桥均需载体、执行、确认与失败条件，不是自动成熟阶梯。"}],"diagramBrief":"当前交付为静态图；交互尚未实现，以下涉及选择、切换或点击的内容仅为后续设计设想。五行时钟与右侧四条最低桥接责任对应，另列事实与规范不可互相代替。示意不规定统一天数；具体虚拟时间线见正文。","applicability":{"realCase":"applicable","diagram":"applicable","reason":"同一官方报告把提交、使用和方案批准分开，适合多时钟辨认；教学日期与二值权限例另标虚构，避免替真实个案作法律裁决。"},"openQuestions":[],"taskId":"S-6-12","sources":[{"id":"theory","title":"Xikari-条件结构与转化论，用户提供原文","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"现行全文第1430—1446行；每节精确范围见sourceRefs","claim_support":["6.12：术语、合同、论证责任和原文边界；不据此认证经验事实"],"limits":["作者理论文本，是被解释对象，不替代外部经验资料；技能5.3.1不等于理论版本。"],"access_status":"read"},{"id":"maryland-clocks","title":"Maryland FY24 Quarter 4：不同事件时点","url":"https://health.maryland.gov/mmcp/Documents/JCRs/2023/eligibilityredetprocessJCRfinal4-24.pdf","source_type":"primary","version_or_date":"报告April 2024；提交封信2024-05-14","locator":"印刷p.9，第3项缓解方案与最后流程使用段","claim_support":["6.12：2023-09-13提交方案、2023-11开始使用更新流程、2024-02方案获批。"],"limits":["日期不自行证明所有行为授权/违法或长期健康结果，审批对象是该缓解方案。"],"access_status":"partially_read"},{"id":"theory-writeback","title":"Xikari6.4与7.1：执行写回及H3边界","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"第1338—1351行；第1469—1482行","claim_support":["6.12：受理、字段、执行、持续分开；分类不授权现实行动。"],"limits":["事实发生与规范状态不能互相代替。"],"access_status":"read"}],"lecturePath":"/reading-assets/S-6-12/lecture.md","sourcesPath":"/reading-assets/S-6-12/sources.json","sourceSlicePath":"/reading-assets/S-6-12/source-slice.md","supplementaryFiles":[],"diagramsPath":"/reading-assets/S-6-12/diagrams.md"},"6.13":{"title":"6.13　跨圈层级联与共演化","lead":"一条消息穿过桥，不代表人、资源和行动也一起穿过去。跨圈层分析要把每一跳拆开：到底传了什么，下一处凭什么改变，又在哪里停住？","explanation":["原文定位：第1447—1460行；原文锚点 section-6-13；短引文：‘每一级都要重新检查对象、通道、尺度和证据’。本题源切片逐字附后，讲解与原文分开。","级联是一个圈层的局部变化经通道触发其他圈层变化。通道可能是成员重叠、桥接接口、共享资源、网络传播或制度下行。成员重叠可能让同一个人承接两个位置；共享资源可能把一处使用传成另一处短缺；制度下行可能改变局部程序。这些都是待具体识别的机制类型，名称本身不证明已经发生。","每一级重新登记对象、通道、尺度和证据。A处已变化、A→B已有支持，并不推出B→C，更不推出C的长期结果。观察单位、任务、状态、时间窗和身份判据可能在跨圈层时改变；需要说明如何对应，而非沿用第一处的效应量或阈值。容量不足、过滤、迟到、抵消与局部排除区，都可以截断接续。","先问传播的是什么：消息到达、意见确认、采纳、实际协作、资金到账和设备供给不是同一状态变量。消息可沿单桥传送；行动却可能要求多位参与者在同一窗口可用、不同来源作确认、现场安全条件满足。网络上存在路径，只证明模型中的连通可能，不能自行证明现实行动可行。","同一消息从三个渠道转来，仍可能只有一个原始依据。不同人员确认也须查其来源关系，不能自动当作统计独立样本；即使确认真实且来源分开，也不等于这些人已实际协作。桥的落点决定信号集中在哪个目标，先后顺序和持续期决定能否同时满足条件，安全与权限另有自己的责任。","一处故障触发下一处故障，需要按时序逐跳核通道、替代解释和作用；多个故障共同阻碍恢复，则要核恢复需要哪些资源同时到位；共同外因同时损坏多处，则检查共同暴露。这三种图可在同一事故中并存，但不能只看到多个位置出问题，就一律写成串联传染。","人的多源采纳和设施的供给依赖可以互相影响，却不能借用同一个阈值而省略解释。前者涉及信息来源、信任、意图与行动条件，后者可能涉及供电容量、物流可达和材料规格；“需要两个邻居”若只是模型规则，不是普遍的人类规律，更不是电网的物理定律。","聚类描述局部邻居之间怎样连接，不直接等于全网覆盖。局部闭合可提供强化，同时可能把接触集中在已覆盖群体，减少跨群落点和有效多源接入。真实实验中某种聚类网络扩散较好，与另一个明确模型中跨群覆盖受限，可以同时成立；不能把其中之一升级成所有网络上的单调规律。","共演化还需至少两个对象在一段时间内相互改变选择环境、转移概率或约束，并保留各自独立的同一性判据K及相应对象身份。K只是完整对象合同中的同一性判据，不是整个合同。只有共同外因引起同步、只有单向影响，或返回信号未改变后续状态，均不足以按本节称为共演化。","若原来的两个对象只是被合并吸收，先检查嵌套、身份中断或对象转换，不把“已经难分彼此”当作共演化最强证明。描述性对象变化与正式G4转换资格仍有区别；后者要自己的转换材料。对于独立支持的领域观察，缺少本框架正式实例身份并不使原结果失效。","级联与共演化不自带价值方向。紧密耦合可能帮助协同，也可能放大脆弱性和责任扩散；解耦可能牺牲效率，也可能保护自主与止损。知道通道存在，不等于可以利用它操纵人或实施干预。评价和行动仍需规范层对目标、代价、权利、责任及授权作相应判断。"],"distinctions":[{"leftTitle":"消息到达","leftText":"信息已经进入目标的接收位置。","rightTitle":"行动发生","rightText":"目标具备并实际满足采纳、配合及资源条件。"},{"leftTitle":"多次转述","leftText":"可以出自同一个原始依据。","rightTitle":"多源确认","rightText":"须查源头和依赖关系，也不自动等于实际协作。"},{"leftTitle":"故障级联","leftText":"前一处故障经通道触发后一处。","rightTitle":"恢复依赖","rightText":"多项供给共同决定能否恢复，不必彼此造成初始故障。"},{"leftTitle":"共同外因","leftText":"同一暴露造成多处变化。","rightTitle":"相互改变","rightText":"每个对象都改变另一对象后续条件，需分别有材料。"},{"leftTitle":"局部聚类","leftText":"邻居彼此连接的结构特征。","rightTitle":"全网覆盖","rightText":"还取决于种子、桥接、动力规则和行动持续期。"},{"leftTitle":"共演化","leftText":"对象身份分别保留且存在持续相互改变。","rightTitle":"吸收/转换","rightText":"原对象关系或身份发生另类变化，不能只按名字处理。"}],"boundaries":["先一级已证，后一级仍须自己的证据；失败可局部截断，不能全成功或全失败二选一。","来源人数不是天然独立样本数，确认人数也不是在场合作人数。","时间先后是机制识别所需信息之一，单靠先后本身不确证因果边。","人的阈值模型、设施供给约束与同源消息计数具有不同语义，不可换标签后直接复用。","高聚类既可能强化局部接入，也可能损失跨群覆盖；模型和实验均要限定网络、规则与观察对象。","对象合同中的K须分别检查；判据文本没改，不代表对象仍满足判据或仍然独立存在。","故障串传、恢复依赖及共因可以混合，不能强迫每个现实事件只属于一种图。","材料不足的边保持未决，不能把未发现传播当成已证明无传播，也不能把模型可达冒充观察发生。","解释、评价与许可分别负责；没有因为耦合高效而自动产生实施权。"],"questions":["四人转发同一报告，能否直接算四个独立确认来源？","两位协作者各出现一小时，为什么仍可能不能完成需要一小时的协作？","三角柱与完全二分图阈值2模型的最终覆盖分别多少，为什么？","这是否推翻聚类网络可以扩散得更好的真实实验？","多个故障同时存在，最少还要查哪三种解释？","A和B交换信息，但B的信息从不改变A后续条件，是否足以叫共演化？","降低耦合减少传播，是否自动应该解耦？"],"diagramPath":"/reading-assets/S-6-13/figures/section-6-13.png","caseLinks":[{"title":"2010年在线论坛实验：登记行为的传播，不是健康结局","href":"https://ndg.asc.upenn.edu/wp-content/uploads/2016/04/Centola-2010-Science.pdf"},{"title":"2017年飓风后复电：物流供给是恢复的条件","href":"https://www.gao.gov/assets/gao-19-296.pdf"}],"caseNotes":[{"title":"2010年在线论坛实验：登记行为的传播，不是健康结局","text":"Centola把参与者随机分入聚类格网与重连随机网络，保持节点度数；被传播的行为是注册健康论坛。已注册邻居会各自触发邀请。研究报告前者传播更广、更快。这里新增的观察点是不同已采纳邻居的信号及网络结构，不能用消息总转发数替换。","sourceLabel":"Centola 2010，原作者机构公开论文","sourceUrl":"https://ndg.asc.upenn.edu/wp-content/uploads/2016/04/Centola-2010-Science.pdf","sourceLocator":"Science 329（2010），印刷pp.1194—1196的方法与结果；限制pp.1196—1197（PDF第2—5页）","boundary":"匿名参与者不能直接联系；论坛注册不等于健康改善，本文没有证明普遍硬阈值或聚类单调规律。主文已核，补充材料与原始数据未独立核验。","href":"https://ndg.asc.upenn.edu/wp-content/uploads/2016/04/Centola-2010-Science.pdf"},{"title":"2017年飓风后复电：物流供给是恢复的条件","text":"GAO在2019年报告依据文件和访谈列出恢复障碍：飓风后波多黎各及美属维尔京群岛港口、机场无电，影响修复材料运入；多地同时恢复也加大材料需求并造成供应紧张。本节新增关注恢复资源接续，而非重复复电比例。","sourceLabel":"美国政府问责局GAO，2019-04-18报告","sourceUrl":"https://www.gao.gov/assets/gao-19-296.pdf","sourceLocator":"GAO-19-296，印刷pp.18—19“Logistical challenges”“Availability of materials”（PDF第22—23页）","boundary":"报告支持恢复中的物流与材料约束，不能据此断言每个初始故障都逐跳传播，或把人的多源采纳阈值代入电力与物流；未独立重建完整因果网络。","href":"https://www.gao.gov/assets/gao-19-296.pdf"}],"sourceRefs":[{"section":"6.13","start_line":1447,"end_line":1460,"startLine":1447,"endLine":1460}],"outputId":"section-6-13","sourceHash":"df579dbdbb68442b1781b066606c267761f0a1673fbd034ce93eeeb41641439f","argumentSteps":["固定要解释的变化、起点、目标对象和窗口，分别登记每一级的状态与尺度。","识别每条边实际传播的是消息、资源、行为还是规则；给出通道和使能条件。","逐跳核起点变化、到达、目标响应与竞争解释；在尚未核到的桥处保留未决，不自动续接。","对多源主张查原始来源、依赖关系与落点；对合作主张查人员、时间、持续期及可行条件。","分开故障串传、联合恢复依赖和共因暴露；必要时同时建图，但不互换边的含义。","把聚类、连接数和最短路放回已声明的动力规则；模型计算只能证明该模型内的结果。","声称共演化时核双方独立对象合同、相互改变和持续窗口，排除单向、共同外因与吸收。","报告截断点、局部已知与范围外未知；评价或现实动作另走规范与授权责任。"],"teachingExamples":[{"title":"教学构造：三条转述、两次确认与一个行动窗口","text":"虚构目标T收到P、Q、R三条消息，但溯源均来自同一记录O。若规则要求两个不同原始核查来源，当前来源数为1，三次到达仍未达标。后来新增来源V，来源计数才为2；这也不满足另一项“双人同时协作”规则。设行动窗口为[0,3)，人员P只在[0,1)可用，Q只在[2,3)可用，二者可用时段交集为空，行动不能按该规则开始。若Q改为[0.5,1.5)，交集为[0.5,1)，只有0.5单位；需要连续1单位仍失败，需要0.5单位则在其余条件满足时可行。","assumptions":"虚构规则把来源去重、人员可用、持续时间分别定义；时间为抽象单位，安全、设备与授权仅在最后的可行判断中假设满足，不声称实际发生。不同来源也不额外假定统计独立。","boundary":"只证明到达、确认、协作互不等价；不能把两个来源或0.5时间单位当现实普遍阈值。"},{"title":"数学构造：同为六节点、三度网络，高聚类仍可能停在半网","text":"取六节点0—5，均为无向简单图。图P为三角柱：边01、12、20、34、45、53，以及03、14、25；图B为完全二分图，分区{0,1,2}与{3,4,5}，所有跨区边存在、区内无边。两图都连通、各有9边、每点度3。定义局部聚类系数为该点三个邻居间已有边数除以3。P中每点邻居间恰有1边，故平均聚类为1/3；B中为0。设初始激活集A₀={0,1}，同步永久激活规则Aₜ₊₁=Aₜ∪{v:|N(v)∩Aₜ|≥2}。P中第一轮只有节点2新激活，A₁={0,1,2}；另一三角形的每点只收到一条跨群接入，此后不再增加，最终3点。B中第一轮3、4、5各接到0和1两点，A₁={0,1,3,4,5}；第二轮2得到三个激活邻居，最终6点。因而更高聚类并不保证这个复杂阈值模型的更大全网覆盖。P的节点2在第一轮受到局部强化，B的节点2到第二轮才激活，也说明局部先行与全网成功不同。","assumptions":"阈值2、种子位置、同步更新、永久激活均为明确教学假设；所有节点身份固定，无外来种子、无衰退。此构造可精确枚举，不是人员实验数据。","boundary":"反驳的是无条件“越聚类越覆盖”的规则。两拓扑还改变了跨群落点，不能把差异归为一个独立受控的聚类系数因果效应；也不否定Centola在其设计下的研究结果。"},{"title":"数学构造：三种“多处出问题”的不同方程","text":"串传模型令故障位aₜ恒为1，bₜ₊₁=aₜ，cₜ₊₁=bₜ，初始(a₀,b₀,c₀)=(1,0,0)，得到(1,1,0)、(1,1,1)，故障逐跳进入。恢复模型用p、q表示两项资源可用，恢复可行位r=p∧q：00、01、10时r均为0，11时r=1；这没有声明p故障造成q故障。共因模型令外部冲击u决定a=u、b=u：u=1时两者同故障，仍没有a→b。三模型都能出现两个故障位同时为1，却有不同解释。","assumptions":"二值、确定性规则用于逻辑区分；串传例无修复，恢复例假设两资源为必要且联合充分条件，共因例忽略其他路径。r是本模型的恢复可行位，不是现实已经执行的证据。","boundary":"实际事件可能同时含三机制，不能仅凭横截面状态选择其中一个；模型方程也不自行证明现实因果方向。"},{"title":"教学构造：双向信息线不够，共同冲击也不够","text":"虚构两个独立组织A、B各保留完整对象合同。A改变排程，使B可用资源时段改变；B据此改变供给安排，随后确实改变A下一轮可选排程，才提供一段相互改变的候选机制。若B的回信被归档而从未进入后续排程，则只有通信返回；若两者只因同一个外部停运令同步停工，则先核共同外因；若B已经失去独立对象身份而成为A内部单元，则改查嵌套或对象转换。","assumptions":"完全虚构的条件比较，所谓“确实改变”是构造假设；现实须核版本、执行、替代解释及双方身份，不用两条画线替代。","boundary":"不认定真实组织发生过共演化，不从机制可行推出任何组织重组的规范正当性。"}],"counterexamples":[{"identity":"constructed_boundary","text":"网络有一条最短路径，因而必须能完成多人同时行动。","effect":"消息路径没有给出合作重叠窗口、持续期与行动条件。","sourceIds":["theory"]},{"identity":"constructed_boundary","text":"三份转述都来自O，但把它们算作三份独立确认。","effect":"来源重复使确认数量虚增；逐次到达仍可是真实事实。","sourceIds":["theory"]},{"identity":"constructed_boundary","text":"三角柱的平均聚类1/3高于完全二分图0，所以阈值2扩散一定覆盖更多。","effect":"给出的同节点数、同度、同边数且都连通的模型得3对6，足以限制无条件推广。","sourceIds":["theory"]},{"identity":"constructed_boundary","text":"港口断电阻碍修复材料送达，所以港口一定造成了电网的初始损坏。","effect":"恢复约束不能倒写成初始故障原因；需分别核时序与通道。","sourceIds":["gao-recovery"]},{"identity":"constructed_boundary","text":"两个对象同时变化，或已经被吸收成一个对象，所以共演化已证。","effect":"共同外因和身份转换分别需要检查，不能由同步或合并推出双对象相互改变。","sourceIds":["theory"]}],"questionAnswers":[{"question":"四人转发同一报告，能否直接算四个独立确认来源？","answer":"不能；先去重原始依据并查来源关系。四次转发的到达事实可保留，独立支持不能凭人数累加。","basis":"本节原文及上述公开推导"},{"question":"两位协作者各出现一小时，为什么仍可能不能完成需要一小时的协作？","answer":"如果可用时段不重叠，联合持续期为0；即使重叠半小时，也达不到一小时要求。总出现时间不能代替同时条件。","basis":"本节原文及上述公开推导"},{"question":"三角柱与完全二分图阈值2模型的最终覆盖分别多少，为什么？","answer":"分别3和6。前者另一三角形每点只接一条已激活跨群边，停住；后者三个对侧节点第一轮都接到两个种子，第二轮再激活剩余节点。","basis":"本节原文及上述公开推导"},{"question":"这是否推翻聚类网络可以扩散得更好的真实实验？","answer":"不推翻。教学模型给出另一组拓扑、种子和确定性规则的反例；实验保留其设计和行为指标下的有限结果，两者都不能自动变成普遍定律。","basis":"本节原文及上述公开推导"},{"question":"多个故障同时存在，最少还要查哪三种解释？","answer":"逐跳故障触发、多个条件共同阻碍恢复、共同外因暴露；查时序、资源依赖和共因材料，现实允许并存。","basis":"本节原文及上述公开推导"},{"question":"A和B交换信息，但B的信息从不改变A后续条件，是否足以叫共演化？","answer":"不足。通信返回未形成有效相互改变；还须核独立对象身份、持续窗口及两向的实际作用。","basis":"本节原文及上述公开推导"},{"question":"降低耦合减少传播，是否自动应该解耦？","answer":"不能。还要比较损失的协同、资源代价、权利和责任，按规范与授权条件判断；机制效果不替代行动理由。","basis":"本节原文及上述公开推导"}],"figures":[{"path":"/reading-assets/S-6-13/figures/section-6-13.png","alt":"逐跳故障，A故障 → B故障 → C故障，核每一跳的时序与通道；恢复依赖，资源P与资源Q → 恢复可行R，两项同时到位；不推P导致Q；共同外因，冲击U → A故障；U → B故障，核共同暴露；不自动有A→B。教学机制图。左为逐跳作用，中为联合必要条件，右为共同外因；三图可以并存，不能凭多个故障同在就任选解释。","caption":"教学机制图。左为逐跳作用，中为联合必要条件，右为共同外因；三图可以并存，不能凭多个故障同在就任选解释。"}],"diagramBrief":"当前交付为静态图；交互尚未实现，以下涉及选择、切换或点击的内容仅为后续设计设想。三面板分别画出串传、联合恢复条件与共同外因，旁列本讲二值规则。若后续制作交互，可改变恢复资源或外部冲击并显示不同结果；当前仅静态图。","applicability":{"realCase":"applicable","diagram":"applicable","reason":"真实社会传播实验与灾后物流恢复分别说明行为接入和供给依赖，身份分开；模型只解释条件差异。"},"openQuestions":["具体圈层的每一跳还需对象、通道、时间与替代解释材料；未提供现实个案的完整级联识别或共演化认证。","Centola主文支持其有限实验结果；本讲未独立获取补充材料和原始数据，也未开展新的参与者或读者实验。","实际解耦、资源调配或组织变化的授权与规范评价未在本讲作出。"],"taskId":"S-6-13","sources":[{"id":"theory","title":"Xikari-条件结构与转化论，用户提供原文","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"现行全文第1447—1460行；每节精确范围见sourceRefs","claim_support":["6.13：术语、合同、论证责任和原文边界；不据此认证经验事实"],"limits":["作者理论文本，是被解释对象，不替代外部经验资料；技能5.3.1不等于理论版本。"],"access_status":"read"},{"id":"centola-2010","title":"Damon Centola: The Spread of Behavior in an Online Social Network Experiment","url":"https://ndg.asc.upenn.edu/wp-content/uploads/2016/04/Centola-2010-Science.pdf","source_type":"primary","version_or_date":"2010-09-03，DOI 10.1126/science.1185231","locator":"Science 329(5996),1194—1197；方法pp1194—1195，结果p1196，设计限制pp1196—1197","claim_support":["6.13真实案例：随机网络条件、保持度数、论坛注册指标、每个已注册邻居各触发信号；聚类条件传播更广更快。","6.13支持边界：匿名且无直接联系，现实高成本行为的推广在原文中属于预期或待进一步研究。"],"limits":["只核主文，不声称已核补充材料或原始数据；不将登记行为当健康结局，不追授正式G实例或普遍阈值。"],"access_status":"partially_read"},{"id":"gao-recovery","title":"GAO-19-296: 2017 Hurricane Season—Federal Support for Electricity Grid Restoration in the U.S. Virgin Islands and Puerto Rico","url":"https://www.gao.gov/assets/gao-19-296.pdf","source_type":"primary","version_or_date":"2019-04-18","locator":"印刷pp18—19；PDF第22—23页，物流挑战与材料可用性两小节","claim_support":["6.13真实案例：文件和访谈所记录的港口/机场断电导致材料运输受阻，以及多地修复的材料需求与供应限制。"],"limits":["这些材料支持恢复约束，不单独识别所有初始故障的传导网络；本讲未重建个别设施的完整因果链。"],"access_status":"partially_read"},{"id":"theory-object","title":"Xikari3.1：D0对象合同与K身份判据","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"第425—448行，特别429、447行","claim_support":["6.13：完整对象合同与其中的同一性判据K不同，两个对象的身份与适用范围须分别检查。"],"limits":["定义不替代现实对象识别。"],"access_status":"read"},{"id":"theory-coevolution","title":"Xikari6.9—6.10：共演化与身份转换","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"第1412—1425行","claim_support":["6.13：双向作用、共同外因、返回未起作用及吸收/修复边界。"],"limits":["并行变化不是自动双向因果。"],"access_status":"read"},{"id":"theory-conversion","title":"Xikari4.6：G4转换登记","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"第642—650行","claim_support":["6.13：描述性变化与正式转换资格不能混同。"],"limits":["本讲未提交现实G4实例。"],"access_status":"read"}],"lecturePath":"/reading-assets/S-6-13/lecture.md","sourcesPath":"/reading-assets/S-6-13/sources.json","sourceSlicePath":"/reading-assets/S-6-13/source-slice.md","supplementaryFiles":[],"diagramsPath":"/reading-assets/S-6-13/diagrams.md"}}},"headers":[],"relativePath":"theory/part-06.md","filePath":"theory/part-06.md"}'),d={name:"theory/part-06.md"};function l(u,e,p,_,m,h){const t=r("SectionLesson");return o(),n("div",null,[e[0]||(e[0]=s('<div class="theory-source"><p><a id="part_6"></a></p><h1 id="part-title-6" tabindex="-1"><span class="xk-part">第六部分<span class="xk-part__gap">　</span></span>运转与演化 <a class="header-anchor" href="#part-title-6" aria-label="Permalink to &quot;第六部分　运转与演化 {#part-title-6}&quot;">​</a></h1><p>本部分把对象合同展开为过程解释。运转、反馈、学习、维护、负荷、相位与筛选不是一组可以互换的叙事词，而是具有不同推理前提、使能条件、反事实和停止位置的条件机制。机制名称本身不构成充分条件；只有依赖、条件、最低证据和竞争解释同时通过，才能在指定 SP/T/K 内登记一个机制实例。</p></div>',1)),a(t,{section:"intro-06-part"}),e[1]||(e[1]=s('<div class="theory-source"><h2 id="section-6-1" tabindex="-1"><span class="xk-num"><span class="xk-num__n">6.1</span><span class="xk-num__gap">　</span></span>运转登记 <a class="header-anchor" href="#section-6-1" aria-label="Permalink to &quot;6.1　运转登记 {#section-6-1}&quot;">​</a></h2><p>一次运转至少登记输入、指定载体或通道、状态转移、输出、环境条件、时间窗和可能留痕。若输出返回，还要登记返回通道、接收位置和被改变字段；若主张跨期作用，先按§4.5区分历史形成、当前载体传递与额外历史增量，并核对各自的时间和机制材料；只有额外历史增量主张需要比较历史感知模型与当前状态充分模型；若跨尺度，还要完成 D3/E5 映射。这样的登记不是把复杂过程强行压成线性链，而是让每一处时延、损耗、替代通道、证据断点和外推边界可被检验。</p></div>',1)),a(t,{section:"6.1"}),e[2]||(e[2]=s('<div class="theory-source"><h2 id="section-6-2" tabindex="-1"><span class="xk-num"><span class="xk-num__n">6.2</span><span class="xk-num__gap">　</span></span>CM-FEEDBACK 有效反馈 <a class="header-anchor" href="#section-6-2" aria-label="Permalink to &quot;6.2　CM-FEEDBACK 有效反馈 {#section-6-2}&quot;">​</a></h2><p>推理依赖：D2、G2。 E4、CAUSAL 与 EVIDENCE 是方法门，不是额外经验原因。有效反馈不以 G3 为前提。</p><p>使能条件是：先前状态或输出经已由 G2-instance 识别的指定返回通道进入后续过程；相对于无返回或阻断条件，至少一个后续状态、转移概率或约束发生超过阈值的差异；时间顺序和被改变字段在结果前已登记。机制链为：</p><p>先前状态或输出 → 返回信号 → 指定通道传导 → 接收位置摄取 → 后续状态、概率或约束改变 → 阻断反事实复核</p><p>最低证据包括通过预注册门的 G2-instance、返回通道与接收位置、时间顺序、被改变字段、后续差异，以及无返回或通道阻断比较。信号到达但后续转移不变，变化由独立共同输入解释，或切断返回通道后差异仍保持不变时，不登记有效反馈。有效反馈只说明返回造成了一次后续改变；它不等于学习、修复、正向结果，也不要求持久历史留痕。</p></div>',1)),a(t,{section:"6.2"}),e[3]||(e[3]=s('<div class="theory-source"><h3 id="section-6-2-1" tabindex="-1"><span class="xk-num"><span class="xk-num__n">6.2.1</span><span class="xk-num__gap">　</span></span>反馈时延与稳定区间 <a class="header-anchor" href="#section-6-2-1" aria-label="Permalink to &quot;6.2.1　反馈时延与稳定区间 {#section-6-2-1}&quot;">​</a></h3><p>一个可自含分析的局部模型是 x_{t+1}=x_t−k x_{t−d}。其中x_t为相对目标的有符号、无量纲偏差，k为固定实数增益，d为固定非负整数延迟，采样步长固定；模型没有外部冲击、测量噪声、执行饱和或状态边界。对所有有限初始历史，零解渐近稳定的充要条件是 0&lt;k&lt;2sin[π/(4d+2)]，等号不包含在稳定区内。证明见附录C.10。</p><p>例如固定k=0.8、初始历史全部为1，延迟0或1步时渐近稳定，延迟2或3步时不稳定；四种情形第一步都由1变为0.2，而阻断通道k=0时保持1。这个模型由此同时给出反馈有效和稳定失效的实例。越过稳定边界表示存在不衰减或增长模态，不表示包括零历史在内的每条轨迹都增长。</p><p>稳定性不保证每步偏差下降、瞬态峰值可接受或执行代价可承受。x_t可为负只表示越过目标，不是负任务数量；现实队列的非负性、需求、异质服务、策略反应与权限均未被该式建模。把这个判据用于现实流程前，需要独立测量和模型验证，不能据此设定未经识别的现实纠偏增益。</p></div>',1)),a(t,{section:"6.2.1"}),e[4]||(e[4]=s('<div class="theory-source"><h2 id="section-6-3" tabindex="-1"><span class="xk-num"><span class="xk-num__n">6.3</span><span class="xk-num__gap">　</span></span>CM-LEARNING 反馈介导学习 <a class="header-anchor" href="#section-6-3" aria-label="Permalink to &quot;6.3　CM-LEARNING 反馈介导学习 {#section-6-3}&quot;">​</a></h2><p>基础推理依赖：CM-FEEDBACK。E4、CAUSAL 与 EVIDENCE 是方法门。反馈介导学习要求返回造成可保留更新，该更新实际进入后续任务；当前载体传递与当前表示之外的历史增量是两个分别取证的分支。</p><p>CM-LEARNING-carried 是载体分支。使能条件为：有效反馈改变可定位的内部状态、参数、规则、记忆或结构；更新经明确载体保留或持续更新，并在重复轮次中实际调用；相对于预先声明的基线或替代过程，后续预定任务出现可复核差异。因果主张须有中断、替换、恢复或具备识别条件的比较，并处理共同输入、持续训练、选择、失访与测量改变。主张迁移或预测增益时，另需与该主张相称的独立任务或样本外评价。机制链为：</p><p>有效反馈 → 可定位的内部更新 → 更新载体保留或持续更新 → 后续轮次实际调用 → 预定任务结果改变</p><p>一次参数变化、一次成功、一次写回或材料归档都不足以证明这条学习机制。更新未保留、未被后续调用、任务结果仅由共同输入解释，或只改变代理指标而未触及预定任务时，相应机制主张未获支持。有效反馈、一般学习、跨情境迁移和净收益分别判断；学习成立也不表示变得更好、拥有统一目标或取得行动授权。</p><p>目标本身发生改变时，应说明形成新目标的理由与决定程序，保留旧目标下的结果、失败和成本，再为新任务建立比较。不能用后来重构的目标把旧任务失败改写为成功。</p><p>一般学习可以由相应领域的证据得到支持，例如可重复完成的新任务、保留并调用的技能、可追查的教学或组织过程。它不必先取得本框架的正式机制实例身份。报告可以同时说明“做法已改变”“后续净效果尚未确定”“反馈介导机制尚未识别”，不将几种判断压成一个通过或失败。〔研究16.02、25.01—25.08、31.08〕</p><p>学习评价还应区分支持下完成任务、撤除支持后的独立迁移与后续生活结果。必要支持可以构成表达或协作任务的组成部分，此时无支持失败不取消已有成功；原目标若是独立迁移，则需相称的撤援比较。选择目标、确认更新保留、测量任务表现和判断净收益分别承担责任，不能用支持仍在否认功能获得，也不能把辅助成绩替代独立技能。</p><p>CM-LEARNING-history 是历史增量分支：在载体更新、重复调用与任务比较之外，还须由 G3-instance 支持相对于明示当前表示的额外历史条件增量。当当前载体充分保留所学内容时，这一增量可以消失，而载体学习仍然成立。不得删去已知当前载体制造增量，也不得在结果后改换分支救援原检验；两条路线分别声明比较、反例与失败条件。</p></div>',1)),a(t,{section:"6.3"}),e[5]||(e[5]=s('<div class="theory-source"><h2 id="section-6-4" tabindex="-1"><span class="xk-num"><span class="xk-num__n">6.4</span><span class="xk-num__gap">　</span></span>反馈、制度写回与学习的虚拟申诉例 <a class="header-anchor" href="#section-6-4" aria-label="Permalink to &quot;6.4　反馈、制度写回与学习的虚拟申诉例 {#section-6-4}&quot;">​</a></h2><p>设一个虚拟制度收到申诉。本例只展示分类方法，不引用现实材料，也不构成外部经验证明。</p><p>申诉被收件并生成回执，但记录、规则、资源、角色、责任、记忆和停止条件均未改变：这是信号到达，不是有效反馈，也不是制度写回。</p><p>申诉经指定通道使案件状态字段改变，但改变没有进入执行：这可以是 D2 意义上的有效反馈，却仍不是 H3 意义上的完整制度写回。</p><p>字段变化进入实际执行，并记录受理、字段变化、执行和持续时间：这是一次制度写回。写回事实不证明制度正当，也不等于长期修复。</p><p>当该写回形成可保留规则或状态更新，进入后续多轮相似案件，并有相应任务比较和因果依据时，可以提出载体型反馈介导学习候选；若另要主张当前状态之外的历史条件增量，再由 G3-instance 独立检验。</p><p>因此，反馈不等于学习，写回也不等于学习。三者的证据门逐级增加，不能因制度拥有申诉入口或公开回应就一次性跨越。</p></div>',1)),a(t,{section:"6.4"}),e[6]||(e[6]=s('<div class="theory-source"><h2 id="section-6-5" tabindex="-1"><span class="xk-num"><span class="xk-num__n">6.5</span><span class="xk-num__gap">　</span></span>CM-MAINTENANCE 维护与存护—消解 <a class="header-anchor" href="#section-6-5" aria-label="Permalink to &quot;6.5　CM-MAINTENANCE 维护与存护—消解 {#section-6-5}&quot;">​</a></h2><p>基础推理依赖：D0、G2。 E4、CAUSAL 与 EVIDENCE 是方法门，D1 提供状态词特化。维护要求预先声明当前 K 或功能判据 F 与维护窗口；补给、替换、校正或清除必须经 G2-instance 识别为改变 K/F 保持的指定通道；还要比较维护、减维护、错配维护与停止维护条件。</p><p>机制链为：</p><p>磨损、漂移、损耗或组件退出 → 指定维护通道 → 补给/替换/校正/清除 → K/F 保持时间或失效概率改变</p><p>CM-MAINTENANCE-current 检查维护输入对当前 K/F 保持的作用。CM-MAINTENANCE-carried-cumulative 另依§4.5核对当前磨损或能力载体、此前输入如何形成它、跨窗保留或补给，以及维护改变后续保持的纵向和因果证据。CM-MAINTENANCE-cumulative 是历史增量型分支，只有主张当前表示之外的历史条件增量时追加 G3。对象在目标窗口内无需持续维护仍保持 K/F、维护输入变化不改变相关结果，或所谓磨损由独立冲击解释时，应收窄或撤回相应维护主张。原 K 已改变却继续沿用旧维护判据，也属于合同失效。</p><p>维护需要不等于对象应永久存续，维护通道存在也不能直接指定具名承接者、责任或牺牲义务。错配维护可能延长旧 K 却破坏目标 F；有序停止、对象转换或解体也可能是合同允许的结果。</p><p>维护分析还要区分正常运行、迁移、故障和恢复中的任务。接口标准规定可能的互通条件，实际兼容仍取决于实现版本、业务语义、环境与负荷、测试及现场适配；零件存在也不等于规格合适、质量可验、人员能到场或有权停机。维护工作的增加可能发生在原对象之外，由用户、家庭、外包人员或其他机构补上，不能只以中心工单和运行输出估计维护总量。</p><p>冗余按失效条件检验，不能只数备用数量。两条路径可能共用电源、软件状态、运输通道、供应商、操作者或同一审批节点；正常时可替代，也可能在故障时同时失效。应分别核实备用容量、共因暴露、切换所需时间、现场技能和实际切换权，并将恢复过程所依赖的通信、道路、燃料、备件和人员纳入同一窗口。增加备份、降低耦合或保留局部独立运转都只是候选方案，其净效应依具体故障及维护成本判断。</p></div>',1)),a(t,{section:"6.5"}),e[7]||(e[7]=s('<div class="theory-source"><h2 id="section-6-6" tabindex="-1"><span class="xk-num"><span class="xk-num__n">6.6</span><span class="xk-num__gap">　</span></span>CM-LOAD 负荷、容量与恢复 <a class="header-anchor" href="#section-6-6" aria-label="Permalink to &quot;6.6　CM-LOAD 负荷、容量与恢复 {#section-6-6}&quot;">​</a></h2><p>基础推理依赖：D0、G2。 E4、CAUSAL 与 EVIDENCE 是方法门。需求与容量必须是同型量，或具有明确单位与转换映射；需求、可用容量、补给和溢出按同一窗口、同一位置测量；G2-instance 只支持已测通道及其相关维度。</p><p>机制链为：</p><p>同型需求进入指定通道 → 占用可用容量 → 形成即时缺口或跨边界溢出 → 减载/补给/扩容改变缺口；若要解释后续累积或迟恢复，另核损伤、容量或恢复载体及其跨窗作用。</p><p>CM-LOAD-instant 只登记同型需求—容量与同窗即时缺口。CM-LOAD-carried-cumulative 依§4.5核对历史暴露形成当前损伤或容量状态、该状态跨窗保留或恢复，以及后续结果与比较条件；因果主张须有相称识别依据。CM-LOAD-cumulative 是历史增量型分支，另由 G3 检验当前表示之外的条件增量。容量同步扩展可以吸收需求；瞬时缺口解除后也可能没有持久差异，因此负荷不必单调累积，瞬时过载不必导致损伤或崩溃。</p><p>负荷必须按位置与分布登记，不能只报告平均值；容量要区分峰值、持续值、替代通道与补给；恢复要区分表面输出恢复、K/F 恢复和内部余量恢复。不同类型量不能直接相减，恢复需求也不能直接生成任何主体的牺牲义务或授权。</p><p>恢复判断应同时说明恢复了什么、对谁、在什么支持条件下以及截至何时。实际输出的数量、质量、持续性与可达性，内部人员休整、备件、维护积压和资金接续，边界外新增的照护、通勤、借款或替代服务负担，以及后续中断和近失误，分别取证。灾前人口、当前人口、符合资格者和实际使用者不能在计算恢复比例时默默互换。对某项有限功能的确认，不要求其他全部结果同时恢复。</p><p>临时场所、持续外援或辅助设备可以构成真实的功能修复；依赖支持本身不是恢复失败。应核实支持的可持续性、到期点与替代承接是否已运行，并明确尚未经历的需求高峰、维护周期或季节性暴露。所谓假恢复，只宜指声明超出了证据支持的对象、人群、功能或持续条件，不由此推定欺骗。恢复后的再次失稳须分别比较旧损伤延续、储备未补回、支持中断、新冲击与测量口径改变，不能用一次新失败抹去此前准确限定的成果，也不能为验证恢复而撤走必要支持。</p></div>',1)),a(t,{section:"6.6"}),e[8]||(e[8]=s('<div class="theory-source"><h2 id="section-6-7" tabindex="-1"><span class="xk-num"><span class="xk-num__n">6.7</span><span class="xk-num__gap">　</span></span>CM-PHASE 相位与阈值转换 <a class="header-anchor" href="#section-6-7" aria-label="Permalink to &quot;6.7　CM-PHASE 相位与阈值转换 {#section-6-7}&quot;">​</a></h2><p>基础推理依赖：D0、D1。 E4 与 EVIDENCE 是相位模式分支的共同方法门；对因果触发、载体持续机制或历史增量型迟滞提出因果解释时，追加CAUSAL；它不是基础模式分类的前置门，单纯预测性历史增量也不因此升级为因果。相位的基础识别不要求 G3：同一候选对象合同和 K 下，只要预先登记状态变量、候选参数或触发条件、阈值，以及噪声和分箱稳健性，就可以检验至少两个可重复区分的运转区间。</p><p>机制判断分为以下分支：</p><p>CM-PHASE-pattern：相位模式。 条件为“同一K、两个可复核区间、预定阈值模式”。它只登记区间—阈值关系，不宣称触发因果。</p><p>CM-PHASE-causal-trigger：因果触发。 条件为“指定触发通道、通道干预或可识别自然变异”，并另加 G2-instance 定位触发作用。</p><p>CM-PHASE-carried-persistence 检查当前载体如何在同一 K 下维持相位、跨窗持续或迟恢复；依§4.5取得载体、时序、纵向比较及相称因果证据。CM-PHASE-hysteretic 限定为历史增量型迟滞分支，另以 G3-instance 检验当前表示之外的条件增量。相同曲线形状不能替任一路线取证。</p><p>连续趋势若在同一状态分布内充分解释变化、阈值随分箱任意移动，或转移前 K 已失效，应撤回相位结论，分别改记为连续变化、测量划分效应或对象转换/解体。可逆相位不必具有历史路径；只有历史增量型迟滞分支才追加 G3。相位也不构成 S0—S6 的必经成熟序列，新相位不因此更高、更好或拥有更大授权。</p></div>',1)),a(t,{section:"6.7"}),e[9]||(e[9]=s('<div class="theory-source"><h2 id="section-6-8" tabindex="-1"><span class="xk-num"><span class="xk-num__n">6.8</span><span class="xk-num__gap">　</span></span>CM-SELECTION 变异—差异保留—再生产 <a class="header-anchor" href="#section-6-8" aria-label="Permalink to &quot;6.8　CM-SELECTION 变异—差异保留—再生产 {#section-6-8}&quot;">​</a></h2><p>基础推理依赖：D1。 E4、CAUSAL 与 EVIDENCE 是方法门。该机制是独立操作化，不由“发生演化”这个定义自动推出，也不能由概念说明或框架叙述直接证明。</p><p>必须把三种输出分开：</p><p>CM-SELECTION-pattern：筛选模式。 条件为“V、D、R、下一轮、重复轮次、漂变竞争”：结果前定义可区分变异 V 及来源，在可比环境中观察超过阈值的差异结果 D，差异经保留 R 进入下一轮并在重复轮次中可复核，同时检验漂变、共同外因和抽样偏差。基础依赖只有 D1。</p><p>CM-SELECTION-carrier：具体机制。 条件为“指定保留或再生产通道、通道扰动或可识别自然变异”，在模式成立之外另加 G2-instance 定位承载机制。</p><p>CM-SELECTION-history：跨轮路径。 条件为“跨轮历史项条件增量、当前状态控制”，在模式成立之外另加 G3-instance。</p><p>只有变化而无 D，是变动；有一次差异而无 R、下一轮和重复轮次，是一次结果；漂变模型已经充分时，不登记筛选模式；候选再生产通道被扰动而保留不变时，不登记该具体机制。一次存续不等于差异保留，被保留者不因此更优、更高级或更正当。系统筛选不是行动主体选择，更不是集体治理选择：后两者分别需要主体、选项与决策证据，以及规范前提、J 轴授权和 O 程序。</p></div>',1)),a(t,{section:"6.8"}),e[10]||(e[10]=s('<div class="theory-source"><h2 id="section-6-9" tabindex="-1"><span class="xk-num"><span class="xk-num__n">6.9</span><span class="xk-num__gap">　</span></span>共演化的条件 <a class="header-anchor" href="#section-6-9" aria-label="Permalink to &quot;6.9　共演化的条件 {#section-6-9}&quot;">​</a></h2><p>当两个候选对象相互改变对方的环境、可行路径、指定通道或保留条件，并且双向作用在各自时间窗内可追踪时，可以提出共演化候选。必须分别登记两个对象的 D0 合同与 K、各自 SP/T、双向 G2 通道、时间顺序、速度差异和第三方共同环境；跨轮载体作用依§4.5分别取证；只有主张当前表示之外的历史条件增量时，才分别追加相应 G3-instance。</p><p>共同变化、同步波动或长期相关不能替代双向机制。单向依赖、共同冲击和测量协议同步都是必要的竞争解释。共演化也不表示双方对称、互利、价值一致或负有继续维持关系的义务。</p><p>同终态不是同机制。两个过程可以收敛到相同固定点，却具有不同的更新规则、回归速度、瞬态和干预响应；只问长期终值时，较简表示可能充分，改问到达期限或定向操作时，原结论不自动延伸。恢复、共演化和跨圈层接续均须按所问目标保留这些差异，而不以曲线趋同替机制识别。</p></div>',1)),a(t,{section:"6.9"}),e[11]||(e[11]=s('<div class="theory-source"><h2 id="section-6-10" tabindex="-1"><span class="xk-num"><span class="xk-num__n">6.10</span><span class="xk-num__gap">　</span></span>解体、对象转换与修复边界 <a class="header-anchor" href="#section-6-10" aria-label="Permalink to &quot;6.10　解体、对象转换与修复边界 {#section-6-10}&quot;">​</a></h2><p>解体以原 K 不再成立为判据。若原 K 失效但另一个对象合同可以成立，应区分对象转换与终止；相位变化只有在原 K 保持时才与解体分开。解体不自动等于失败，存续也不自动等于成功。</p><p>修复以结果前公开的目标 K* 或 F* 为判据。它可以利用旧痕迹，也可以改变组件、边界、关系、接口、载体和尺度位置；它不是把时间倒回旧状态。若主张存在修复窗口，除了 K*/F*，还需比较不同时点介入对目标可达性与成本的影响；历史形成的当前限制按载体路线取证；主张当前表示之外的历史条件残差才另需 G3。即使这些经验条件成立，目标是否正当、由谁选择、谁负责任以及谁可实施，仍须由 N 层、J 轴和 O1—O4 审查。</p></div>',1)),a(t,{section:"6.10"}),e[12]||(e[12]=s('<div class="theory-source"><h2 id="section-6-11" tabindex="-1"><span class="xk-num"><span class="xk-num__n">6.11</span><span class="xk-num__gap">　</span></span>机制输出总闸 <a class="header-anchor" href="#section-6-11" aria-label="Permalink to &quot;6.11　机制输出总闸 {#section-6-11}&quot;">​</a></h2><p>六个条件机制都必须依次完成对象与尺度声明、推理依赖、使能条件、机制链、最低证据、竞争解释、反例和失效边界。缺项时只保留候选机制或检查问题。反馈不偷带学习，瞬时负荷不偷带累积，基础相位不偷带迟滞，筛选模式不偷带机制或价值，维护和修复也不偷带存续义务。概念说明和教学例只展示合同如何使用，均不构成外部经验支持。</p></div>',1)),a(t,{section:"6.11"}),e[13]||(e[13]=s('<div class="theory-source"><h2 id="section-6-12" tabindex="-1"><span class="xk-num"><span class="xk-num__n">6.12</span><span class="xk-num__gap">　</span></span>异步多时钟的运转 <a class="header-anchor" href="#section-6-12" aria-label="Permalink to &quot;6.12　异步多时钟的运转 {#section-6-12}&quot;">​</a></h2><p>多圈层联合状态至少包含即时、互动、组织、制度和长期时钟。一个事件可以先改变快变量，随后经重复互动改变关系预期，再经组织决策改变资源，最后才可能进入制度写回。若把这些变化压成同一时间点，会把时延误判为无效，或把短时波动误判为长期演化。</p><p>快变量的变化不自动代表长期制度或生活结果。产业扩张、签署协议、停止公开暴力、设施完工或群众合作，都要继续核对执行、分配、权利、关系和持续性；若资料不足，保留局部已知结果并停止远程外推。</p><p>每个机制应声明自己的更新时钟和跨时钟桥。反馈信号到达不等于组织规则已经改变，组织决定不等于制度执行，制度文本变化也不等于每个局部位置已实际写回。跨时钟桥必须给出载体、执行、确认和失效条件。</p><div class="xk-table"><table><thead><tr><th>时钟转换</th><th>最低桥接证据</th><th>常见失败</th></tr></thead><tbody><tr><td>即时→互动</td><td>多个回合中状态差持续并改变对方响应</td><td>单次情绪消退</td></tr><tr><td>互动→组织</td><td>关系或策略变化进入角色、流程、资源或记录</td><td>口头共识未执行</td></tr><tr><td>组织→制度</td><td>可核实的规则或程序变化、责任安排与实际执行；授权、法律有效性和规范正当性分别登记</td><td>只发布文件未执行，或以不合法为由漏记实际发生的制度变化</td></tr><tr><td>制度→长期</td><td>持续执行、维护、学习和替代路径</td><td>短期合规后回弹</td></tr></tbody></table></div><p>这张表登记变化的实际接续，不把合法、正当或已获授权当作事件发生的证明条件。违规、越权或受争议的规则变更与执行，只要有相应事实证据，也须进入过程记录，并另记其授权和合法性状态；解释其形成和后果不等于准许实施。反过来，授权、规则发布或机构宣布完成，也不能代替实际执行证据。</p></div>',1)),a(t,{section:"6.12"}),e[14]||(e[14]=s('<div class="theory-source"><h2 id="section-6-13" tabindex="-1"><span class="xk-num"><span class="xk-num__n">6.13</span><span class="xk-num__gap">　</span></span>跨圈层级联与共演化 <a class="header-anchor" href="#section-6-13" aria-label="Permalink to &quot;6.13　跨圈层级联与共演化 {#section-6-13}&quot;">​</a></h2><p>级联发生在一个圈层的局部变化经成员重叠、桥接接口、共享资源、网络传播或制度下行触发其他圈层变化。每一级都要重新检查对象、通道、尺度和证据，不能因为第一步成立就假定后续全部成立。级联可被容量、过滤、延迟、抵消和局部排除区截断。</p><p>跨圈层传播必须先识别传播的是什么，以及目标发生改变需要什么条件。消息可经单条桥到达，但需要多人实际配合、不同来源确认或足够安全支持的行动，可能在同一网络上停住；同源转述次数不等于独立确认人数，确认人数也不等于实际协作。桥的作用取决于来源关系、落点、到达顺序、行动持续期与可行条件，不能由最短路径、连接数或某个模型阈值直接判定。</p><p>还须区分一处故障触发下一处故障、多个故障共同阻碍恢复，以及共同外因同时损坏多处。前者需要逐跳传导证据，后两者分别检查恢复依赖和共因暴露。人的多源采纳机制与设施之间的供给依赖可以并存，却不能互换状态变量或阈值；复杂传播也不保证聚类越高越有利，其强化收益可能被跨群覆盖的减少抵消。</p><p>共演化要求至少两个对象在一段时间内相互改变对方的选择环境、转移概率或约束，并保留彼此独立的 K。若一个对象只是被另一个吸收，应记录嵌套或对象转换；若只有共同外部环境造成同步变化，不称共演化；若返回信号没有改变后续状态，只称耦合或共同暴露。</p><p>多圈层级联和共演化都不带价值方向。更紧密耦合可能提高协同，也可能扩大脆弱性和责任扩散；解耦可能降低效率，也可能保护局部自主与止损。评价与行动仍交由规范层。</p></div>',1)),a(t,{section:"6.13"}),e[15]||(e[15]=c("div",{class:"theory-source"},null,-1))])}const y=i(d,[["render",l]]);export{g as __pageData,y as default};
